const storage = await openStorage({ databaseUrl: process.env.DATABASE_URL, dataDir: DATA_DIR });
// Every email sent one at a time, and how it went (back office → Outbox; server/outbox.ts).
const outbox = createOutbox({ store: await storage.open("outbox", OUTBOX_PARTS) });
// Sends an email and keeps it in the Outbox. `secret`: what the Outbox shows for an email with a
// code or one-time link in it, kept without its contents. `by`: who sent it from the back office.
async function sendEmail({ secret = "", by = "", again = "", ...m }: { to: any; subject: any; text: any; html?: any; from?: any; kind?: any; replyTo?: any; headers?: any; attachments?: { filename: string; content: Buffer }[]; secret?: string; by?: string; again?: string }) {
  const row = await outbox.record({ ...m, secret, by, again }).catch((error) => (console.error("[outbox]", error.message), null));
  // Marketing, automated emails and outreach skip anyone on the do-not-email list (a bounce, a
  // spam complaint, an unsubscribe); the Outbox says why.
  const held = ["newsletter", "automations", "outreach"].includes(m.kind) && suppressedReason(m.to);
  if (held) {
    if (row) await outbox.failed(row.id, `Not sent: ${held}.`);
    return { id: null, skipped: true };
  }
  try {
    const r = await deliverEmail(m);
    if (row) await outbox.sent(row.id);
    return r;
  } catch (error) {
    if (row) await outbox.failed(row.id, error.message);
    throw error;
  }
}

// Why an address is on the do-not-email list, in a few words (or "" when it isn't).
function suppressedReason(to) {
  try {
    const x = dncOf(String(Array.isArray(to) ? to[0] : to || "").replace(/^.*<|>.*$/g, ""));
    return x ? { bounced: "their email bounced", complained: "they marked an email as spam", unsubscribed: "they unsubscribed", asked: "they asked not to be emailed" }[x.reason] || "on the do-not-email list" : "";
  } catch {
    return ""; // not loaded yet (starting up)
  }
}

