// Posts that ship with the site (content/numeral/*.md, front matter then the post): each is
// published once, the first time the site starts with it. When its file changes later, the post
// follows, as long as nobody has edited it in the back office; once it's been edited there (or
// deleted), the back office version is the one that counts and the file is left alone.
async function publishShippedPosts() {
  const dir = path.join(ROOT, "content", "numeral");
  const files = await readdir(dir).catch(() => []);
  for (const file of files.filter((f) => f.endsWith(".md")).sort()) {
    const key = `numeral:${file}`;
    const raw = (await readFile(path.join(dir, file), "utf8")).replace(/\r\n?/g, "\n");
    const hash = createHash("sha256").update(raw).digest("hex").slice(0, 16);
    let shipped = setting(key)?.value;
    if (typeof shipped === "string") shipped = { id: shipped }; // recorded before changes were followed
    if (shipped?.hash === hash) continue;
    const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(raw);
    if (!m) {
      console.error(`[numeral] ${file}: no front matter, skipped`);
      continue;
    }
    const meta = Object.fromEntries(m[1].split("\n").map((l) => /^(\w+):\s*(.*)$/.exec(l)).filter(Boolean).map((x) => [x[1], x[2].trim()]));
    const fields = { title: meta.title, slug: meta.slug, description: meta.description, image: meta.image, imageAlt: meta.imageAlt, body: m[2].trim() };
    if (!shipped) {
      const post = await notes.create({ ...fields, status: "published" }, { publishedAt: meta.date });
      await saveSetting(key, { id: post.id, hash, at: post.updatedAt });
      console.log(`[numeral] published ${file} at /numeral/${post.slug}`);
      continue;
    }
    const post = notes.list().find((p) => p.id === shipped.id);
    // Untouched since it shipped: its last change is the one the site made (or, for posts shipped
    // before this was recorded, the moment it was created).
    const untouched = post && (shipped.at ? post.updatedAt === shipped.at : Math.abs(Date.parse(post.updatedAt) - Date.parse(post.createdAt)) < 5000);
    if (!untouched) {
      await saveSetting(key, { ...shipped, hash }); // edited or deleted in the back office: theirs now
      continue;
    }
    const updated = await notes.update(post.id, fields);
    await saveSetting(key, { id: post.id, hash, at: updated.updatedAt });
    console.log(`[numeral] updated /numeral/${updated.slug} from ${file}`);
  }
}
await publishShippedPosts();

// Back office → Numeral: drafts, publishing, photos (kept with the newsletter images, at /media/)
// and a preview of the page as it will look.
// The calendar on the site: a free place, held with a name and email (and a confirmation).
async function handleReserve(req, res, id) {
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "reserve", 8)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body;
  try {
    body = await readJson(req, 10_000);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that." });
  }
  try {
    guardForm(req, "reserve", body, { names: [String(body?.name || "")] });
    await checkEmailDomain(String(body?.email || "").trim().toLowerCase());
  } catch (error) {
    if (!(error instanceof SpamError)) throw error;
    if (error.silent) return sendJson(res, 200, { ok: true });
    return sendJson(res, error.status, { error: error.message, code: error.code, wait: error.wait });
  }
  try {
    // With email set up, the place is held until they open the link we send: proof the email is theirs.
    const confirm = emailConfigured();
    const { reservation: r, item, token } = await happenings.reserve(id, body || {}, { confirm });
    if (confirm) {
      const link = `${SITE_URL}/api/calendar/confirm?token=${encodeURIComponent(token)}`;
      const first = firstName(String(r.name));
      const intro = `Hi ${first},\n\nConfirm your ${r.guests === 1 ? "place" : `${r.guests} places`} at ${item.title}, ${reservationWhen(item, r)}. We'll hold ${r.guests === 1 ? "it" : "them"} for 30 minutes.`;
      await sendEmail({ kind: "orders", secret: "Confirm class place", to: r.email, subject: `Confirm your place: ${item.title}`, text: `${intro}\n\n${link}\n\nDidn't ask for this? Ignore this email.\n\n${DATA.SITE.name}`, html: emailHtml(intro, "", { href: link, label: "Confirm My Place" }, { note: "Didn't ask for this? Ignore this email.", contact: false }), replyTo: replyAddress(DATA.SITE.email) });
      return sendJson(res, 201, { ok: true, pending: true, guests: r.guests });
    }
    await reservationConfirmed(r, item);
    return sendJson(res, 201, { ok: true, guests: r.guests, left: happenings.left(item) });
  } catch (error) {
    if (error instanceof HappeningError) return sendJson(res, error.status, { error: error.message });
    throw error;
  }
}

// The link in "Confirm your place": asks first (mail scanners open links), then books it.
async function handleReserveConfirm(req, res, url) {
  if (rateLimited(clientIp(req), "reserve-confirm", 30)) return send(res, 429, "Too many attempts.");
  const token = url.searchParams.get("token") || "";
  const back = `<a class="btn" href="/calendar">Back to the Calendar</a>`;
  if (req.method !== "POST") {
    return emailPage(res, true, "Confirm your place", `<h1>Confirm your place</h1><p>One tap and it's yours.</p><form method="post" action="/api/calendar/confirm?token=${encodeURIComponent(token)}"><button type="submit">Confirm My Place</button></form>`);
  }
  try {
    const { reservation: r, item, already } = await happenings.confirmReservation(token);
    if (!already) await reservationConfirmed(r, item);
    const places = r.guests === 1 ? "a place" : `${r.guests} places`;
    return emailPage(res, true, "You're in", `<h1>You're in</h1><p>You have ${places} at ${escapeHtml(item.title)}, ${escapeHtml(reservationWhen(item, r))}. The details are in your email.</p><a class="btn" href="/api/calendar/${item.id}.ics">Add to Calendar</a>`);
  } catch (error) {
    if (!(error instanceof HappeningError)) throw error;
    return emailPage(res, false, "Link expired", `<h1>${escapeHtml(error.message.split(".")[0])}</h1><p>${escapeHtml(error.message.split(".").slice(1).join(".").trim() || "")}</p>${back}`);
  }
}

// A place is booked: "You're in" to them (with the calendar links), and a note to the shop.
async function reservationConfirmed(r, item) {
  const date = reservationWhen(item, r);
  const where = [item.place, item.address].filter(Boolean).join(", ");
  const lines = [`Hi ${firstName(String(r.name))},`, "", `You have ${r.guests === 1 ? "a place" : `${r.guests} places`} at ${item.title}.`, "", date, where, "", `Add it to your calendar: ${SITE_URL}/api/calendar/${item.id}.ics${r.slot ? `?slot=${encodeURIComponent(r.slot)}` : ""}`, `Google Calendar: ${SITE_URL}/api/calendar/${item.id}/google${r.slot ? `?slot=${encodeURIComponent(r.slot)}` : ""}`, "", `If you can't make it, reply to this email and we'll free up your place.`, "", DATA.SITE.name].filter((l, i, a) => l !== "" || a[i - 1] !== "");
  if (emailConfigured()) {
    const intro = [`Hi ${firstName(String(r.name))},`, "", `You have ${r.guests === 1 ? "a place" : `${r.guests} places`} at ${item.title}.`, "", [date, where].filter(Boolean).join("\n"), "", "If you can't make it, reply to this email and we'll free up your place."].join("\n");
    const slot = r.slot ? `?slot=${encodeURIComponent(r.slot)}` : "";
    const html = emailHtml(intro, "", { href: `${SITE_URL}/api/calendar/${item.id}.ics${slot}`, label: "Add to Calendar" }, { link: { href: `${SITE_URL}/api/calendar/${item.id}/google${slot}`, label: "Google Calendar" }, contact: false });
    sendEmail({ kind: "orders", to: r.email, subject: `You're in: ${item.title}`, text: lines.join("\n"), html, replyTo: replyAddress(DATA.SITE.email) }).catch((e) => console.error("[calendar] confirmation:", e.message));
    sendEmail({ to: DATA.SITE.email, subject: `Reservation: ${item.title} (${r.guests})`, text: `${r.name} <${r.email}>, ${r.guests} place${r.guests === 1 ? "" : "s"}.\n${date}` }).catch(() => {});
  }
}

// A reservation's when: its time slot on the day ("Wed, Oct 28, 11:00 AM to 12:00 PM"), or the
// event's own dates.
function reservationWhen(x, r) {
  if (!r?.slot) return calendarDate(x);
  const t = (hm) => new Date(`2000-01-01T${hm}:00Z`).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" });
  const d = new Date(`${x.startsAt.slice(0, 10)}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" });
  return `${d}, ${t(r.slot)} to ${t(r.slotEnd)}`;
}

// "Wed, Oct 28, 6:00 PM" (and the end, for something that runs over days or hours).
function calendarDate(x) {
  const d = (s) => new Date(`${s.slice(0, 10)}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" });
  const t = (s) => (s.length > 10 ? new Date(`2000-01-01T${s.slice(11, 16)}:00Z`).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" }) : "");
  const start = [d(x.startsAt), t(x.startsAt)].filter(Boolean).join(", ");
  if (!x.endsAt) return start;
  return x.endsAt.slice(0, 10) === x.startsAt.slice(0, 10) ? `${start} to ${t(x.endsAt)}` : `${start} to ${[d(x.endsAt), t(x.endsAt)].filter(Boolean).join(", ")}`;
}

// Back office → Calendar: events and classes, their photos (kept with the other images, at
// /media/), and who has a place.
async function handleCalendarAdmin(req, res, pathname) {
  const method = req.method;
  let body: any = {};
  if (method !== "GET" && method !== "DELETE") {
    try {
      body = await readJson(req, /\/images$/.test(pathname) ? 4_000_000 : 100_000);
    } catch (error) {
      return sendJson(res, error.message === "too large" ? 413 : 400, { error: error.message === "too large" ? "That's too large to save." : "Couldn't read that request." });
    }
  }
  // Tickets bought through the shop, newest first: who, how many, for which time slot.
  const ticketsFor = (id) =>
    orders
      .list()
      .filter((o) => o.status !== "cancelled")
      .flatMap((o) => o.lines.filter((l) => l.kind === "class" && l.product === id).map((l) => ({ number: o.number, name: o.contact?.name || "", email: o.contact?.email || "", qty: l.qty, slot: l.slot || null, at: o.placedAt })))
      .sort((a, b) => String(b.at).localeCompare(String(a.at)));
  const view = (x) => ({ ...x, taken: happenings.taken(x), left: happenings.left(x), slots: happenings.view(x).slots, reservations: happenings.reservationsFor(x.id), tickets: ticketsFor(x.id) });
  try {
    if (pathname === "/api/admin/calendar" && method === "GET") return sendJson(res, 200, { items: happenings.list().map(view) });
    if (pathname === "/api/admin/calendar" && method === "POST") return sendJson(res, 201, { item: view(await happenings.create(body)) });
    if (pathname === "/api/admin/calendar/images" && method === "POST") return sendJson(res, 201, await newsletters.addImage(body.dataUrl));
    let m = pathname.match(/^\/api\/admin\/calendar\/reservations\/(res-[a-f0-9]{10})$/);
    if (m && method === "DELETE") return sendJson(res, 200, { reservation: await happenings.cancelReservation(m[1]) });
    m = pathname.match(/^\/api\/admin\/calendar\/(hap-[a-f0-9]{10})$/);
    if (m && method === "GET") return sendJson(res, 200, { item: view(happenings.get(m[1])) });
    if (m && method === "PATCH") return sendJson(res, 200, { item: view(await happenings.update(m[1], body)) });
    if (m && method === "DELETE") {
      // Still to come with people booked: they'd never hear. Cancel their places (and refund paid
      // seats) first. Past ones can go.
      const x = happenings.get(m[1]);
      const booked = happenings.taken(x);
      if (booked && (x.endsAt || x.startsAt || "").slice(0, 10) >= shopToday()) {
        return sendJson(res, 409, { error: `${booked} ${booked === 1 ? "person is" : "people are"} booked. Cancel their places (and refund paid seats from their orders) first, or switch it to a draft.` });
      }
      await happenings.remove(m[1]);
      return sendJson(res, 200, { deleted: m[1] });
    }
    return sendJson(res, 404, { error: "Not found." });
  } catch (error) {
    if (error instanceof HappeningError || error instanceof NewsletterError) return sendJson(res, error.status, { error: error.message });
    throw error;
  }
}

/* ── Reviews (server/reviews.js) ─────────────────────────────── */

// The link in the email after an order: signed, so only that order's buyer can review it.
const reviewToken = (number) => createHmac("sha256", String(setting("automationSecret")?.value || adminKey())).update(`review:${number}`).digest("base64url").slice(0, 22);
const reviewUrl = (number) => `${SITE_URL}/review?order=${encodeURIComponent(number)}&t=${reviewToken(number)}`;
const reviewable = (o) => o && o.payment === "paid" && o.status !== "cancelled" && o.status !== "pending_payment";
// The coffees and accessories on an order (gifts included), once each.
function reviewItems(order) {
  const seen = new Map();
  for (const l of allLines(order)) {
    if (l.kind !== "coffee" && l.kind !== "accessory") continue;
    const p = l.kind === "coffee" ? DATA.PRODUCTS.find((x) => x.id === l.product) : (DATA.ACCESSORIES || []).find((x) => x.id === l.product);
    if (p && !seen.has(p.id)) seen.set(p.id, { id: p.id, name: p.short || p.name, image: p.image || null });
  }
  return [...seen.values()];
}

async function handleReviews(req, res, url) {
  const method = req.method;
  if (url.pathname === "/api/reviews" && method === "GET") {
    const id = String(url.searchParams.get("product") || "");
    return sendJson(res, 200, { summary: reviews.summary(id), reviews: reviews.forProduct(id) });
  }
  let input = Object.fromEntries(url.searchParams);
  if (method === "POST") {
    if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
    if (rateLimited(clientIp(req), "review", 30)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
    try {
      input = await readJson(req);
    } catch {
      return sendJson(res, 400, { error: "Couldn't read that review." });
    }
  } else if (method !== "GET") return sendJson(res, 405, { error: "Method not allowed." });
  const number = String(input.order || "");
  const order = orders.get(number);
  const t = Buffer.from(String(input.t || ""));
  const expected = Buffer.from(reviewToken(number));
  if (!order || t.length !== expected.length || !timingSafeEqual(t, expected) || !reviewable(order)) {
    return sendJson(res, 404, { error: "This review link doesn't work." });
  }
  const items = reviewItems(order);
  if (method === "GET") {
    const mine = reviews.forOrder(number);
    return sendJson(res, 200, { order: number, items: items.map((i) => ({ ...i, review: mine[i.id] || null })) });
  }
  if (!items.some((i) => i.id === input.product)) return sendJson(res, 400, { error: "That item isn't on this order." });
  try {
    const r = await reviews.submit({ order: number, product: input.product, name: order.contact.name, rating: input.rating, text: input.text });
    return sendJson(res, 200, { review: { rating: r.rating, text: r.text } });
  } catch (error) {
    if (error instanceof ReviewError) return sendJson(res, error.status, { error: error.message });
    throw error;
  }
}

async function handleNotes(req, res, pathname) {
  const method = req.method;
  let body: any = {};
  if (method !== "GET" && method !== "DELETE") {
    try {
      body = await readJson(req, /\/images$/.test(pathname) ? 4_000_000 : 200_000);
    } catch (error) {
      return sendJson(res, error.message === "too large" ? 413 : 400, { error: error.message === "too large" ? "That's too large to save." : "Couldn't read that request." });
    }
  }
  const view = (n) => ({ ...n, url: n.status === "published" ? noteUrl(n) : null });
  try {
    if (pathname === "/api/admin/notes" && method === "GET") {
      return sendJson(res, 200, { notes: notes.list().map(view), products: DATA.PRODUCTS.map((p) => ({ id: p.id, name: p.short || p.name })) });
    }
    if (pathname === "/api/admin/notes" && method === "POST") return sendJson(res, 201, { note: view(await notes.create(body)) });
    if (pathname === "/api/admin/notes/images" && method === "POST") return sendJson(res, 201, await newsletters.addImage(body.dataUrl));
    let m = pathname.match(/^\/api\/admin\/notes\/(note-[a-f0-9]{10})\/preview$/);
    if (m && method === "GET") {
      const html = await notesPage("en", notes.get(m[1]), { preview: true });
      res.writeHead(200, { "Content-Type": TYPES[".html"], "Cache-Control": "no-store", "X-Robots-Tag": "noindex" });
      return res.end(html);
    }
    m = pathname.match(/^\/api\/admin\/notes\/(note-[a-f0-9]{10})$/);
    if (m && method === "GET") return sendJson(res, 200, { note: view(notes.get(m[1])) });
    if (m && method === "PATCH") return sendJson(res, 200, { note: view(await notes.update(m[1], body)) });
    if (m && method === "DELETE") {
      await notes.remove(m[1]);
      return sendJson(res, 200, { deleted: m[1] });
    }
    return sendJson(res, 404, { error: "Not found." });
  } catch (error) {
    if (error instanceof NoteError || error instanceof NewsletterError) return sendJson(res, error.status, { error: error.message });
    throw error;
  }
}
/* ── Inbox (back office → Inbox): customers who want a person ── */

// Replies go from INBOX_FROM (or EMAIL_FROM) with Reply-To INBOX_ADDRESS: an address Resend
// receives mail for (an address on your .resend.app domain, or on a domain whose MX record points
// to Resend, e.g. hello@reply.mimifood.com). Resend posts each email it receives to
// /api/resend/inbound, signed with RESEND_INBOUND_SECRET (Resend → Webhooks → the signing secret).
const inboxAddress = () => String(process.env.INBOX_ADDRESS || "").trim();
const inboxFrom = () => process.env.INBOX_FROM || process.env.EMAIL_FROM;
// Who the team writes as. The shared addresses (hello@, orders@, wholesale@, support@) and the
// people on the team (abu@, emily@…), added the first time someone writes from one. All are on
// EMAIL_FROM's domain; replies come back to the same name on INBOX_ADDRESS's domain, into the
// shared Inbox: orders@ to Orders, wholesale@ to Wholesale, everything else to Hello, and a
// person's as their conversation.
const SHARED_SENDERS = ["hello", "orders", "wholesale", "support"];
// Never an address to write from or take mail in for (newsletter@ only sends).
const RESERVED_SENDERS = ["imports", "newsletter", "join", "noreply", "no-reply", "postmaster", "mailer-daemon", "abuse", "admin", "root"];
const mailDomain = () => addressOf(process.env.EMAIL_FROM || DATA.SITE.email).split("@")[1] || "";
const replyDomain = () => inboxAddress().split("@")[1] || "";
const helloLocal = () => inboxAddress().split("@")[0] || "hello";
// The founder, who signs the welcome note: on the team from the start.
const FOUNDER = { local: "abu", name: "Abu Jalloh" };
const teamSenders = () => setting("teamSenders")?.value || [FOUNDER];
const senderLocal = (v) => String(v || "").trim().toLowerCase().replace(/@.*$/, "");
const validSender = (local) => /^[a-z0-9][a-z0-9._-]{0,30}$/.test(local) && !RESERVED_SENDERS.includes(local);
// Everyone the team can write as: { local, name, address, shared }.
const senders = () => [
  ...SHARED_SENDERS.map((local) => ({ local, name: DATA.SITE.name, shared: true })),
  ...teamSenders().map((p) => ({ local: p.local, name: p.name, photo: p.photo || "", shared: false })),
].map((x) => ({ ...x, address: `${x.local}@${mailDomain()}` }));
const senderOf = (local) => senders().find((x) => x.local === senderLocal(local)) || null;
// A teammate's address used for the first time ("emily@") joins the list, named from it ("Emily").
async function ensureSender(value) {
  const local = senderLocal(value);
  if (senderOf(local)) return senderOf(local);
  if (!validSender(local)) throw new InboxError(`"${local}@" can't be used to send. Use letters, numbers, dots or dashes.`);
  const name = local.split(/[._-]/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
  await saveSetting("teamSenders", [...teamSenders(), { local, name }]);
  return senderOf(local);
}
// "Mimi Food <orders@mimifood.com>", or a teammate as "Emily from Mimi Food <emily@mimifood.com>" (a shared
// address keeps any <KIND>_FROM set in Render).
const fromLine = (local) => {
  const x = senderOf(local) || senderOf("hello");
  if (x.local === "hello") return inboxFrom();
  if (x.local === "orders") return senderFor("orders");
  if (x.local === "wholesale") return senderFor("wholesale");
  if (x.local === "support") return senderFor("account");
  return `${firstName(x.name)} from ${DATA.SITE.name} <${x.address}>`;
};
// Where answers to a sender's email come back: its name on the receiving domain.
const replyTo = (local) => (replyDomain() ? `${senderLocal(local) === "hello" ? helloLocal() : senderLocal(local)}@${replyDomain()}` : "");
const boxForLocal = (local) => (local === "orders" || local === "wholesale" ? local : "hello");
// The sender an incoming email was written to: a known sender's name on the receiving domain, or
// on the shop's own domain when that mail is forwarded. Anything else stays out.
function senderForAddress(address) {
  const [local, domain] = addressOf(address).split("@");
  if (!local || ![replyDomain(), mailDomain(), addressOf(DATA.SITE.email).split("@")[1]].filter(Boolean).includes(domain)) return null;
  const name = local === helloLocal() ? "hello" : local;
  return RESERVED_SENDERS.includes(name) ? null : senderOf(name);
}
// The Inbox tab an inbox's mail arrives at (shown in the back office).
const boxAddress = (box) => replyTo(box === "orders" || box === "wholesale" ? box : "hello");
// Where replies to the shop's automatic emails go: the same name's inbox (an order email's to
// orders@, a wholesale one's to wholesale@, the rest to hello@), or else the shop's address.
const replyAddress = (fallback = DATA.SITE.email) => replyTo(senderForAddress(fallback)?.local || "hello") || fallback;
const inboundSecret = () => String(process.env.RESEND_INBOUND_SECRET || "").trim();
// "Cam, Credit Cafe" → "Cam": the first word of a name, without punctuation.
const firstName = (name) => String(name || "").trim().split(/[\s,]+/)[0].replace(/[^\p{L}\p{M}'’-]/gu, "");
const addressOf = (v) => String(/<([^>]+)>/.exec(String(v || ""))?.[1] || v || "").trim().toLowerCase();
const bracketed = (id) => (String(id).startsWith("<") ? String(id) : `<${id}>`);
const nameOf = (v) => String(/^\s*"?([^"<]*?)"?\s*</.exec(String(v || ""))?.[1] || "").trim();

// A conversation's email (a reply from the Inbox, or a new email from it), laid out like a support
// conversation: who wrote it (their initials, or the logo for a shared address) beside the message
// in a soft card; on the closing message, "Rate your conversation" with five faces; "We're here to
// help"; and the logo with the name at the foot.
const conversationSignature = (local) => {
  const x = senderOf(local);
  return x && !x.shared ? `${firstName(x.name)} from ${DATA.SITE.name}` : DATA.SITE.name;
};
const RATINGS = [[1, "Terrible", "😠"], [2, "Bad", "🙁"], [3, "OK", "😐"], [4, "Great", "😃"], [5, "Amazing", "🤩"]];
const rateToken = (cid) => createHmac("sha256", String(setting("automationSecret")?.value || adminKey())).update(`rate:${cid}`).digest("base64url").slice(0, 22);
const rateTokenOk = (cid, t) => {
  const a = Buffer.from(String(t || ""));
  const b = Buffer.from(rateToken(cid));
  return a.length === b.length && timingSafeEqual(a, b);
};
const rateUrl = (cid, score) => `${SITE_URL}/rate?c=${cid}&s=${score}&t=${rateToken(cid)}`;
// Terrible or Bad: the team hears, to follow up (once, not again if they change it to another
// low one). From the closing email's faces or the chat's.
async function ratingAlert(c, before, picked) {
  if (!(picked <= 2) || (before && before <= 2)) return;
  const [, label, face] = RATINGS.find(([score]) => score === picked);
  const who = c.owner && senderOf(c.owner);
  const last = [...c.messages].reverse().find((m) => m.from === "customer" && !m.earlier);
  await notifyShop(
    DATA.SITE.email,
    `${face} ${label} rating from ${c.name || c.email || "a customer"}`,
    `${c.name || "A customer"}${c.email ? ` <${c.email}>` : ""} rated their conversation ${label}.${c.rating?.comment ? `\n\n"${c.rating.comment}"` : ""}\n\nSubject: ${c.subject}${who && !who.shared ? `\nHandled by: ${who.name}` : ""}${last ? `\nTheir last message: ${firstLine(last.text)}` : ""}\n\nFollow up in the back office: ${SITE_URL}/admin/inbox/${c.id}`
  ).catch((e) => console.error("[inbox] rating alert:", e.message));
}

// "Our chat" in a conversation's emails opens that conversation in the chat window on the site,
// so they can carry on there (signed like the rating links).
const chatLinkToken = (cid) => createHmac("sha256", String(setting("automationSecret")?.value || adminKey())).update(`chat:${cid}`).digest("base64url").slice(0, 22);
const chatLinkOk = (cid, t) => {
  const a = Buffer.from(String(t || ""));
  const b = Buffer.from(chatLinkToken(cid));
  return a.length === b.length && timingSafeEqual(a, b);
};
const chatLink = (c) => (c?.id && c.email ? `${SITE_URL}/contact?chat=${c.id}&k=${chatLinkToken(c.id)}` : `${SITE_URL}/contact?chat=1`);
function conversationEmailHtml(text, local, { rateFor = "", chat = `${SITE_URL}/contact?chat=1` } = {}) {
  const x = senderOf(local);
  const person = x && !x.shared;
  const initials = person ? x.name.split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0].toUpperCase()).join("") : "";
  const avatar = person && x.photo
    ? `<img src="${SITE_URL}/media/${x.photo}" alt="" width="40" height="40" style="display:block;width:40px;height:40px;border:0;border-radius:20px;object-fit:cover">`
    : person
    ? `<div style="width:40px;height:40px;border-radius:20px;background:${EMAIL_INK};color:#ffffff;font:600 14px/40px ${EMAIL_FONT};text-align:center">${escapeHtml(initials)}</div>`
    : `<div style="width:40px;height:40px;border-radius:20px;background:#ffffff;box-shadow:inset 0 0 0 1px ${EMAIL_LINE};text-align:center"><img src="${SITE_URL}/assets/email-logo-badge.png" alt="" width="20" height="28" style="display:inline-block;border:0;margin-top:6px"></div>`;
  const paras = linkify(escapeHtml(text))
    .split(/\n{2,}/)
    .map((p) => `<p style="margin:0 0 16px;font:400 16px/1.5 ${EMAIL_FONT};color:${EMAIL_INK}">${p.replace(/\n/g, "<br>")}</p>`)
    .join("");
  const card = (inner, pad = "20px 24px") => `<div style="padding:${pad};border-radius:16px;background:${EMAIL_SOFT}">${inner}</div>`;
  const rating = rateFor
    ? `<tr><td></td><td style="padding:12px 0 0">${card(
        `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #dddddd;border-radius:6px"><tr><td colspan="5" align="center" style="padding:20px 8px 14px;font:400 17px/1.4 ${EMAIL_FONT};color:${EMAIL_MUTED}">Rate your conversation</td></tr><tr>${RATINGS.map(
          ([score, label, face]) => `<td align="center" width="20%" style="padding:0 2px 18px"><a href="${rateUrl(rateFor, score)}" style="text-decoration:none;color:${EMAIL_MUTED}"><span style="display:block;font-size:32px;line-height:40px">${face}</span><span style="display:block;font:400 13px/1.4 ${EMAIL_FONT};color:${EMAIL_MUTED}">${label}</span></a></td>`
        ).join("")}</tr></table>`,
        "16px"
      )}</td></tr>`
    : "";
  const body = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 20px"><tr>
  <td width="52" valign="bottom" style="padding:0 12px 0 0">${avatar}</td>
  <td valign="top">${card(paras, "18px 24px 2px")}</td>
</tr>${person ? `<tr><td></td><td style="padding:6px 0 0 4px;font:400 13px/1.4 ${EMAIL_FONT};color:${EMAIL_MUTED}">${escapeHtml(conversationSignature(local))}</td></tr>` : ""}${rating}</table>
${card(`<p style="margin:0 0 10px;font:600 18px/1.3 ${EMAIL_FONT};color:${EMAIL_INK}">We're here to help</p><p style="margin:0;font:400 16px/1.5 ${EMAIL_FONT};color:${EMAIL_INK}">Reply to this email or use <a href="${escapeHtml(chat)}" style="color:#0000ee;text-decoration:underline">our chat</a></p>`, "22px 24px")}`;
  const footer = `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:28px 0 0"><tr><td valign="middle" style="padding-right:12px"><a href="${SITE_URL}/"><img src="${SITE_URL}/assets/email-logo-badge.png" alt="" width="30" height="42" style="display:block;border:0"></a></td><td valign="middle"><a href="${SITE_URL}/" style="font:600 30px/1 ${EMAIL_FONT};letter-spacing:-0.01em;color:${EMAIL_INK};text-decoration:none">${escapeHtml(DATA.SITE.name)}</a></td></tr></table>`;
  return emailLayout({ siteUrl: SITE_URL, siteName: DATA.SITE.name, preheader: String(text).split(/(?<=[.!?])\s/)[0].slice(0, 140), body, footer, logo: false, rule: false });
}

// How long a reply waits in the chat window to be read before it goes by email as well.
const CHAT_EMAIL_AFTER = 5 * 60_000;
const chatSeen = new Map(); // conversation id → when a chat window last looked at it

async function deliverReply(c, m) {
  if (c.channel === "imessage") {
    const to = m.replyTo && c.messages.find((x) => x.id === m.replyTo);
    return sendText(c, m.text, { ...(m.effect && { effect: m.effect }), ...(to?.textId && { replyTo: to.textId }) });
  }
  if (!c.email) return {}; // a visitor in the chat, with no email: the reply is in their chat
  // An email conversation they carried on in the chat: the reply shows there, and goes by email
  // too if they haven't seen it in a few minutes (they may have closed the page).
  const lastIn = [...c.messages].reverse().find((x) => x.from === "customer");
  if (c.chatKeys?.length && lastIn?.via === "chat") {
    m.inChat = true;
    m.emailBy = new Date(Date.now() + CHAT_EMAIL_AFTER).toISOString();
    return {};
  }
  return emailReply(c, m);
}

async function emailReply(c, m) {
  // Each reply carries its own Message-ID and references every earlier email in the conversation
  // (theirs and ours), so the whole conversation stays one thread in their mail app.
  const domain = addressOf(inboxFrom()).split("@")[1] || "localhost";
  m.messageId ||= `<${m.id}.${refOf(c)}@${domain}>`;
  const earlier = c.messages.slice(0, c.messages.indexOf(m)).map((x) => x.messageId).filter(Boolean).map(bracketed);
  return sendEmail({
    kind: "inbox",
    to: c.email,
    // From whoever wrote it (abu@, or the conversation's address: orders@ for Orders…), and
    // answers come back to the same address, into the same conversation.
    from: fromLine(m.sender || c.from || boxOf(c)),
    replyTo: replyTo(m.sender || c.from || boxOf(c)) || undefined,
    // The conversation's subject, with "Re:" once they've written (no ticket numbers: answers find
    // their conversation by the email they reply to).
    subject: `${c.messages.some((x) => x.from === "customer") ? "Re: " : ""}${cleanSubject(c.subject)}`,
    text: `${m.text}\n\n${conversationSignature(m.sender || c.from || boxOf(c))}${m.rate ? `\n\nRate your conversation:\n${RATINGS.map(([score, label]) => `${label}: ${rateUrl(c.id, score)}`).join("\n")}` : ""}\n\n—\nWe're here to help. Reply to this email or use our chat: ${chatLink(c)}`,
    html: conversationEmailHtml(m.text, m.sender || c.from || boxOf(c), { rateFor: m.rate ? c.id : "", chat: chatLink(c) }),
    // Answers sit under the customer's own email in their mail app.
    headers: { "Message-ID": m.messageId, ...(earlier.length && { "In-Reply-To": earlier.at(-1), References: earlier.slice(-20).join(" ") }) },
  });
}

const inboxStore = await storage.open("inbox", INBOX_PARTS);
const inbox = createInbox({ store: inboxStore, deliver: deliverReply });

// One live stream for the Inbox, after Spectrum's event stream: every open Inbox hears which
// conversations changed (a new message, a read, a reaction, a status) the moment they're saved,
// instead of asking every few seconds.
const inboxListeners = new Set<(ids: string[]) => void>();
const inboxSigs = new Map<string, string>(); // conversation id → a hash of how it was last seen
const inboxSig = (c) => createHash("sha1").update(JSON.stringify(c)).digest("base64");
function inboxSeen() {
  inboxSigs.clear();
  for (const c of inboxStore.data.conversations) inboxSigs.set(c.id, inboxSig(c));
}
let inboxDiffAt = null;
function inboxChanged() {
  if (!inboxListeners.size || inboxDiffAt) return;
  inboxDiffAt = setTimeout(() => {
    inboxDiffAt = null;
    const ids = [];
    const now = new Set();
    for (const c of inboxStore.data.conversations) {
      now.add(c.id);
      const sig = inboxSig(c);
      if (inboxSigs.get(c.id) !== sig) ids.push(c.id);
      inboxSigs.set(c.id, sig);
    }
    for (const cid of inboxSigs.keys()) if (!now.has(cid)) (ids.push(cid), inboxSigs.delete(cid));
    if (ids.length) for (const hear of inboxListeners) hear(ids);
  }, 120);
}
{
  const saveInbox = inboxStore.save;
  inboxStore.save = async (...args) => {
    const done = await saveInbox(...args);
    inboxChanged();
    return done;
  };
}

// Replies left in the chat window: seen there since they went, or emailed once it's been a while.
async function chatRepliesTick() {
  for (const { c, m } of inbox.waitingInChat()) {
    if ((chatSeen.get(c.id) || 0) > Date.parse(m.sentAt)) {
      await inbox.chatReplyDone(c.id, m.id, { seenInChat: new Date().toISOString() });
      continue;
    }
    if (Date.now() < Date.parse(m.emailBy)) continue;
    try {
      const sent: any = await emailReply(c, m);
      await inbox.chatReplyDone(c.id, m.id, { emailedAt: new Date().toISOString(), ...(sent?.id && { emailId: sent.id }) });
    } catch (error) {
      console.error(`[inbox] chat reply to ${c.email} by email failed:`, error.message);
      await inbox.chatReplyDone(c.id, m.id, { emailError: String(error.message).slice(0, 200) });
    }
  }
}
setInterval(() => chatRepliesTick().catch((e) => console.error("[inbox] chat replies:", e.message)), 30_000).unref?.();

// Texts (iMessage through Photon). Each one joins its sender's conversation, or starts one.
// A sender is matched to a wholesale account by phone number (last 10 digits) or email.
const lastTen = (v) => String(v || "").replace(/\D/g, "").slice(-10);
function textAccount(from) {
  const live = trade.accounts.filter((a) => !a.archivedAt);
  if (from.includes("@")) return live.find((a) => a.email === from.toLowerCase() || (a.portalEmails || []).includes(from.toLowerCase())) || null;
  const digits = lastTen(from);
  return (digits.length === 10 && live.find((a) => lastTen(a.phone) === digits)) || null;
}

// Photos, voice notes and files they text, kept apart from the conversations (they're big) and
// shown only in the back office (/api/admin/inbox/files/<id>). Photos are turned into JPEGs no
// wider than 1568px (iPhone HEIC photos too), so they show anywhere and the assistant can see them.
const textFiles = await storage.open("textfiles", { files: (f) => f.id });
const FILE_LABEL = { image: "Sent a photo.", audio: "Sent a voice message.", video: "Sent a video.", pdf: "Sent a PDF." };
const FILES_LABEL = { image: "photos", audio: "voice messages", video: "videos", pdf: "PDFs" };
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, "0")}`;
// "Sent a photo.", "Sent 3 photos.", "Sent a voice message (0:12).", "Sent 2 files."
function filesLabel(files) {
  const kinds = new Set(files.map((f) => f.kind));
  if (files.length === 1) {
    const f = files[0];
    if (f.kind === "audio" && f.duration) return `Sent a voice message (${clock(f.duration)}).`;
    return FILE_LABEL[f.kind] || `Sent a file${f.name ? ` (${f.name})` : ""}.`;
  }
  return `Sent ${files.length} ${kinds.size === 1 ? FILES_LABEL[files[0].kind] || "files" : "files"}.`;
}
const fileKind = (type) => (type.startsWith("image/") ? "image" : type.startsWith("audio/") ? "audio" : type.startsWith("video/") ? "video" : type === "application/pdf" ? "pdf" : "file");
async function keepTextFile(file) {
  let { data, mimeType: type, name } = file;
  if (/^image\/(hei[cf]|jpeg|png|webp|gif|tiff)/i.test(type)) {
    try {
      if (/hei[cf]/i.test(type)) data = Buffer.from(await (await import("heic-convert")).default({ buffer: data, format: "JPEG", quality: 0.9 }));
      const { default: sharp } = await import("sharp");
      data = await sharp(data).rotate().resize(1568, 1568, { fit: "inside", withoutEnlargement: true }).jpeg({ quality: 82 }).toBuffer();
      type = "image/jpeg";
      name = name.replace(/\.\w+$/, "") + ".jpg";
    } catch (error) {
      console.error("[inbox] couldn't convert a photo:", error.message);
    }
  }
  const f = { id: `file-${randomBytes(8).toString("hex")}`, type, name: String(name || "").slice(0, 120), bytes: data.length, data: data.toString("base64"), at: new Date().toISOString() };
  textFiles.data.files.push(f);
  await textFiles.save();
  return { id: f.id, kind: fileKind(type), type, name: f.name, bytes: f.bytes, ...(file.duration && { duration: Math.round(file.duration) }) };
}
const textFile = (id) => textFiles.data.files.find((f) => f.id === id) || null;

// Photos and PDFs from the chat window (+ in Chat Us): three a message, kept like texted files.
// A photo must open as one and a PDF must start like one, whatever the browser says it is.
class ChatFileError extends Error {}
async function chatFiles(list) {
  const out = [];
  for (const f of (Array.isArray(list) ? list : []).slice(0, 3)) {
    const type = String(f?.type || "");
    const data = Buffer.from(typeof f?.data === "string" ? f.data : "", "base64");
    if (!data.length || data.length > 10 * 1024 * 1024) throw new ChatFileError("Add photos or PDFs under 10 MB.");
    if (type === "application/pdf") {
      if (data.subarray(0, 5).toString("latin1") !== "%PDF-") throw new ChatFileError("That PDF couldn't be opened.");
    } else if (/^image\/(jpeg|png|webp|gif|heic|heif)$/.test(type)) {
      const { default: sharp } = await import("sharp");
      const ok = /hei[cf]/.test(type) || (await sharp(data).metadata().then((m) => m.width > 0, () => false));
      if (!ok) throw new ChatFileError("That photo couldn't be opened.");
    } else throw new ChatFileError("Add a photo or a PDF.");
    out.push(await keepTextFile({ data, mimeType: type, name: String(f?.name || (type === "application/pdf" ? "file.pdf" : "photo.jpg")).slice(0, 120) }));
  }
  return out;
}

// Every text to a customer goes through here: the shop's contact card goes first, once per
// conversation, so they can save the number (logo, the texting line, email, site, roastery).
const contactPhoto = readFileSync(path.join(ROOT, "assets/contact-photo.jpg"));
// Written the way an iPhone writes a company card (vCard 3.0, empty N, X-ABShowAs:COMPANY), so
// Contacts files it under Mimi Food as a business, with the logo as its photo.
const vcardText = (v) => String(v || "").replace(/\\/g, "\\\\").replace(/\n/g, "\\n").replace(/([,;])/g, "\\$1");
const vcardFold = (line) => line.match(/.{1,74}/g).join("\r\n ");
const shopCard = () => {
  const s = DATA.SITE;
  const from = s.shipFrom || {};
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    // Shown as a person named Mimi Food, with the company line "Coffee & Tea".
    `N:;${vcardText(s.name)};;;`,
    `FN:${vcardText(s.name)}`,
    `ORG:${vcardText("Coffee & Tea")}`,
    `TEL;type=WORK;type=VOICE;type=pref:${textNumber() || from.phone}`,
    `EMAIL;type=INTERNET;type=WORK:${s.wholesaleEmail}`,
    `URL;type=WORK:${SITE_URL}`,
    from.street1 ? `ADR;type=WORK:;;${vcardText(from.street1)};${vcardText(from.city)};${vcardText(from.state)};${vcardText(from.postalCode)};United States` : null,
    vcardFold(`PHOTO;ENCODING=b;TYPE=JPEG:${contactPhoto.toString("base64")}`),
    "END:VCARD",
  ];
  return lines.filter(Boolean).join("\r\n") + "\r\n";
};
async function sendText(c, text, opts?) {
  await shareCardOnce(c);
  return imessage.send(c.spaceId, text, opts);
}
// Once per person: a new conversation with someone who already has the card doesn't send it again.
async function shareCardOnce(c) {
  if (!c.cardShared && inbox.cardSentTo(c)) await inbox.update(c.id, { cardShared: true });
  else if (!c.cardShared) {
    try {
      await imessage.shareCard(c.spaceId, shopCard());
      await inbox.update(c.id, { cardShared: true });
    } catch (error) {
      console.error("[imessage] contact card:", error.message);
    }
  }
}

/* ── Stock ── */
const stockUnits = (lines) => lines.flatMap((l) => lineUnits(l, DATA));
const bagWeight = (units) => (units >= 4 ? `${units / 4}kg` : `${units * 250}g`);
// Why these lines can't all be had (counted stock is short), or "" when they can.
function stockShort(lines, held = []) {
  const lack = stock.short(stockUnits(lines), held)[0];
  if (!lack) return "";
  const [id, variant] = lack.key.split(/:(.*)/s);
  const p = DATA.PRODUCTS.find((x) => x.id === id);
  const a = !p && DATA.ACCESSORIES.find((x) => x.id === id);
  const name = `${p?.short || a?.short || a?.name || "One item"}${variant ? ` (${variant})` : ""}`;
  if (!lack.left) return `${name} has just sold out. Please remove it from your cart.`;
  return `Only ${p ? bagWeight(lack.left) : lack.left} of ${name} left. Please change the quantity in your cart.`;
}
// Emails everyone waiting on something that can be bought again, then forgets them.
let notifying = false;
async function notifyBack() {
  if (notifying) return;
  notifying = true;
  try {
    const sent = [];
    for (const w of stock.waits()) {
      const [id, variant] = w.key.split(/:(.*)/s);
      const p = DATA.PRODUCTS.find((x) => x.id === id) || DATA.ACCESSORIES.find((x) => x.id === id);
      if (!p || p.soldOut || p.price == null || (variant && p.leftBy?.[variant] === 0)) continue;
      if (!emailConfigured()) continue; // they keep waiting until email is set up
      const name = `${p.short || p.name}${variant ? ` (${variant})` : ""}`;
      const href = `${SITE_URL}${langPrefix(w.lang)}/products/${encodeURIComponent(id)}`;
      const text = `${name} is back in stock.${p.left != null && p.left <= LOW_STOCK ? " There aren't many, so don't wait too long." : ""}`;
      try {
        await sendEmail({ kind: "orders", to: w.email, replyTo: replyAddress(DATA.SITE.ordersEmail), subject: `${name} is back at ${DATA.SITE.name}`, text: `${text}

${href}

You asked us to tell you when it was back. We won't email you about it again.

${DATA.SITE.name}`, html: emailHtml(`${text}

You asked us to tell you when it was back. We won't email you about it again.`, "", { href, label: "Shop Now" }) });
        sent.push(w.id);
      } catch (error) {
        console.error("[stock] back-in-stock email:", error.message);
      }
    }
    if (sent.length) {
      await stock.done(sent);
      console.log(`[stock] ${sent.length} back-in-stock email${sent.length === 1 ? "" : "s"} sent`);
    }
  } finally {
    notifying = false;
  }
}

// An order's tax, delivery and discount code, for the shop's purchase measurement.
const gaAmounts = (o) => ({ tax: o.tax || 0, shipping: Math.round(((o.shipping || 0) + (o.cafeFee || 0)) * 100) / 100, coupon: o.discount?.code || "" });

// A site image's bytes: from /assets or a back office upload (/media/).
function siteImage(src) {
  if (src.startsWith("/media/")) {
    const photo = catalog.photo(decodeURIComponent(src.slice(7)));
    return photo ? Buffer.from(photo.data, "base64") : null;
  }
  const file = path.join(ROOT, src);
  return src.startsWith("/assets/") && file.startsWith(path.join(ROOT, "assets")) && existsSync(file) ? readFileSync(file) : null;
}
// Merchant feed photos, drawn once per product state (its photo, label and color).
const feedPhotos = new Map();
async function serveFeedPhoto(res, id) {
  try {
    const parts = await feedPhotoParts(DATA, id, async (src) => siteImage(String(src)));
    if (!parts?.source) return send(res, 404, "Not found");
    const key = `${id}:${createHash("sha256").update(parts.source).update(parts.overlay || "").digest("hex")}`;
    let jpeg = feedPhotos.get(key);
    if (!jpeg) {
      jpeg = await renderFeedPhoto(parts);
      feedPhotos.set(key, jpeg);
      if (feedPhotos.size > 200) feedPhotos.delete(feedPhotos.keys().next().value);
    }
    res.writeHead(200, { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=3600" });
    res.end(jpeg);
  } catch (error) {
    console.error("[feed] photo:", error.message);
    send(res, 500, "Couldn't draw that photo.");
  }
}

// A product's photo as a JPEG to text: from /assets or a back office upload (/media/).
async function productPhoto(p) {
  const src = String(p.image || "");
  if (!src) return null;
  let data;
  if (src.startsWith("/media/")) {
    const photo = catalog.photo(decodeURIComponent(src.slice(7)));
    if (photo) data = Buffer.from(photo.data, "base64");
  } else if (src.startsWith("/assets/")) {
    const file = path.join(ROOT, src);
    if (file.startsWith(path.join(ROOT, "assets"))) data = readFileSync(file);
  }
  if (!data) return null;
  const { default: sharp } = await import("sharp");
  // Cut-out photos (transparent) go on white, as they look on the site.
  return sharp(data).flatten({ background: "#ffffff" }).resize(1200, 1200, { fit: "inside", withoutEnlargement: true }).jpeg({ quality: 85 }).toBuffer();
}

const imessage = createImessage({
  async onText({ from, spaceId, messageId, text, files: sent = [] }) {
    const files = [];
    for (const f of sent.slice(0, 10)) if (!f.tooBig) files.push(await keepTextFile(f));
    const tooBig = sent.filter((f) => f.tooBig).length;
    // A caption they typed stays as the text; otherwise it says what they sent.
    if (!text && files.length) text = filesLabel(files);
    if (tooBig) text = [text, `Sent ${tooBig === 1 ? "a file" : `${tooBig} files`} too big to keep (over 15 MB).`].filter(Boolean).join("\n");
    const found = inbox.matchText(spaceId);
    let conv = found;
    if (found) await inbox.receive(found, { text, textId: messageId, files });
    else {
      const acct = textAccount(from);
      const d = from.replace(/\D/g, "");
      const number = d.length === 11 && d[0] === "1" ? `(${d.slice(1, 4)}) ${d.slice(4, 7)}-${d.slice(7)}` : from;
      const name = acct ? acct.contactName || acct.business : number;
      conv = await inbox.start({ name, subject: acct ? acct.business : firstLine(text), channel: "imessage", source: "imessage", box: acct ? "wholesale" : "hello", text, phone: from, spaceId, accountId: acct?.id, textId: messageId, files });
    }
    console.log(`[inbox] text${found ? ` (conversation ${found.id})` : " (new)"}${!conv.agent ? ": the assistant is off for it" : !textAgent ? ": no assistant (Claude isn't connected)" : ""}`);
    if (conv.agent && textAgent) textAgent.poke(conv.id);
  },
  // A tapback on one of our texts: shows in the Inbox, and the assistant takes it as an answer
  // (👍 on "Good to go?" is a yes).
  async onReaction({ spaceId, messageId, emoji, textId }) {
    const c = inbox.matchText(spaceId);
    const to = c?.messages.find((m) => m.textId === textId && m.from !== "customer");
    if (!to) return;
    const quote = to.text.length > 60 ? `${to.text.slice(0, 59)}…` : to.text;
    await inbox.receive(c, { text: `Reacted ${emoji} to “${quote}”`, textId: messageId, reaction: { emoji, to: to.id } });
    if (c.agent && textAgent) textAgent.poke(c.id);
  },
  // They read our texts: "Read 2:14 PM" under the latest one in the Inbox.
  async onRead({ spaceId, textId, at }) {
    const c = inbox.matchText(spaceId);
    if (c) await inbox.readUpTo(c, textId, at);
  },
});

/* The texting assistant (server/textagent.js): answers wholesale texts and acts on the account
   through the same code as the wholesale portal. Each action is noted in the conversation. */
const convAccount = (c) => (c.accountId && trade.account(c.accountId)) || textAccount(c.phone || "");
function textCustomer(c) {
  const acct = convAccount(c);
  if (!acct || acct.archivedAt) throw new TradeError("This number isn't linked to a wholesale account. The team can link it (hand_off).");
  return acct;
}
const agentLines = (lines) =>
  (lines || []).map((l) => {
    const tea = DATA.ACCESSORIES.some((a) => a.id === l.product && a.category === "Tea");
    if (!tea && l.size === "tin") throw new TradeError("Coffee comes in 5lb, 1kg or 250g bags.");
    if (tea && !["tin", "1kg"].includes(l.size)) throw new TradeError("Tea comes in packs of 8 cups or 1kg loose.");
    return { product: l.product, size: l.size, qty: l.qty };
  });
// One of their locations, named by the assistant (or its id): "" for the main address.
function locationNamed(acct, name) {
  const n = String(name || "").trim().toLowerCase();
  if (!n || n === "main" || n === String(acct.business || "").toLowerCase()) return "";
  const l = (acct.locations || []).find((x) => x.id === name || x.name.toLowerCase() === n) || (acct.locations || []).find((x) => x.name.toLowerCase().includes(n));
  if (!l) throw new TradeError(`They don't have a location called “${name}”. Their locations: ${(acct.locations || []).map((x) => x.name).join(", ") || "only the main address"}.`);
  return l.id;
}
async function priceForText(acct, { lines, fulfilment, location = "", notes = "", poRef = "" }, except = "") {
  const loc = fulfilment === "Pickup" ? "" : locationNamed(acct, location);
  const { local } = fulfilment === "Pickup" ? { local: true } : await tradeLocal(acct, trade.addressFor(acct, loc));
  return priceWholesale(acct, { lines: agentLines(lines), fulfilment, location: loc, notes, poRef }, { local }, except);
}
// A wholesale account's credit still to use: each credit less what its orders have taken
// (cancelled orders give theirs back; `except` is an order being re-priced).
// How many of each line of an order have been credited already, by hand ([i] → qty).
function creditedQty(acct, number) {
  const out = {};
  for (const c of acct.credits || []) if (c.order === number) for (const x of c.items || []) out[x.i] = (out[x.i] || 0) + x.qty;
  return out;
}
function creditsLeft(acct, except = "") {
  const used = new Map();
  for (const o of orders.list()) {
    if (o.wholesale?.accountId !== acct.id || o.status === "cancelled" || o.number === except) continue;
    for (const c of o.wholesale.credits || []) used.set(c.id, (used.get(c.id) || 0) + c.amount);
  }
  return (acct.credits || []).map((c) => ({ id: c.id, reason: c.reason, order: c.order, amount: c.amount, createdAt: c.createdAt, left: round2(c.amount - (used.get(c.id) || 0)) })).filter((c) => c.left > 0.004);
}
const priceWholesale = (acct, input, opts: any = {}, except = "") => trade.priceWholesale(acct, input, { ...opts, credits: creditsLeft(acct, except) });
const itemsOf = (o) => o.lines.map((l) => `${l.qty} × ${l.title} (${l.variant}) ${money(l.price * l.qty)}`);
const theirOrder = (acct, number) => {
  const o = orders.get(String(number || "").trim().toUpperCase());
  if (!o || o.wholesale?.accountId !== acct.id) throw new TradeError("No order with that number on this account.");
  return o;
};
// Changes and cancellations: only before it's packed or paid.
const changeable = (o) => {
  if (o.status !== "new") throw new TradeError(`${o.number} is ${o.status === "cancelled" ? "cancelled" : "already packed"}, so it can't be changed. The team can help (hand_off).`);
  if (o.payment !== "unpaid" || o.wholesale?.processing) throw new TradeError(`${o.number} is paid or being paid, so it can't be changed. The team can help (hand_off).`);
};
// Who they are and what day it is, after the cached part of the prompt; with what the assistant
// remembers about the account and their usual order.
// Their account, prices and recent orders come with every answer, so most questions need no
// lookup first (each one is another trip to the model).
const wholesaleContext = async (c) => {
  const acct = convAccount(c);
  const base = `Today is ${shopToday()}. ${acct ? `You're ${c.spaceId ? "texting" : "chatting with"} ${c.name === acct.business ? "someone" : c.name} at ${acct.business}, a wholesale account${acct.archivedAt ? " that has been closed (hand off anything account related)" : ""}.` : `This number (${c.phone}) isn't linked to a wholesale account.`}`;
  if (!acct) return base;
  let facts = "";
  if (!acct.archivedAt) {
    try {
      const [account, prices, recent] = await Promise.all([wholesaleActions.get_account(c), wholesaleActions.get_prices(c), wholesaleActions.get_orders(c)]);
      facts = `\n\n# Their account, prices and recent orders, as of now\nAnswer from these; call get_account, get_prices or get_orders only for something not here.\n${JSON.stringify({ account, prices, recentOrders: recent.slice(0, 6) })}`;
    } catch (error) {
      console.error("[textagent] wholesale context:", error.message);
    }
  }
  return `${base}${memoryText(`account:${acct.id}`)}${usualText(acct.id)}${facts}`;
};
// How an order change came in, for its history: a text from their number, or the website chat.
const viaOf = (c) => (c.spaceId ? `text ${c.phone}` : `chat ${c.email || c.name}`);
const wholesaleActions: Record<string, any> = {
        async get_account(c) {
          const acct = textCustomer(c);
          const open = orders.list().filter((o) => o.wholesale?.accountId === acct.id && o.payment !== "paid" && o.status !== "cancelled" && o.status !== "pending_payment" && o.total > 0);
          return {
            business: acct.business,
            contact: acct.contactName,
            billingEmail: acct.email,
            phone: acct.phone,
            address: acct.address,
            locations: (acct.locations || []).map((l) => ({ name: l.name, address: `${l.street}, ${l.city}, ${l.state} ${l.postcode}` })),
            offRetail: `${Math.round((1 - tradeFactor(acct)) * 100)}%`,
            paymentTerms: acct.terms ? `${acct.terms} days` : "due on receipt",
            deliveryFee: acct.deliveryFee || 0,
            rules: { ...(await tradeLocal(acct)), localMiles: DATA.SITE.wholesale.localMiles, minimumsBeyondLocal: DATA.SITE.wholesale.minimums },
            owed: { total: Math.round(open.reduce((n, o) => n + o.total, 0) * 100) / 100, invoices: open.map((o) => ({ number: o.number, total: o.total, due: o.wholesale?.dueDate, state: tradeState(o) })) },
            portal: `${SITE_URL}/trade`,
          };
        },
        async get_prices(c) {
          const acct = textCustomer(c);
          const factor = tradeFactor(acct);
          return {
            coffee: tradePrices(acct).map((p) => {
              const kilo = DATA.PRODUCTS.find((x) => x.id === p.id);
              return { id: p.id, name: p.name, notes: p.notes, price5lb: p.price5lb, price1kg: Math.round((kilo.regular1kg ?? kilo.price1kg) * factor * 100) / 100, price250g: p.price250 };
            }),
            tea: tradeTeas(acct).map((t) => ({ id: t.id, name: t.name, notes: t.notes, pack: t.pack, priceTin: t.price, price1kg: t.price1kg })),
          };
        },
        async get_orders(c) {
          const acct = textCustomer(c);
          return orders
            .list()
            .filter((o) => o.wholesale?.accountId === acct.id)
            .slice(0, 10)
            .map((o) => ({ number: o.number, placed: o.placedAt.slice(0, 10), status: o.status, state: tradeState(o), fulfilment: o.fulfilment, items: itemsOf(o), delivery: o.shipping || 0, total: o.total, due: o.wholesale?.dueDate || null, tracking: o.tracking?.url || null }));
        },
        async quote_order(c, input) {
          const acct = textCustomer(c);
          const q = await priceForText(acct, input);
          return { items: itemsOf(q), fulfilment: q.fulfilment, delivery: q.shipping, total: q.total, paymentTerms: acct.terms ? `due in ${acct.terms} days` : "due on receipt" };
        },
        async place_order(c, input) {
          const acct = textCustomer(c);
          let order = await orders.add(await routeTrade(await priceForText(acct, input)), { status: "new", payment: "unpaid", by: viaOf(c) });
          let invoiced = false;
          if (squareConfigured()) {
            try {
              order = await invoiceWholesale(order);
              invoiced = true;
            } catch (error) {
              console.error("[textagent] invoice failed:", error.message);
            }
          }
          await inbox.say(c, `Placed ${order.number} · ${money(order.total)}`, { action: true });
          await notifyShop(DATA.SITE.ordersEmail, `Wholesale order ${order.number}: ${acct.business}, ${money(order.total)}`, `${orderText(order)}

Placed with the assistant (${viaOf(c)}).${invoiced ? " Invoice sent." : " No invoice yet: send it from the back office."}

${SITE_URL}/admin/inbox/${c.id}`);
          return { number: order.number, items: itemsOf(order), total: order.total, invoiceEmailed: invoiced, payLink: invoiced ? invoiceLink(order.number) : null };
        },
        async change_order(c, input) {
          const acct = textCustomer(c);
          const o = theirOrder(acct, input.number);
          changeable(o);
          const was = o.total; // (the order is updated in place below)
          const q = await routeTrade(await priceForText(acct, { ...input, notes: o.notes, poRef: o.wholesale?.poRef }, o.number));
          // The old invoice can't be paid once the amount changes: cancel it first, then send a new one.
          const old = o.wholesale?.invoice;
          if (old?.id) await sq.cancelInvoice(old.id);
          let updated = await orders.update(o.number, { lines: q.lines, fulfilment: q.fulfilment, shipTo: q.shipTo, courier: q.fulfilment === "Local delivery" ? { ...(o.courier || {}), ...q.courier } : null, subtotal: q.subtotal, shipping: q.shipping, total: q.total, discount: q.discount || null, wholesale: { ...o.wholesale, credits: q.wholesale.credits || [], invoice: null, ...(old && { voided: [...(o.wholesale.voided || []), old] }) } }, { by: viaOf(c), note: `Changed with the assistant: ${money(was)} → ${money(q.total)}` });
          if (old && squareConfigured()) updated = await invoiceWholesale(updated);
          await inbox.say(c, `Changed ${o.number} · ${money(was)} → ${money(updated.total)}`, { action: true });
          await notifyShop(DATA.SITE.ordersEmail, `Wholesale order ${o.number} changed: ${acct.business}, ${money(updated.total)}`, `${orderText(updated)}

Changed by text with the assistant (was ${money(was)}).

${SITE_URL}/admin/inbox/${c.id}`);
          return { number: o.number, items: itemsOf(updated), total: updated.total, newInvoiceEmailed: Boolean(old && updated.wholesale?.invoice) };
        },
        async cancel_order(c, input) {
          const acct = textCustomer(c);
          const o = theirOrder(acct, input.number);
          changeable(o);
          await orders.update(o.number, { status: "cancelled" }, { by: viaOf(c), note: "Cancelled with the assistant" });
          await cancelUnderway(o.number);
          if (o.wholesale?.invoice?.id) await sq.cancelInvoice(o.wholesale.invoice.id).catch((error) => console.error(`[square] couldn't cancel invoice for ${o.number}:`, error.message));
          await inbox.say(c, `Cancelled ${o.number}`, { action: true });
          await notifyShop(DATA.SITE.ordersEmail, `Wholesale order ${o.number} cancelled: ${acct.business}`, `${acct.business} cancelled ${o.number} (${money(o.total)}) by text with the assistant.

${SITE_URL}/admin/inbox/${c.id}`);
          return { cancelled: o.number };
        },
        async send_invoice(c, input) {
          const acct = textCustomer(c);
          let o = theirOrder(acct, input.number);
          if (o.payment === "paid") return { paid: true, number: o.number };
          if (o.status === "cancelled") throw new TradeError(`${o.number} was cancelled.`);
          if (!o.wholesale?.invoice && squareConfigured()) o = await invoiceWholesale(o);
          else await emailInvoice(o, acct, o.wholesale?.dueDate || shopToday());
          await inbox.say(c, `Sent invoice ${o.number}`, { action: true });
          return { number: o.number, total: o.total, due: o.wholesale?.dueDate || null, emailedTo: acct.email, payLink: invoiceLink(o.number) };
        },
        async send_poll(c, input) {
          const options = [...new Set((input.options || []).map((o) => String(o).trim().slice(0, 60)).filter(Boolean))].slice(0, 6);
          if (options.length < 2) throw new Error("A poll needs at least two choices.");
          const question = String(input.question || "").trim().slice(0, 120);
          await shareCardOnce(c);
          const sent = await imessage.sendPoll(c.spaceId, question, options);
          await inbox.say(c, `${question}\n${options.map((o) => `○ ${o}`).join("\n")}`, { textId: sent?.id, poll: true });
          return "Sent. Their vote will come back as a text.";
        },
        async send_photo(c, input) {
          const p = [...DATA.PRODUCTS, ...DATA.ACCESSORIES].find((x) => x.id === input.product_id);
          if (!p) throw new Error("No product with that id.");
          const jpeg = await productPhoto(p);
          if (!jpeg) throw new Error(`There's no photo of ${p.name} to send.`);
          await shareCardOnce(c);
          const sent = await imessage.sendPhoto(c.spaceId, jpeg, { name: `${p.id}.jpg` });
          const kept = await keepTextFile({ data: jpeg, mimeType: "image/jpeg", name: `${p.id}.jpg` });
          await inbox.say(c, `Photo of ${p.name}`, { textId: sent?.id, files: [kept] });
          return `Sent the photo of ${p.name}.`;
        },
        async hand_off(c, input) {
          const reason = String(input.reason || "").slice(0, 300);
          await inbox.say(c, `Handed to the team: ${reason}`, { action: true });
          await notifyShop(DATA.SITE.wholesaleEmail, `${c.spaceId ? "Text" : "Chat"} from ${c.name} needs you`, `${reason}

Reply in the Inbox: ${SITE_URL}/admin/inbox/${c.id}`);
          return `The team has been told and will ${c.spaceId ? "text them back here" : "reply here in the chat"}. Tell them so.`;
        },
};
const textAgent = client
  ? createTextAgent({
      client,
      // Fast and snappy: Haiku answers chats and texts, Opus only if it fails or declines.
      model: QUICK_MODEL,
      fallbackModel: MODEL,
      knowledge: () => SYSTEM_PROMPT,
      inbox,
      imessage,
      sendText,
      textFile,
      profile: (c) => assistantProfile(c),
      typing: (c, on) => (c.spaceId ? imessage.typing(c.spaceId, on) : (on ? chatTyping.add(c.id) : chatTyping.delete(c.id), Promise.resolve())),
      draft: (c, text) => (text ? chatDrafts.set(c.id, text) : chatDrafts.delete(c.id)),
      // Who on the team sent a reply (their first name; none for a shared address).
      staffName: (local) => {
        const x = senderOf(local);
        return x && !x.shared ? firstName(x.name) : "";
      },
    })
  : null;

/* ── The assistants: who's on the other end, and their tools (server/agents.js) ──
   A text from a staff phone gets the team's assistant; any other text, the wholesale one. The
   website chat gets the wholesale one for someone logged in to a wholesale account, and the
   shopper one otherwise. The back office Assistant page is the team's, too. */

const assistantStore = await storage.open("assistant", { notes: (x) => x.id, usual: (x) => x.id, proposals: (x) => x.id });
for (const k of ["notes", "usual", "proposals"]) assistantStore.data[k] ||= [];
// What it remembers, by subject ("user:<id>", "account:<id>", "team"): short facts, newest kept.
const memoryOf = (subject) => assistantStore.data.notes.filter((n) => n.subject === subject).slice(-30);
const memoryText = (subject) => {
  const notes = memoryOf(subject);
  return notes.length ? `\n\nWhat you remember (from earlier conversations):\n${notes.map((n) => `- ${n.text} (${dayOf(n.at)})`).join("\n")}` : "";
};
async function remember(subject, text) {
  const note = String(text || "").trim().slice(0, 300);
  if (!note) throw new Error("Nothing to remember.");
  if (memoryOf(subject).some((n) => n.text.toLowerCase() === note.toLowerCase())) return "Already noted.";
  assistantStore.data.notes.push({ id: randomUUID(), subject, text: note, at: new Date().toISOString() });
  // At most 30 per subject: the oldest go.
  const mine = assistantStore.data.notes.filter((n) => n.subject === subject);
  if (mine.length > 30) assistantStore.data.notes = assistantStore.data.notes.filter((n) => n.subject !== subject || mine.slice(-30).includes(n));
  await assistantStore.save();
  return "Noted.";
}
// A wholesale account's usual order.
const usualOf = (accountId) => assistantStore.data.usual.find((u) => u.id === accountId) || null;
const usualText = (accountId) => {
  const u = usualOf(accountId);
  const where = u?.location && (trade.account(accountId)?.locations || []).find((l) => l.id === u.location);
  return u ? `\n\nTheir usual order (saved ${dayOf(u.at)}): ${u.lines.map((l) => `${l.qty} × ${l.product} ${l.size}`).join(", ")}, ${u.fulfilment}${where ? ` to ${where.name}` : ""}.` : "";
};

// Staff phones (back office → Assistant): texts from them get the team's assistant.
const phoneKey = (p) => String(p || "").replace(/\D/g, "").slice(-10);
const staffPhones = () => (setting("staffPhones")?.value || []).map(phoneKey).filter((p) => p.length === 10);
const isStaffPhone = (p) => phoneKey(p).length === 10 && staffPhones().includes(phoneKey(p));
// The website chat's assistant can be switched off (back office → Assistant); on by default.
const chatAssistantOn = () => Boolean(client) && setting("chatAssistant")?.value !== false;
const chatTyping = new Set(); // chats the assistant is writing in (their window shows the dots)
const staffTyping = new Map<string, { until: number; name: string }>(); // ...and chats a teammate is writing a reply in
const teamTyping = (cid) => {
  const t = staffTyping.get(cid);
  return t && t.until > Date.now() ? t : null;
};
const chatDrafts = new Map<string, string>(); // ...and its reply so far, shown as it's written

function assistantProfile(c) {
  if (c.spaceId && isStaffPhone(c.phone)) {
    return { persona: MERCHANT_PERSONA("text"), tools: MERCHANT_TOOLS, readOnly: MERCHANT_READ_ONLY, actions: teamActionsFor(`conv:${c.id}`, c), context: () => teamContext() };
  }
  if (c.spaceId || convAccount(c)) return { persona: WHOLESALE_PERSONA, tools: TEXT_TOOLS, readOnly: WHOLESALE_READ_ONLY, actions: wholesaleActions, context: wholesaleContext };
  return { persona: SHOPPER_PERSONA, tools: SHOPPER_TOOLS, readOnly: SHOPPER_READ_ONLY, actions: shopperActions, context: shopperContext };
}

wholesaleActions.remember = async (c, input) => remember(`account:${textCustomer(c).id}`, input.note);
wholesaleActions.save_usual_order = async (c, input) => {
  const acct = textCustomer(c);
  await priceForText(acct, input); // it must be an order that can be placed
  const usual = { id: acct.id, lines: agentLines(input.lines), fulfilment: input.fulfilment, ...(input.fulfilment !== "Pickup" && locationNamed(acct, input.location) && { location: locationNamed(acct, input.location) }), at: new Date().toISOString() };
  assistantStore.data.usual = [...assistantStore.data.usual.filter((u) => u.id !== acct.id), usual];
  await assistantStore.save();
  await inbox.say(c, "Saved their usual order", { action: true });
  return "Saved as their usual.";
};

/* ── Shoppers ── */

const productLink = (id) => `${SITE_URL}/products/${encodeURIComponent(id)}`;
const shopItems = () => [
  ...DATA.PRODUCTS.map((p) => ({ id: p.id, kind: "coffee", name: p.name, short: p.short, type: p.type, notes: p.notes, region: p.region, process: p.process, about: p.about, price: p.price, price1kg: p.price1kg, sale: p.regular ? `was ${money(p.regular)}` : null, soldOut: Boolean(p.soldOut), left: p.left ?? null })),
  ...DATA.ACCESSORIES.filter((a) => a.price != null).map((a) => ({ id: a.id, kind: a.category === "Tea" ? "tea" : "accessory", name: a.name, short: a.short, type: a.type || a.category, notes: a.notes, about: [].concat(a.description || a.about || []).join(" "), price: a.price, pack: a.pack, sizes: a.sizes, colors: (a.colors || []).map((x) => x.name), soldOut: Boolean(a.soldOut), left: a.left ?? null })),
];
const shopperUser = (c) => (c.userId ? accounts.customer(c.userId) : null);
// An order as a card in the chat: where it is on its way, what's in it, and its tracking page.
async function orderCard(o) {
  const pickup = o.fulfilment === "Pickup" || Boolean(o.cafe);
  const steps = pickup ? ["Placed", "Being Made", "Ready", "Picked Up"] : ["Placed", "Packed", "Shipped", "Delivered"];
  const at = { new: 0, packed: 1, ready: 2, shipped: 2, completed: 3 }[o.status] ?? 0;
  return {
    type: "order",
    number: o.number,
    placed: o.placedAt.slice(0, 10),
    cancelled: o.status === "cancelled",
    steps,
    at,
    items: o.lines.map((l) => `${l.qty} × ${l.title}${l.variant ? ` (${l.variant})` : ""}`).slice(0, 4),
    more: Math.max(0, o.lines.length - 4),
    total: o.total,
    page: (await trackUrl(o)).replace(SITE_URL, ""),
  };
}
const shopperContext = (c) => {
  const u = shopperUser(c);
  return `Today is ${shopToday()}. ${u ? `They're logged in as ${u.name} (${u.email}).${memoryText(`user:${u.id}`)}` : "They're not logged in (a visitor): no account tools, and track_order needs their email."}`;
};
// The Mimi Food store as a connector for AI assistants (server/mcp.js) at /mcp: find coffees, teas
// and gear, see one, the shop's terms, and a checkout link with the cart filled in. Before the
// shop opens (SITE.shopLive) the checkout link isn't given.
const storeConnector = createMcp({
  name: "Mimi Food",
  title: "Mimi Food Coffee",
  version: "1.0.0",
  instructions: "Mimi Food is a specialty coffee roaster and tea shop in Los Angeles (Roastery House, 327 S Western Ave). Use search_products to find coffees, teas and brewing gear, get_product for sizes and grinds, store_info for shipping, returns and hours, and start_checkout to give the customer a link to our checkout with their cart filled in. Prices are in US dollars; payment happens on our site.",
  tools: [
    {
      name: "search_products",
      title: "Search products",
      description: "Find Mimi Food coffees, teas and brewing gear by taste, roast, origin or name (e.g. 'fruity light roast', 'decaf', 'oolong', 'dripper'). Returns up to 12 with prices, sizes and links.",
      inputSchema: { type: "object", properties: { query: { type: "string", description: "What they're looking for." }, kind: { type: "string", enum: ["coffee", "tea", "accessory"], description: "Only this kind." } }, required: ["query"] },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: async ({ query, kind }) => {
        const r: any = await shopperActions.search_catalog(null, { query });
        const items = r.items.filter((x) => !kind || x.kind === kind);
        return { matched: r.matched, items };
      },
    },
    {
      name: "get_product",
      title: "Get a product",
      description: "One product by its id (from search_products): description, price, sizes, grinds for coffee, and whether it's in stock.",
      inputSchema: { type: "object", properties: { id: { type: "string" } }, required: ["id"] },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: ({ id }) => shopperActions.get_product(null, { product: String(id || "") }),
    },
    {
      name: "store_info",
      title: "Shop info",
      description: "Mimi Food's shipping, local delivery, pickup, returns, subscriptions and Roastery House address and hours.",
      inputSchema: { type: "object", properties: {} },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: () => {
        const S = DATA.SITE;
        const roastery = DATA.LOCATIONS.find((l) => l.id === "roastery");
        return {
          shopOpen: Boolean(S.shopLive),
          shipping: `Ships across the US. Free over $${S.freeShippingOver}; otherwise up to $${S.postage?.maxFee ?? ""}. Roasted weekly and shipped 1–2 days after roasting.`,
          localDelivery: `Same-day courier delivery within ${S.localDelivery?.radiusMiles ?? 10} miles of Roastery House, up to $${S.localDelivery?.maxFee ?? ""}.`,
          pickup: "Free pickup at Roastery House.",
          returns: `Accessories can be returned within ${S.returns?.days ?? 14} days, unused. A return can be refunded to the card, taken as store credit, or swapped for another size or color. Coffee and tea can't be returned; damaged, wrong or missing items (coffee and tea too) are replaced or refunded: the customer reports it with a photo from their order page within ${S.claims?.days ?? 14} days of delivery.`,
          subscriptions: `Subscribe and save ${Math.round((DATA.SUBSCRIPTION?.discount || 0) * 100)}% with free shipping.`,
          roastery: roastery ? { name: roastery.name, address: roastery.address.join(", "), hours: "Every day, 9 AM–6 PM", phone: roastery.phone } : null,
          contact: S.email,
          website: SITE_URL,
        };
      },
    },
    {
      name: "start_checkout",
      title: "Start checkout",
      description: "A link to Mimi Food's checkout with these items in the cart, for the customer to open and pay. Coffee: size 250g or 1kg and a grind (from get_product). Gear: its size or color if it has them.",
      inputSchema: {
        type: "object",
        properties: { items: { type: "array", minItems: 1, maxItems: 10, items: { type: "object", properties: { product: { type: "string" }, qty: { type: "integer", minimum: 1, maximum: 10 }, size: { type: "string" }, grind: { type: "string" }, color: { type: "string" } }, required: ["product"] } } },
        required: ["items"],
      },
      annotations: { readOnlyHint: true, openWorldHint: false },
      run: ({ items }) => {
        if (!DATA.SITE.shopLive) throw new Error(`Mimi Food's online shop opens soon. Until then, visit Roastery House at 327 S Western Ave, Los Angeles, or join the list at ${SITE_URL} for the opening.`);
        const parts = [];
        const lines = [];
        let subtotal = 0;
        for (const it of [].concat(items || []).slice(0, 10)) {
          const qty = Math.max(1, Math.min(10, Math.floor(Number(it.qty) || 1)));
          const p = DATA.PRODUCTS.find((x) => x.id === it.product);
          const a = !p && DATA.ACCESSORIES.find((x) => x.id === it.product && x.price != null);
          if (!p && !a) throw new Error(`No product ${it.product}. Use search_products.`);
          if ((p || a).soldOut) throw new Error(`${(p || a).short || (p || a).name} is sold out.`);
          if (p) {
            const size = it.size === "1kg" ? "1kg" : "250g";
            const grind = DATA.grindsFor(p).includes(it.grind) ? it.grind : DATA.grindsFor(p)[0];
            const price = size === "1kg" ? p.price1kg : p.price;
            parts.push([p.id, size, grind, qty].join("~"));
            lines.push({ product: p.id, name: p.name, size, grind, qty, price });
            subtotal += price * qty;
          } else {
            if (a.sizes?.length && !a.sizes.includes(it.size)) throw new Error(`${a.name} comes in ${a.sizes.join(", ")}.`);
            const color = a.colors?.length ? (a.colors.find((c) => c.name === it.color) || a.colors[0]).name : "";
            parts.push([a.id, it.size || "", color, qty].join("~"));
            lines.push({ product: a.id, name: a.name, ...(it.size && { size: it.size }), ...(color && { color }), qty, price: a.price });
            subtotal += a.price * qty;
          }
        }
        return { checkoutUrl: `${SITE_URL}/checkout?cart=${encodeURIComponent(parts.join(","))}`, items: lines, subtotal: Math.round(subtotal * 100) / 100, note: "Shipping and tax are added at checkout." };
      },
    },
  ],
});
async function handleMcp(req, res) {
  const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type, Accept, Mcp-Protocol-Version, Mcp-Session-Id, Authorization", "Cache-Control": "no-store" };
  if (req.method === "OPTIONS") return send(res, 204, "", cors);
  if (req.method !== "POST") return send(res, 405, "Use POST with JSON-RPC (Model Context Protocol).", { ...cors, Allow: "POST, OPTIONS" });
  if (rateLimited(clientIp(req), "mcp", 120)) return sendJson(res, 429, { jsonrpc: "2.0", id: null, error: { code: -32000, message: "Too many requests. Try again in a few minutes." } }, cors);
  const raw = await readRaw(req).catch(() => "");
  if (raw.length > 100_000) return sendJson(res, 413, { jsonrpc: "2.0", id: null, error: { code: -32600, message: "Too large." } }, cors);
  const { status, body } = await storeConnector.handle(raw);
  if (!body) return send(res, status, "", cors);
  return sendJson(res, status, body, cors);
}

const shopperActions = {
  async search_catalog(c, { query }) {
    const words = String(query || "").toLowerCase().split(/[^\p{L}\p{N}]+/u).filter((w) => w.length > 2);
    const scored = shopItems().map((x) => {
      const hay = [x.name, x.type, x.notes, x.region, x.process, x.about, x.kind].join(" ").toLowerCase();
      return { x, score: words.reduce((n, w) => n + (hay.includes(w) ? (x.name.toLowerCase().includes(w) ? 3 : 1) : 0), 0) };
    });
    const hits = scored.filter((s) => s.score > 0).sort((a, b) => b.score - a.score).map((s) => s.x);
    const list = (hits.length ? hits : shopItems()).slice(0, 12);
    return { matched: hits.length > 0, items: list.map((x) => ({ ...x, about: x.about ? x.about.slice(0, 200) : undefined, link: productLink(x.id) })) };
  },
  async get_product(c, { product }) {
    const x = shopItems().find((i) => i.id === product);
    if (!x) throw new Error("No product with that id. Use search_catalog.");
    const p = DATA.PRODUCTS.find((i) => i.id === product);
    return { ...x, grinds: p ? DATA.grindsFor(p) : undefined, link: productLink(x.id) };
  },
  async add_to_cart(c, { items }) {
    if (!DATA.SITE.shopLive) throw new Error("Online ordering isn't open yet, so nothing can go in the cart. Tell them it's coming soon, and they can visit the roastery or join the list for news.");
    const cart = [];
    for (const it of (items || []).slice(0, 10)) {
      const qty = Math.max(1, Math.min(10, Math.floor(Number(it.qty) || 1)));
      const p = DATA.PRODUCTS.find((x) => x.id === it.product);
      const a = !p && DATA.ACCESSORIES.find((x) => x.id === it.product && x.price != null);
      if (!p && !a) throw new Error(`No product ${it.product}.`);
      if ((p || a).soldOut) throw new Error(`${(p || a).short || (p || a).name} is sold out.`);
      if (p) {
        const size = it.size === "1kg" ? "1kg" : "250g";
        const grind = DATA.grindsFor(p).includes(it.grind) ? it.grind : "Whole Bean";
        cart.push({ product: p.id, size, grind, qty });
      } else {
        if (a.sizes?.length && !a.sizes.includes(it.size)) throw new Error(`${a.name} comes in ${a.sizes.join(", ")}: ask which size.`);
        const colors = (a.colors || []).map((x) => x.name);
        if (colors.length && !colors.includes(it.color)) throw new Error(`${a.name} comes in ${colors.join(" or ")}: ask which.`);
        cart.push({ product: a.id, size: a.sizes?.length ? it.size : null, color: colors.length ? it.color : null, qty });
      }
    }
    if (!cart.length) throw new Error("Nothing to add.");
    return { cart, said: `Added to their cart (they'll see it): ${cart.map((l) => `${l.qty} × ${l.product}${l.size ? ` ${l.size}` : ""}`).join(", ")}. Checkout: ${SITE_URL}/checkout` };
  },
  async subscription_options() {
    const S = DATA.SUBSCRIPTION;
    return {
      rotating: S.coffees.map((x) => ({ id: x.id, label: x.label, note: x.note, sizes: S.sizes.filter((z) => !z.tea).map((z) => ({ size: z.label, cups: z.cups, price: DATA.subscriptionPrice(DATA.subscriptionCoffee(x.id), z.id)?.price })) })),
      discount: `${Math.round(S.discount * 100)}% off rotating coffees, ${Math.round(S.productDiscount * 100)}% off a single coffee subscribed from its page, ${Math.round(S.teaDiscount * 100)}% off tea`,
      frequencies: S.frequencies.map((f) => f.label),
      freeShipping: true,
      build: `${SITE_URL}/subscriptions/build`,
      gift: `${SITE_URL}/subscriptions/gift`,
    };
  },
  async track_order(c, { number, email }) {
    const o = orders.get(orderNumberOf(number));
    const u = shopperUser(c);
    const ok = o && o.status !== "pending_payment" && ((u && (o.userId === u.id || (u.verified && o.contact?.email === u.email))) || (email && String(o.contact?.email || "").toLowerCase() === String(email).trim().toLowerCase()));
    if (!ok) throw new Error("No order with that number and email.");
    return { number: o.number, placed: o.placedAt.slice(0, 10), status: o.status, payment: o.payment, fulfilment: o.fulfilment, items: o.lines.map((l) => `${l.qty} × ${l.title}${l.variant ? ` (${l.variant})` : ""}`), total: o.total, tracking: o.tracking?.url || null, page: await trackUrl(o), shown: "They see it as a card with its progress and items: don't repeat them, just add what helps.", cards: [await orderCard(o)] };
  },
  async my_orders(c) {
    const u = shopperUser(c);
    if (!u) throw new Error("They're not logged in: ask for the order number and email instead.");
    const list = ordersOf(u.id, u.verified ? u.email : null).filter((o) => o.status !== "pending_payment").slice(0, 8);
    return {
      orders: list.map((o) => ({ number: o.number, placed: o.placedAt.slice(0, 10), status: o.status, items: o.lines.map((l) => `${l.qty} × ${l.title}${l.variant ? ` (${l.variant})` : ""}`), total: o.total })),
      shown: "The latest one or two are shown as cards.",
      cards: await Promise.all(list.slice(0, 2).map(orderCard)),
    };
  },
  async my_subscriptions(c) {
    const u = shopperUser(c);
    if (!u) throw new Error("They're not logged in.");
    const subs = accounts.list(u.id).filter((s) => s.status !== "cancelled" && s.status !== "ended");
    return {
      subscriptions: subs.map((s) => ({ id: s.id, coffee: s.coffeeLabel, size: s.sizeLabel, every: s.freqLabel, price: s.price, status: s.status, nextDelivery: s.nextDelivery, gift: s.gift ? s.recipient : null })),
      manage: `${SITE_URL}/account`,
      shown: "Shown as cards with Skip and Pause/Resume buttons (tapping one asks you to do it).",
      cards: subs.slice(0, 3).map((s) => ({ type: "subscription", id: s.id, coffee: s.coffeeLabel, product: s.product, size: s.sizeLabel, every: s.freqLabel, price: s.price, status: s.status, next: s.nextDelivery, gift: s.gift ? s.recipient : null })),
    };
  },
  async change_subscription(c, { subscription, action }) {
    const u = shopperUser(c);
    if (!u) throw new Error("They're not logged in.");
    const sub = await accounts.update(u.id, subscription, { action }, { before: syncSubscription });
    await inbox.say(c, `${action === "skip" ? "Skipped the next delivery" : action === "pause" ? "Paused" : "Resumed"}: ${sub.coffeeLabel} subscription`, { action: true });
    return { status: sub.status, nextDelivery: sub.nextDelivery };
  },
  async remember(c, { note }) {
    const u = shopperUser(c);
    if (!u) throw new Error("Only for logged-in customers.");
    return remember(`user:${u.id}`, note);
  },
  async hand_off(c, { summary }) {
    const why = String(summary || "").slice(0, 300);
    await inbox.say(c, `Handed to the team: ${why}`, { action: true });
    await notifyShop(DATA.SITE.email, `Chat from ${c.name} needs you`, `${why}\n\nReply in the Inbox: ${SITE_URL}/admin/inbox/${c.id}`);
    return "The team has been told and will reply here in the chat. Tell them so.";
  },
};

/* ── The team ── */

const teamContext = () => `Today is ${shopToday()} (${new Date().toLocaleDateString("en-US", { weekday: "long", timeZone: DATA.SITE.timezone || "America/Los_Angeles" })}).${memoryText("team")}${teamSnapshot()}`;
// Where things stand right now, with every question: most everyday questions ("sales today?",
// "what's low?", "anything to pack?") are answered from it with no lookup, and each lookup is
// another trip to the model.
function teamSnapshot() {
  try {
    const today = shopToday();
    const week = addDaysTo(today, -6);
    const money2 = (n) => Math.round(n * 100) / 100;
    const sum = (list) => money2(list.reduce((n, o) => n + (o.payment === "unpaid" && !o.wholesale ? 0 : o.total - (o.refunded || 0)), 0));
    const sold = soldIn(today, today);
    const soldWeek = soldIn(week, today);
    const open = orders.list().filter((o) => ["new", "packed", "ready"].includes(o.status) && !o.parent);
    const low = stockItems(DATA)
      .map((i) => ({ i, left: stock.left(i.key), at: stock.reorderAt(i.key) ?? LOW_STOCK }))
      .filter((x) => x.left != null && x.left <= x.at)
      .map((x) => `${x.i.name}${x.i.variant ? ` (${x.i.variant})` : ""}: ${x.left} ${x.i.unit}`);
    const greenLow = green.items.filter((x) => x.reorderAt != null && x.onHand <= x.reorderAt).map((x) => `${x.name}: ${x.onHand} kg`);
    const roastsToday = green.batches.filter((b) => b.status === "planned" && b.date === today);
    const overdue = orders.list().filter((o) => o.wholesale && o.payment !== "paid" && o.status !== "cancelled" && o.wholesale.dueDate && o.wholesale.dueDate < today);
    const facts = {
      salesToday: { orders: sold.length, total: sum(sold) },
      salesLast7Days: { orders: soldWeek.length, total: sum(soldWeek) },
      toPack: open.filter((o) => o.status === "new").map((o) => `${[o.number, o.wholesale?.business || o.name].filter(Boolean).join(" ")} (${o.fulfilment})`).slice(0, 12),
      packedOrReady: open.filter((o) => o.status !== "new").length,
      inboxOpen: inbox.list("open").length,
      inboxUnread: inbox.list("open").filter((c) => c.unread).length,
      todosDueToday: todos.list.filter((t) => t.status === "open" && t.due && t.due <= today).map((t) => t.title).slice(0, 10),
      lowStock: low.slice(0, 15),
      greenCoffeeLow: greenLow.slice(0, 10),
      roastsPlannedToday: roastsToday.map((b) => `${coffeeName(b.product)} ${b.greenKg} kg`),
      deliveriesDue: trade.purchaseOrders.filter((p) => ["sent", "partial"].includes(p.status) && p.expected && p.expected <= today).map((p) => `${p.number} ${p.supplierName}`),
      wholesaleOverdue: overdue.map((o) => `${o.number} ${o.wholesale.business} ${money(o.total)} due ${o.wholesale.dueDate}`).slice(0, 10),
      importsToCheck: imports.list.filter((x) => x.status === "open").length,
    };
    return `\n\n# Right now\nAnswer from these when they cover the question; look things up only for more than they say.\n${JSON.stringify(facts)}`;
  } catch (error) {
    console.error("[assistant] snapshot:", error.message);
    return "";
  }
}
const dayOf = (iso) => new Intl.DateTimeFormat("en-CA", { timeZone: DATA.SITE.timezone || "America/Los_Angeles" }).format(new Date(iso));
const addDaysTo = (day, n) => new Date(Date.parse(`${day}T12:00:00Z`) + n * 864e5).toISOString().slice(0, 10);
function period(from, to) {
  const end = /^\d{4}-\d{2}-\d{2}$/.test(to || "") ? to : shopToday();
  const start = /^\d{4}-\d{2}-\d{2}$/.test(from || "") ? from : addDaysTo(end, -6);
  if (start > end) throw new Error("The first day is after the last.");
  const days = Math.round((Date.parse(end) - Date.parse(start)) / 864e5) + 1;
  return { from: start, to: end, days, before: { from: addDaysTo(start, -days), to: addDaysTo(start, -1) } };
}
const channelOf = (o) => (o.wholesale ? "wholesale" : o.source === "renewal" ? "subscriptions" : o.cafe ? "café" : "website");
// Sales booked in a period (wholesale invoices count when placed, paid or not).
const soldIn = (from, to) => orders.list().filter((o) => o.status !== "cancelled" && o.status !== "pending_payment" && !o.parent && dayOf(o.placedAt) >= from && dayOf(o.placedAt) <= to);
const r2 = (n) => Math.round(n * 100) / 100;
function totals(list) {
  const revenue = list.reduce((n, o) => n + o.total - (o.refunded || 0), 0);
  return { orders: list.length, revenue: r2(revenue), averageOrder: list.length ? r2(revenue / list.length) : 0, refunded: r2(list.reduce((n, o) => n + (o.refunded || 0), 0)) };
}
const change = (now, was) => (was ? `${now >= was ? "+" : ""}${Math.round(((now - was) / was) * 100)}%` : null);
const findProduct = (q) => {
  const s = String(q || "").toLowerCase().trim();
  const all = [...catalog.adminView().products.map((p) => ({ ...p, kind: "coffee" })), ...catalog.adminView().teas.map((t) => ({ ...t, kind: "tea" })), ...DATA.ACCESSORIES.filter((a) => a.category !== "Tea").map((a) => ({ ...a, kind: "accessory" }))];
  return all.find((p) => p.id === s) || all.find((p) => [p.name, p.short].some((n) => n && n.toLowerCase() === s)) || all.find((p) => [p.name, p.short].some((n) => n && n.toLowerCase().includes(s))) || null;
};
const accountByName = (q) => {
  const s = String(q || "").toLowerCase().trim();
  return trade.accounts.find((a) => a.id === q) || trade.accounts.find((a) => a.business.toLowerCase() === s) || trade.accounts.find((a) => a.business.toLowerCase().includes(s)) || null;
};

const teamReads = {
  async find_businesses(c, { area, type }) {
    const t = PROSPECT_TYPES[type] ? type : "cafe";
    try {
      const r = await research.discover({ area: String(area || "").slice(0, 100), type: t, query: PROSPECT_TYPES[t][1] });
      return { source: r.source, cost: r.cost, businesses: r.places.slice(0, 12).map((p) => ({ name: p.name, category: p.category, address: p.address, website: p.website, rating: p.facts.find((f) => f.key === "rating")?.value || null, alreadyOurs: alreadyKnown(p) })) };
    } catch (error) {
      if (error instanceof ResearchError) return { error: error.message };
      throw error;
    }
  },
  async research_business(c, { name, site, city }) {
    const parsed = parseSite(site);
    const r = await researchBusiness({ name: String(name || "").slice(0, 120), location: city || "", website: parsed.website, instagram: parsed.instagram, maps: true });
    return { name, fit: r.fit ? { score: r.fit.score, signals: r.fit.signals.map((x) => ({ signal: x.label, points: `${x.points}/${x.max}`, why: x.why || "not found", source: x.source })) } : null, facts: r.facts.slice(0, 20).map((f) => ({ [f.label]: f.value, source: f.source })), notes: r.notes, cost: r.cost };
  },
  async instagram_profile(c, { handle }) {
    try {
      const r = await research.readInstagram(String(handle || "").replace(/^@/, "").trim());
      return { handle: r.profile.username, name: r.profile.name, followers: r.profile.followers, posts: r.profile.posts, bio: r.profile.bio, authenticity: r.check ? { score: r.check.score, level: r.check.level, reasons: r.check.reasons.map((x) => x.text) } : null, via: r.via, cost: r.cost };
    } catch (error) {
      if (error instanceof ResearchError) return { error: error.message };
      throw error;
    }
  },
  async where_we_show_up(c, { query }) {
    if (query) {
      if (!research.paid()) return { error: "Paid lookups aren't connected." };
      return intel.visibility(String(query).slice(0, 120), intelSettings().area);
    }
    const v = intelRun("visibility");
    return v ? { checkedAt: v.at, results: v.result.results } : { error: "Not checked yet. Run it on Insights → Where We Show Up." };
  },
  async mentions() {
    const list = intelStore.data.mentions.filter((m) => m.status !== "hidden").slice(0, 15);
    return { checkedAt: intelRun("mentions")?.at || null, posts: list.map((m) => ({ platform: m.platform, author: m.author, kind: m.kind, caption: m.caption.slice(0, 200), likes: m.likes, comments: m.comments, at: m.at, url: m.url, status: m.status })) };
  },
  async coffee_market() {
    return marketView()?.found ? marketView() : { error: "Not checked yet. It runs daily, or from Purchasing." };
  },
  async sales_report(c, { from, to }) {
    const p = period(from, to);
    const now = soldIn(p.from, p.to);
    const was = soldIn(p.before.from, p.before.to);
    const t = totals(now);
    const tb = totals(was);
    const byChannel = {};
    for (const o of now) (byChannel[channelOf(o)] ||= []).push(o);
    const products: Record<string, any> = {};
    for (const o of now) for (const l of o.lines) {
      const k = l.title;
      products[k] ||= { product: k, units: 0, revenue: 0 };
      products[k].units += l.qty;
      products[k].revenue = r2(products[k].revenue + l.price * l.qty);
    }
    const emails = now.map((o) => o.contact?.email).filter(Boolean);
    const earlier = new Set(orders.list().filter((o) => dayOf(o.placedAt) < p.from).map((o) => o.contact?.email).filter(Boolean));
    return {
      period: { from: p.from, to: p.to, days: p.days },
      ...t,
      vsPeriodBefore: { ...p.before, ...tb, revenueChange: change(t.revenue, tb.revenue), ordersChange: change(t.orders, tb.orders) },
      byChannel: Object.fromEntries(Object.entries(byChannel).map(([k, v]) => [k, totals(v)])),
      topProducts: Object.values(products).sort((a, b) => b.revenue - a.revenue).slice(0, 10),
      customers: { total: new Set(emails).size, new: new Set(emails.filter((e) => !earlier.has(e))).size },
      codesUsed: Object.entries(now.reduce((m, o) => (o.discount?.code ? ((m[o.discount.code] = (m[o.discount.code] || 0) + 1), m) : m), {})).map(([code, uses]) => ({ code, uses })),
    };
  },
  async product_report(c, { product, from, to }) {
    const x = findProduct(product);
    if (!x) throw new Error("No product by that name or id. Try catalog.");
    const p = period(from || addDaysTo(shopToday(), -29), to);
    const lines = soldIn(p.from, p.to).flatMap((o) => o.lines.filter((l) => l.product === x.id || l.sub?.coffee === `p:${x.id}` || l.sub?.coffee === `t:${x.id}`).map((l) => ({ ...l, day: dayOf(o.placedAt), channel: channelOf(o) })));
    const bySize = {};
    const byWeek = {};
    for (const l of lines) {
      const size = l.size || l.variant || "—";
      bySize[size] = (bySize[size] || 0) + l.qty;
      const wk = addDaysTo(l.day, -((new Date(`${l.day}T12:00:00Z`).getUTCDay() + 6) % 7));
      byWeek[wk] = r2((byWeek[wk] || 0) + l.price * l.qty);
    }
    return {
      product: x.name, id: x.id, period: { from: p.from, to: p.to },
      units: lines.reduce((n, l) => n + l.qty, 0), revenue: r2(lines.reduce((n, l) => n + l.price * l.qty, 0)),
      bySize, revenueByWeekStarting: byWeek,
      byChannel: lines.reduce((m, l) => ((m[l.channel] = (m[l.channel] || 0) + l.qty), m), {}),
      subscribers: accounts.subscribedTo(`${x.kind === "tea" ? "t" : "p"}:${x.id}`),
      stockLeft: stock.left(x.id) ?? "not counted",
    };
  },
  async inventory() {
    const since = addDaysTo(shopToday(), -27);
    const sold = {};
    for (const o of soldIn(since, shopToday())) for (const u of stockUnits(o.lines)) sold[u.key] = (sold[u.key] || 0) + u.units;
    const waits = stock.waitCounts();
    return {
      lowAt: LOW_STOCK,
      items: stockItems(DATA).map((i) => {
        const left = stock.left(i.key);
        const perWeek = r2((sold[i.key] || 0) / 4);
        return { key: i.key, name: `${i.name}${i.variant ? ` (${i.variant})` : ""}`, kind: i.kind, unit: i.unit, left: left ?? "not counted", soldLast4Weeks: sold[i.key] || 0, weeksLeft: left != null && perWeek ? r2(left / perWeek) : null, waitingForRestock: waits[i.key] || 0 };
      }),
    };
  },
  async catalog() {
    const v = catalog.adminView();
    return {
      coffee: v.products.map((p) => ({ id: p.id, name: p.short || p.name, type: p.type, price250g: p.price, price1kg: p.price1kg, labels: p.badges, visible: p.visible, soldOut: Boolean(p.soldOut) })),
      tea: v.teas.map((t) => ({ id: t.id, name: t.short || t.name, pack: t.price, visible: t.visible, soldOut: Boolean(t.soldOut) })),
      accessories: DATA.ACCESSORIES.filter((a) => a.category !== "Tea" && a.price != null).map((a) => ({ id: a.id, name: a.name, price: a.price, note: "price set in the site's code, not the back office" })),
    };
  },
  async subscriptions_report() {
    const rows = accounts.exportRows();
    const live = rows.filter((s) => s.status === "active" && s.billing !== "prepaid");
    const month = addDaysTo(shopToday(), -30);
    const perMonth = { weekly: 52 / 12, biweekly: 26 / 12, monthly: 1 };
    const byCoffee = {};
    for (const s of live) byCoffee[`${s.coffeeLabel} ${s.sizeLabel}`] = (byCoffee[`${s.coffeeLabel} ${s.sizeLabel}`] || 0) + 1;
    return {
      active: live.length,
      paused: rows.filter((s) => s.status === "paused").length,
      prepaidGifts: rows.filter((s) => s.billing === "prepaid" && s.status === "active").length,
      startedLast30Days: rows.filter((s) => (s.createdAt || "") >= month).length,
      cancelledLast30Days: rows.filter((s) => s.status === "cancelled" && (s.updatedAt || s.createdAt || "") >= month).length,
      billsAMonth: r2(live.reduce((n, s) => n + (s.price || 0) * (perMonth[s.freq] || 1), 0)),
      byCoffee,
    };
  },
  async promotions() {
    const all = orders.list().filter((o) => o.discount?.code && o.payment !== "unpaid");
    return promos.list().map((p) => {
      const used = all.filter((o) => o.discount.code === p.code);
      return { code: p.code, kind: p.kind, value: p.value, active: p.active, uses: p.uses, maxUses: p.maxUses, endsOn: p.endsOn, minSubtotal: p.minSubtotal, salesWithIt: r2(used.reduce((n, o) => n + o.total, 0)), discountGiven: r2(used.reduce((n, o) => n + (o.discount.amount || 0), 0)) };
    });
  },
  async campaigns() {
    return {
      automations: automations.list().map((a) => ({ id: a.id, name: a.name, enabled: a.enabled, when: a.when, waiting: a.waiting, ...a.stats })),
      newsletters: newsletters.list().slice(0, 10).map((n) => ({ subject: n.subject, status: n.status, sentAt: n.sentAt || null, recipients: n.recipients ?? null })),
      subscribers: signups.data.emails.filter(confirmed).length,
    };
  },
  async wholesale_accounts() {
    return trade.accounts.filter((a) => !a.archivedAt).map((a) => {
      const theirs = orders.list().filter((o) => o.wholesale?.accountId === a.id && o.status !== "cancelled");
      const open = theirs.filter((o) => o.payment !== "paid" && o.total > 0);
      return { id: a.id, business: a.business, contact: a.contactName, discount: `${Math.round((1 - tradeFactor(a)) * 100)}% off retail`, terms: a.terms ? `${a.terms} days` : "on receipt", owed: r2(open.reduce((n, o) => n + o.total, 0)), overdue: open.filter((o) => o.wholesale?.dueDate && o.wholesale.dueDate < shopToday()).map((o) => ({ number: o.number, total: o.total, due: o.wholesale.dueDate })), lastOrder: theirs[0]?.placedAt?.slice(0, 10) || null, texts: Boolean(a.phone && inbox.byPhone(a.phone)) };
    });
  },
  async find_orders(c, { query }) {
    const q = String(query || "").trim().toLowerCase();
    const statuses = ["new", "packed", "shipped", "completed", "cancelled"];
    const hits = orders.list({}).filter((o) => o.status !== "pending_payment" && (statuses.includes(q) ? o.status === q : o.number.toLowerCase() === q || String(o.contact?.email || "").toLowerCase().includes(q) || String(o.contact?.name || "").toLowerCase().includes(q)));
    return hits.slice(0, 15).map((o) => ({ number: o.number, placed: o.placedAt.slice(0, 10), customer: o.contact?.name, email: o.contact?.email, channel: channelOf(o), status: o.status, payment: o.payment, total: o.total, items: o.lines.map((l) => `${l.qty} × ${l.title}`).join(", "), page: `${SITE_URL}/admin/orders/${o.number}` }));
  },
  async documents(c, { account }) {
    const acct = account ? accountByName(account) : null;
    if (account && !acct) throw new Error("No such account. Use wholesale_accounts.");
    const days = (iso) => Math.max(0, Math.floor((Date.now() - Date.parse(iso)) / 864e5));
    const list = documentsView().filter((d) => !acct || d.accountId === acct.id);
    const live = trade.accounts.filter((a) => !a.archivedAt && (!acct || a.id === acct.id));
    return {
      sign_before_ordering: contracts.template().required,
      agreement_version: contracts.template().version,
      documents: list.slice(0, 40).map((d) => ({ id: d.id, cafe: d.business, title: d.title, kind: d.kind === "custom" ? "one-off" : "wholesale agreement", status: d.status, ...(d.status === "draft" && { drafted: d.createdAt?.slice(0, 10), by: d.createdBy }), ...(d.sentAt && { sent: d.sentAt.slice(0, 10) }), ...(d.status === "sent" && { days_waiting: days(d.sentAt) }), ...(d.status === "signed" && { signed_by: d.signer?.name, signed: d.signedAt?.slice(0, 10) }), ...(d.kind !== "custom" && { version: d.version }) })),
      not_sent_the_agreement: live.filter((a) => !contracts.waiting(a.id) && !contracts.signed(a.id)).map((a) => a.business),
      page: `${SITE_URL}/admin/wholesale/documents`,
    };
  },
  async calls() {
    const s = calls.settings();
    const v = meetings.status();
    const day = (n) => ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][n];
    return {
      booking: s.on ? `On: ${s.days.map(day).join(", ")}, ${s.from} to ${s.to} Pacific, ${s.minutes} minutes each` : "Off: cafés can't book calls right now",
      video: v.connected ? `${v.connected.name}${v.connected.email ? ` (${v.connected.email})` : ""}` : "Not connected: calls are by phone",
      upcoming: calls.upcoming().slice(0, 20).map((b) => ({ when: `${callLabel(b.day, b.time)} (Pacific)`, minutes: b.minutes, cafe: b.business, booked_by: [b.name, b.email].filter(Boolean).join(", "), phone: b.phone || null, takes_it: b.whoName || "Anyone", about: b.note || null, join: b.meeting?.url || null })),
      page: `${SITE_URL}/admin/calls`,
    };
  },
  async waiting_messages() {
    return inbox.list().filter((x) => x.status === "open" && x.unread).slice(0, 20).map((x) => ({ who: x.name, subject: x.subject, channel: x.channel, last: x.last?.text, since: x.updatedAt, assistantAnswering: Boolean(x.agent), open: `${SITE_URL}/admin/inbox/${x.id}` }));
  },
};

// The back office shows what the assistant looked up as cards under its answer: a title, a few
// figures, a short list and a link to the page. (Texts get the words only.)
const usd = (n) => `${DATA.SITE.currency}${Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const cardDay = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const spanLabel = (p) => (p.from === p.to ? cardDay(p.from) : `${cardDay(p.from)} – ${cardDay(p.to)}`);
// An order's status as customers see it (portal, chat, texts).
const ORDER_STATUS_SAID = { new: "Received", packed: "Packed", shipped: "Shipped", ready: "Ready to collect", completed: "Completed", cancelled: "Cancelled" };
const STATUS_WORD = { new: "To pack", packed: "Packed", shipped: "Shipped", ready: "Ready", completed: "Completed", cancelled: "Cancelled" };
function teamCard(name, r) {
  if (!r || typeof r !== "object") return null;
  if (r.error) return null;
  if (name === "find_businesses")
    return { title: "Businesses", sub: r.source, link: { label: "Prospects", href: "#wholesale/prospects" }, rows: r.businesses.slice(0, 6).map((b) => ({ main: b.name, sub: [b.category, b.address].filter(Boolean).join(" · "), value: b.alreadyOurs ? `Already a${b.alreadyOurs === "account" ? "n account" : b.alreadyOurs === "enquiry" ? "n inquiry" : " prospect"}` : b.rating || "" })), rowsTitle: `${r.businesses.length} found` };
  if (name === "research_business")
    return { title: r.name, sub: "Wholesale fit", link: { label: "Prospects", href: "#wholesale/prospects" }, kpis: [{ label: "Fit", value: r.fit ? `${r.fit.score}/100` : "—" }, { label: "Facts", value: String(r.facts.length) }], rows: (r.fit?.signals || []).map((x) => ({ main: x.signal, sub: x.why, value: x.points })), rowsTitle: "Signals" };
  if (name === "instagram_profile")
    return { title: `@${r.handle}`, sub: r.name, kpis: [{ label: "Followers", value: Number(r.followers).toLocaleString("en-US") }, { label: "Genuine audience", value: r.authenticity ? `${r.authenticity.score}%` : "—" }], rows: (r.authenticity?.reasons || []).slice(0, 3).map((x) => ({ main: x, sub: "", value: "" })) };
  if (name === "where_we_show_up") {
    const list = r.results || [r];
    const engines = [["google", "Google"], ["localPack", "Maps"], ["aiOverview", "AI Overview"], ["chatgpt", "ChatGPT"], ["perplexity", "Perplexity"]];
    return { title: "Where we show up", sub: r.checkedAt ? `Checked ${new Date(r.checkedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : "Just now", link: { label: "Insights", href: "#insights/visibility" }, kpis: engines.map(([k, label]) => ({ label, value: `${list.filter((q) => q[k]?.found).length}/${list.length}` })), rows: list.slice(0, 4).map((q) => ({ main: q.query, sub: engines.filter(([k]) => q[k]?.found).map(([, l]) => l).join(", ") || "Not found", value: "" })) };
  }
  if (name === "mentions") return { title: "Mentions", sub: `${r.posts.length} recent`, link: { label: "Insights", href: "#insights/mentions" }, rows: r.posts.slice(0, 5).map((p) => ({ main: `@${p.author}`, sub: p.caption.slice(0, 80), value: p.platform })) };
  if (name === "coffee_market") return { title: "Coffee \"C\" price", sub: "Arabica futures", link: { label: "Green Coffee", href: "#purchasing" }, kpis: [{ label: "Per pound", value: usd(r.price / 100) }, { label: "Today", value: r.changePercent != null ? `${r.changePercent >= 0 ? "+" : ""}${r.changePercent.toFixed(1)}%` : "—" }] };
  if (name === "sales_report")
    return {
      title: "Sales", sub: spanLabel(r.period), link: { label: "Overview", href: "#overview" },
      kpis: [
        { label: "Revenue", value: usd(r.revenue), change: r.vsPeriodBefore?.revenueChange },
        { label: "Orders", value: String(r.orders), change: r.vsPeriodBefore?.ordersChange },
        { label: "Average order", value: usd(r.averageOrder) },
        { label: "Customers", value: String(r.customers?.total || 0), note: `${r.customers?.new || 0} new` },
      ],
      rows: (r.topProducts || []).slice(0, 3).map((x) => ({ main: x.product, sub: `${x.units} sold`, value: usd(x.revenue) })),
      rowsTitle: "Top sellers",
    };
  if (name === "product_report")
    return {
      title: r.product, sub: spanLabel(r.period),
      kpis: [{ label: "Revenue", value: usd(r.revenue) }, { label: "Sold", value: String(r.units) }, { label: "Subscribers", value: String(r.subscribers ?? 0) }, { label: "In stock", value: String(r.stockLeft) }],
      rows: Object.entries(r.bySize || {}).map(([size, n]) => ({ main: size, value: `${n} sold` })),
      rowsTitle: "By size",
    };
  if (name === "inventory") {
    const counted = (r.items || []).filter((i) => typeof i.left === "number");
    const low = counted.filter((i) => i.left <= r.lowAt || (i.weeksLeft != null && i.weeksLeft < 3)).sort((a, b) => a.left - b.left);
    const list = (low.length ? low : counted.sort((a, b) => a.left - b.left)).slice(0, 6);
    return {
      title: "Stock", sub: low.length ? `${low.length} running low` : "Nothing running low", link: { label: "Stock", href: "#products/stock" },
      rows: list.map((i) => ({ main: i.name, sub: i.left === 0 ? "Sold out" : i.weeksLeft == null ? `${i.soldLast4Weeks} sold in 4 weeks` : i.weeksLeft < 1 ? "Under a week left" : `About ${Math.round(i.weeksLeft)} ${Math.round(i.weeksLeft) === 1 ? "week" : "weeks"} left`, value: `${i.left} ${i.unit || "left"}`, tone: i.left === 0 ? "bad" : low.includes(i) ? "warn" : "" })),
    };
  }
  if (name === "subscriptions_report")
    return {
      title: "Subscriptions", link: { label: "Subscriptions", href: "#subscriptions" },
      kpis: [{ label: "Active", value: String(r.active) }, { label: "Billed a month", value: usd(r.billsAMonth) }, { label: "Started", value: String(r.startedLast30Days), note: "30 days" }, { label: "Cancelled", value: String(r.cancelledLast30Days), note: "30 days" }],
      rows: Object.entries(r.byCoffee || {}).sort((a: any, b: any) => b[1] - a[1]).slice(0, 3).map(([k, n]) => ({ main: k, value: `${n} active` })),
      rowsTitle: "Most subscribed",
    };
  if (name === "promotions" && Array.isArray(r))
    return {
      title: "Discount codes", sub: `${r.filter((x) => x.active).length} on`, link: { label: "Codes", href: "#products/codes" },
      rows: [...r].sort((a, b) => b.salesWithIt - a.salesWithIt).slice(0, 6).map((x) => ({ main: x.code, sub: `${x.uses || 0} ${x.uses === 1 ? "use" : "uses"} · ${usd(x.salesWithIt)} in sales`, value: x.active ? "On" : "Off", tone: x.active ? "good" : "" })),
    };
  if (name === "campaigns")
    return {
      title: "Emails", sub: `${r.subscribers} on the list`, link: { label: "Automations", href: "#signups/automations" },
      rows: (r.automations || []).slice(0, 6).map((a) => ({ main: a.name, sub: `${a.sent30 || 0} sent in 30 days · ${usd(a.revenue)} after`, value: a.enabled ? "On" : "Off", tone: a.enabled ? "good" : "" })),
    };
  if (name === "wholesale_accounts" && Array.isArray(r)) {
    const owed = r.reduce((n, a) => n + (a.owed || 0), 0);
    return {
      title: "Wholesale", sub: owed ? `${usd(owed)} owed` : "Nothing owed", link: { label: "Accounts", href: "#wholesale/accounts" },
      rows: [...r].sort((a, b) => b.owed - a.owed).slice(0, 6).map((a) => ({ main: a.business, sub: a.overdue?.length ? `${a.overdue.length} overdue` : `Terms ${a.terms}`, value: usd(a.owed), tone: a.overdue?.length ? "bad" : "" })),
    };
  }
  if (name === "find_orders" && Array.isArray(r))
    return r.length
      ? { title: "Orders", sub: `${r.length} found`, rows: r.slice(0, 6).map((o) => ({ main: o.number, sub: `${o.customer || o.email || ""} · ${cardDay(o.placed)}`, value: usd(o.total), badge: STATUS_WORD[o.status] || o.status, order: o.number, status: o.status })) }
      : null;
  if (name === "waiting_messages" && Array.isArray(r))
    return {
      title: "Inbox", sub: r.length ? `${r.length} waiting` : "All caught up", link: { label: "Inbox", href: "#inbox" },
      rows: r.slice(0, 5).map((x) => ({ main: x.who || "Visitor", sub: x.last || x.subject, value: x.channel === "imessage" ? "Text" : x.channel === "chat" ? "Chat" : "Email", href: `#inbox/${String(x.open).split("/").pop()}` })),
    };
  return null;
}

// Proposals: what the team's assistant wants to change, kept until approved or dismissed.
const proposalView = (p) => ({ id: p.id, kind: p.kind, summary: p.summary, status: p.status });
async function propose(where, kind, args, summary) {
  const p = { id: `prop-${randomBytes(4).toString("hex")}`, where, kind, args, summary, status: "waiting", at: new Date().toISOString() };
  assistantStore.data.proposals = [...assistantStore.data.proposals.filter((x) => Date.parse(x.at) > Date.now() - 7 * 864e5), p];
  await assistantStore.save();
  return { proposal: p.id, summary, status: "Waiting for their approval. Nothing has changed yet." };
}
// Carries out an approved proposal, through the same code as the back office pages.
async function carryOut(p, by) {
  if (p.status !== "waiting") throw new Error(p.status === "done" ? "That's already done." : p.status === "working" ? "That's being done now." : "That proposal was dismissed.");
  p.status = "working"; // a second tap on Approve meanwhile is turned away
  try {
    return await carryOutNow(p, by);
  } catch (error) {
    p.status = "waiting";
    throw error;
  }
}
async function carryOutNow(p, by) {
  const a = p.args;
  let result;
  if (p.kind === "price") {
    const x = findProduct(a.product);
    if (x?.kind === "coffee") {
      await catalog.updateProduct(x.id, a.size === "1kg" ? { price1kg: a.price } : { price: a.price });
      syncCatalog();
      await pushProduct(x.id);
    } else if (x?.kind === "tea") {
      await catalog.updateTea(x.id, { price: a.price });
      syncCatalog();
    } else throw new Error("That price is set in the site's code, not the back office.");
    result = `Price changed: ${x.short || x.name}${a.size === "1kg" ? " 1kg" : ""} ${money(a.price)}.`;
  } else if (p.kind === "productedit") {
    await catalog.updateProduct(a.product, a.changes);
    syncCatalog();
    const warning = await pushProduct(a.product);
    result = `${findProduct(a.product)?.short || a.product} updated.${warning ? ` ${warning}` : ""}`;
  } else if (p.kind === "reply") {
    const c = inbox.get(a.conversation);
    await inbox.reply(c.id, a.text);
    result = `Reply sent to ${c.name || c.phone || c.email}.`;
  } else if (p.kind === "po") {
    const po = await trade.createPurchaseOrder({ supplierId: a.supplierId, items: a.items, notes: a.notes });
    result = `Draft ${po.number} saved in Purchasing. Send it from there.`;
  } else if (p.kind === "prospect") {
    const x = prospectStore.data.prospects.find((y) => y.id === a.id);
    if (!x) throw new Error("That prospect is gone.");
    x.status = a.status;
    x.decidedAt = new Date().toISOString();
    await prospectStore.save();
    result = `${x.name}: ${{ approved: "approved", rejected: "marked not a fit", new: "back to review" }[a.status]}.`;
  } else if (p.kind === "stock") {
    await stock.set(a.key, a.left, { reason: "Set by the assistant" });
    syncCatalog();
    result = a.left == null ? `Stopped counting ${a.key}.` : `Stock set: ${a.key} ${a.left}.`;
  } else if (p.kind === "soldout") {
    const x = findProduct(a.product);
    if (x?.kind === "coffee") await catalog.updateProduct(x.id, { soldOut: a.sold_out });
    else if (x?.kind === "tea") await catalog.updateTea(x.id, { soldOut: a.sold_out });
    else throw new Error("Only coffees and teas can be marked here.");
    syncCatalog();
    result = `${x.short || x.name} is ${a.sold_out ? "sold out" : "back on sale"}.`;
  } else if (p.kind === "code") {
    await promos.create({ code: a.code, kind: a.kind, value: a.value, endsOn: a.ends_on || "", maxUses: a.max_uses || 0, minSubtotal: a.min_subtotal || 0 });
    result = `Code ${String(a.code).toUpperCase()} is live.`;
  } else if (p.kind === "codeswitch") {
    const code = promos.list().find((x) => x.code === String(a.code).toUpperCase());
    if (!code) throw new Error("No such code.");
    await promos.update(code.id, { active: a.active });
    result = `Code ${code.code} is ${a.active ? "on" : "off"}.`;
  } else if (p.kind === "automation") {
    await automations.update(a.id, { enabled: a.enabled });
    result = `${automations.get(a.id).name} is ${a.enabled ? "on" : "off"}.`;
  } else if (p.kind === "message") {
    const acct = accountByName(a.account);
    if (!acct) throw new Error("No such account.");
    if (a.via === "text") {
      const conv = inbox.byPhone(acct.phone);
      if (!conv) throw new Error(`${acct.business} hasn't texted us yet, so only email works.`);
      const sent = await sendText(conv, a.text);
      await inbox.say(conv, a.text, { textId: sent?.id });
    } else {
      if (!emailConfigured()) throw new Error("Email isn't set up.");
      await sendEmail({ kind: "wholesale", to: acct.email, subject: `A note from ${DATA.SITE.name}`, text: `${a.text}\n\n${DATA.SITE.name}`, html: emailHtml(a.text, "", null, { contact: DATA.SITE.wholesaleEmail }), replyTo: replyAddress(DATA.SITE.wholesaleEmail) });
    }
    result = `Sent to ${acct.business} by ${a.via}.`;
  } else if (p.kind === "senddoc") {
    const d = await sendDocument(a.id, by === "back office" ? "Assistant" : by);
    result = `“${d.title}” sent to ${d.business} to sign.`;
  } else if (p.kind === "sendagreement") {
    const acct = trade.account(a.account);
    if (!acct) throw new Error("No such account.");
    await sendAgreement(acct, "Assistant");
    result = `The agreement went to ${acct.business}.`;
  } else if (p.kind === "withdrawdoc") {
    const d = await contracts.withdraw(a.id, "Assistant");
    result = `“${d.title}” for ${d.business} withdrawn.`;
  } else throw new Error("Unknown proposal.");
  p.status = "done";
  p.doneAt = new Date().toISOString();
  p.by = by;
  await assistantStore.save();
  console.log(`[assistant] ${p.id} done (${by}): ${result}`);
  return result;
}

// The team's tools, for one place (`where`: "admin" or "conv:<id>"); `c` is the text thread.
function teamActionsFor(where, c = null) {
  const read = Object.fromEntries(Object.entries(teamReads).map(([k, f]) => [k, (cc, input) => f(cc, input || {})]));
  return {
    ...read,
    async propose_price(cc, { product, size, price }) {
      const x = findProduct(product);
      if (!x) throw new Error("No product by that name or id.");
      if (!(price > 0 && price < 10000)) throw new Error("Give a price in dollars.");
      const was = x.kind === "coffee" ? (size === "1kg" ? x.price1kg : x.price) : x.price;
      return propose(where, "price", { product: x.id, size, price: r2(price) }, `${x.short || x.name}${x.kind === "coffee" ? ` ${size === "1kg" ? "1kg" : "250g"}` : ""}: ${money(was)} → ${money(price)}`);
    },
    async propose_stock(cc, { key, left }) {
      const item = stockItems(DATA).find((i) => i.key === key);
      if (!item) throw new Error("No such stock key. Use inventory.");
      return propose(where, "stock", { key, left }, `${item.name}${item.variant ? ` (${item.variant})` : ""}: ${stock.left(key) ?? "not counted"} → ${left ?? "not counted"}`);
    },
    async propose_product_edit(cc, args) {
      const x = findProduct(args.product);
      if (!x || x.kind !== "coffee") throw new Error("Only coffees can be edited here. Use the product id.");
      const p = catalog.adminView().products.find((y) => y.id === x.id);
      const changes: any = {};
      const said = [];
      for (const [k, label] of [["about", "About"], ["notes", "Tasting notes"], ["region", "Region"], ["process", "Process"], ["variety", "Variety"], ["altitude", "Altitude"]]) {
        if (args[k] == null) continue;
        changes[k] = String(args[k]).trim();
        said.push(`${label}: “${changes[k].slice(0, 80)}”`);
      }
      if (args.supplier != null) {
        const s = args.supplier ? trade.suppliers.find((y) => !y.archivedAt && (y.id === args.supplier || y.name.toLowerCase() === String(args.supplier).toLowerCase())) : null;
        if (args.supplier && !s) throw new Error(`No supplier called ${args.supplier}. Suppliers: ${trade.suppliers.filter((y) => !y.archivedAt).map((y) => y.name).join(", ") || "none yet"}.`);
        changes.supplierId = s?.id || "";
        said.push(`Supplier: ${s?.name || "none"}`);
      }
      for (const [k, f, label] of [["cost_250g", "cost250", "Cost 250g"], ["cost_1kg", "cost1kg", "Cost 1kg"]]) {
        if (args[k] == null) continue;
        if (!(args[k] >= 0 && args[k] < 10000)) throw new Error("Give a cost in dollars.");
        changes[f] = String(r2(args[k]));
        said.push(`${label}: ${p[f] != null ? `${money(p[f])} → ` : ""}${money(args[k])}`);
      }
      if (args.in_shop != null) {
        changes.visible = Boolean(args.in_shop);
        said.push(args.in_shop ? "Show in the shop" : "Hide from the shop");
      }
      if (!said.length) throw new Error("Say what to change.");
      return propose(where, "productedit", { product: x.id, changes }, `${x.short || x.name}: ${said.join("; ")}`);
    },
    async propose_reply(cc, { conversation, text }) {
      let conv;
      try {
        conv = inbox.get(String(conversation));
      } catch {
        throw new Error("No such conversation. Use the open one's id.");
      }
      if (!String(text).trim()) throw new Error("Write the reply.");
      return propose(where, "reply", { conversation: conv.id, text: String(text).slice(0, 4000) }, `Reply to ${conv.name || conv.phone || conv.email}: “${String(text).slice(0, 160)}${String(text).length > 160 ? "…" : ""}”`);
    },
    async propose_purchase_order(cc, { supplier, items, notes }) {
      const s = trade.suppliers.find((y) => !y.archivedAt && (y.id === supplier || y.name.toLowerCase() === String(supplier).toLowerCase()));
      if (!s) throw new Error(`No supplier called ${supplier}. Suppliers: ${trade.suppliers.filter((y) => !y.archivedAt).map((y) => y.name).join(", ") || "none yet"}.`);
      const lines = (items || []).map((i) => ({ description: i.description, qty: i.qty, unit: i.unit, unitCost: i.unit_cost }));
      if (!lines.length) throw new Error("Add at least one line.");
      const total = lines.reduce((n, i) => n + i.qty * i.unitCost, 0);
      return propose(where, "po", { supplierId: s.id, items: lines, notes: notes || "" }, `Draft purchase order to ${s.name}: ${lines.map((i) => `${i.qty} ${i.unit} ${i.description}`).join(", ")} (${money(total)})`);
    },
    async propose_prospect(cc, { prospect, status }) {
      const p = prospectStore.data.prospects.find((x) => x.id === prospect || x.name.toLowerCase() === String(prospect).toLowerCase());
      if (!p) throw new Error("No prospect by that name or id.");
      return propose(where, "prospect", { id: p.id, status }, `${p.name}: ${{ approved: "approve", rejected: "not a fit", new: "back to review" }[status]}`);
    },
    async propose_sold_out(cc, { product, sold_out }) {
      const x = findProduct(product);
      if (!x) throw new Error("No product by that name or id.");
      return propose(where, "soldout", { product: x.id, sold_out }, `${x.short || x.name}: ${sold_out ? "mark sold out" : "back on sale"}`);
    },
    async propose_code(cc, args) {
      const code = String(args.code || "").toUpperCase();
      if (promos.list().some((p) => p.code === code)) throw new Error(`There's already a code ${code}.`);
      const what = args.kind === "freeship" ? "free shipping" : args.kind === "percent" ? `${args.value}% off` : `${money(args.value)} off`;
      return propose(where, "code", { ...args, code }, `New code ${code}: ${what}${args.min_subtotal ? ` on ${money(args.min_subtotal)}+` : ""}${args.max_uses ? `, ${args.max_uses} uses` : ""}${args.ends_on ? `, until ${args.ends_on}` : ""}`);
    },
    async propose_code_switch(cc, { code, active }) {
      const c0 = promos.list().find((p) => p.code === String(code).toUpperCase());
      if (!c0) throw new Error("No such code.");
      return propose(where, "codeswitch", { code: c0.code, active }, `Code ${c0.code}: switch ${active ? "on" : "off"}`);
    },
    async propose_automation(cc, { id, enabled }) {
      const a = automations.list().find((x) => x.id === id);
      if (!a) throw new Error("No such automation. Use campaigns.");
      return propose(where, "automation", { id, enabled }, `${a.name}: switch ${enabled ? "on" : "off"}`);
    },
    async propose_message(cc, { account, via, text }) {
      const acct = accountByName(account);
      if (!acct) throw new Error("No such account. Use wholesale_accounts.");
      if (via === "text" && !inbox.byPhone(acct.phone)) throw new Error(`${acct.business} hasn't texted us yet: offer email instead.`);
      return propose(where, "message", { account: acct.id, via, text: String(text).slice(0, 1500) }, `${via === "text" ? "Text" : "Email"} ${acct.business}: “${String(text).slice(0, 160)}${String(text).length > 160 ? "…" : ""}”`);
    },
    async draft_document(cc, { account, title, text }) {
      const acct = accountByName(account);
      if (!acct) throw new Error("No such account. Use wholesale_accounts.");
      const d = await contracts.draft(acct, { title, text }, "Assistant");
      return { draft: d.id, cafe: acct.business, open: `${SITE_URL}/admin/wholesale/documents`, note: "A draft only: the team reads it in Wholesale › Documents, then sends it (or you propose_send_document)." };
    },
    async propose_send_document(cc, { document_id }) {
      const d = contracts.find(document_id);
      if (!d || d.kind !== "custom") throw new Error("No such document. Use documents.");
      if (d.status !== "draft") throw new Error(`It's ${d.status === "sent" ? "already waiting to be signed" : d.status}.`);
      return propose(where, "senddoc", { id: d.id }, `Send “${d.title}” to ${d.business} to sign`);
    },
    async propose_send_agreement(cc, { account }) {
      const acct = accountByName(account);
      if (!acct) throw new Error("No such account. Use wholesale_accounts.");
      const w = contracts.waiting(acct.id);
      return propose(where, "sendagreement", { account: acct.id }, `${w ? "Send again" : "Send"}: ${contracts.template().via === "usign" ? contracts.template().usign?.name || "the agreement" : contracts.template().title} to ${acct.business}`);
    },
    async propose_withdraw_document(cc, { document_id }) {
      const d = contracts.find(document_id);
      if (!d) throw new Error("No such document. Use documents.");
      if (d.status !== "sent") throw new Error("Only a document waiting to be signed can be withdrawn.");
      return propose(where, "withdrawdoc", { id: d.id }, `Withdraw “${d.title}” sent to ${d.business}`);
    },
    async draft_newsletter(cc, { subject, heading, body }) {
      const n = await newsletters.create({ subject, blocks: [{ id: "b1", type: "heading", text: heading }, { id: "b2", type: "text", text: body }] });
      return { draft: n.id, open: `${SITE_URL}/admin/signups/newsletters/${n.id}`, note: "A draft only: they review and send it from the back office." };
    },
    async approve(cc, { proposal }) {
      const p = assistantStore.data.proposals.find((x) => x.id === proposal && x.where === where);
      if (!p) throw new Error("No such proposal in this conversation.");
      // Texts only: their yes must come after the proposal.
      const lastIn = c && [...c.messages].reverse().find((m) => m.from === "customer");
      if (!lastIn || lastIn.at < p.at) throw new Error("They haven't said yes since it was proposed.");
      return carryOut(p, `text ${c.phone}`);
    },
    async remember(cc, { note }) {
      return remember("team", note);
    },
  };
}

// Back office → Assistant: one answer, with any proposals it made for the buttons.
// The back office chat, with any photos, PDFs and text files on the user's messages as
// content blocks. Ten files at most go to the model, the newest kept; older ones are named.
const ASSIST_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/gif"];
function assistantMessages(input) {
  const list = (Array.isArray(input) ? input : []).slice(-20);
  let budget = 10;
  const out = [];
  for (let i = list.length - 1; i >= 0; i--) {
    const m = list[i] || {};
    const role = m.role === "assistant" ? "assistant" : "user";
    const text = String(m.content || "").slice(0, 8000);
    const blocks = [];
    const unread = [];
    const named = (Array.isArray(m.filesNamed) ? m.filesNamed : []).map((n) => String(n).slice(0, 120));
    for (const f of role === "user" && Array.isArray(m.files) ? m.files.slice(0, 5) : []) {
      const name = String(f?.name || "file").slice(0, 120);
      const data = typeof f?.data === "string" ? f.data : "";
      if (!data || budget <= 0) {
        named.push(name);
        continue;
      }
      if (f.kind === "image" && ASSIST_IMAGE_TYPES.includes(f.type) && data.length < 7_000_000) blocks.push({ type: "image", source: { type: "base64", media_type: f.type, data } });
      else if (f.kind === "pdf" && f.type === "application/pdf" && data.length < 14_000_000) blocks.push({ type: "document", source: { type: "base64", media_type: "application/pdf", data }, title: name });
      else if (f.kind === "text" && data.length <= 300_000) blocks.push({ type: "document", source: { type: "text", media_type: "text/plain", data }, title: name });
      else {
        unread.push(name);
        continue;
      }
      budget--;
    }
    const note = [named.length && `(Attached earlier, no longer available: ${named.join(", ")})`, unread.length && `(Couldn't read: ${unread.join(", ")})`].filter(Boolean).join(" ");
    const words = [text, note].filter(Boolean).join("\n\n") || (blocks.length ? "What's in this?" : "");
    if (!words && !blocks.length) continue;
    out.unshift({ role, content: blocks.length ? [...blocks, { type: "text", text: words }] : words });
  }
  return out;
}

// Asked from the panel beside another back office page: the page, and the order if one is open.
function lookingAt(context) {
  const page = String(context?.page || "").replace(/[^a-z]/g, "").slice(0, 20);
  const sub = String(context?.sub || "").replace(/[^a-z_-]/g, "").slice(0, 20);
  const number = /^MF-[A-Z0-9]{1,12}$/.test(String(context?.order || "")) ? context.order : null;
  const order = number && orders.get(number);
  if (order) return `They're looking at order ${order.number} in the back office right now ("this order" means it):\n${orderText(order)}\nStatus: ${order.status}. Payment: ${order.payment}. Customer: ${order.contact?.name || ""} <${order.contact?.email || ""}>.`;
  const where = page && page !== "assistant" ? `They're on the ${page} page${sub ? ` (${sub})` : ""} of the back office.` : "";
  const open = onScreen(context);
  if (open) return `${where} Open on their screen ("this", "it" and "here" mean it):\n${open}`;
  const list = pageList(page, sub);
  return list ? `${where} What the page lists ("these", "here" mean them):\n${list}` : where;
}

// The list a back office page shows (its tab), a line each, for questions about "these".
function pageList(page, sub) {
  const rows = (list, line, n = 25) => (list.length ? `${list.slice(0, n).map(line).join("\n")}${list.length > n ? `\n…and ${list.length - n} more` : ""}` : "None.");
  const age = (iso) => `${Math.max(0, Math.round((Date.now() - Date.parse(iso)) / 36e5))}h ago`;
  switch (page) {
    case "orders": {
      const status = sub || "new";
      const list = orders.list().filter((o) => o.status === status && !o.parent).sort((a, b) => b.placedAt.localeCompare(a.placedAt));
      return `Orders, ${status}:\n${rows(list, (o) => `${o.number} ${o.contact?.name || ""}, ${money(o.total)}, ${o.payment}, ${o.fulfilment || (o.cafe ? "café" : "")}, placed ${age(o.placedAt)}`)}`;
    }
    case "inbox": {
      const list = inbox.list("open");
      return `Open conversations:\n${rows(list, (c) => { const v = inbox.summary(c); return `${v.name || v.phone || v.email} (${v.channel}${v.unread ? ", unread" : ""}): ${v.last ? `${v.last.from === "customer" ? "they" : "we"} said “${v.last.text.slice(0, 100)}”` : ""}, ${age(c.updatedAt)}`; })}`;
    }
    case "customers": {
      const list = accounts.customers().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
      return `Customers (${list.length}), newest first:\n${rows(list, (c) => `${c.name || ""} <${c.email}>`, 15)}`;
    }
    case "products": {
      const v = catalog.adminView();
      return `Coffees:\n${rows(v.products, (p) => `${p.name}: ${money(p.price)} 250g / ${money(p.price1kg)} 1kg${p.cost250 != null ? `, cost ${money(p.cost250)}` : ""}${p.soldOut ? ", sold out" : ""}${p.visible ? "" : ", hidden"}`)}\nTeas:\n${rows(v.teas, (t) => `${t.name}: ${t.price != null ? money(t.price) : "no price"}${t.soldOut ? ", sold out" : ""}`)}`;
    }
    case "menu": {
      const m = catalog.menuView();
      return m.sections.map((sec) => `${sec.title}: ${sec.items.map((i) => `${i.name} ${money(i.price)}${i.soldOut ? " (sold out)" : ""}`).join(", ")}`).join("\n");
    }
    case "purchasing":
      return sub === "suppliers"
        ? `Suppliers:\n${rows(trade.suppliers.filter((x) => !x.archivedAt), (x) => `${x.name}${x.contactName ? `, ${x.contactName}` : ""}${x.email ? ` <${x.email}>` : ""}`)}`
        : `Purchase orders:\n${rows(trade.purchaseOrders, (po) => `${po.number} ${po.supplierName}, ${po.status}, ${money(po.total)}`)}`;
    case "wholesale": {
      if (sub === "accounts") return `Wholesale accounts:\n${rows(trade.accounts.filter((a) => !a.archivedAt), (a) => `${a.business}, Net ${a.terms}, ${trade.pricing(a).discount}% off${a.priceList ? ` (price list ${trade.pricing(a).priceListName})` : ""}`)}`;
      if (sub === "enquiries") return `Inquiries:\n${rows([...wholesale.data.enquiries].sort((a, b) => b.receivedAt.localeCompare(a.receivedAt)), (e) => `${e.business} (${e.type || ""}), ${e.name}, ${e.location || ""}, ${age(e.receivedAt)}${e.accountId ? ", made an account" : ""}`)}`;
      if (sub === "prospects") return `Prospects:\n${rows(prospectStore.data.prospects, (x) => `${x.name} (${x.category || x.type || ""}, ${x.city || x.area || ""}): ${x.status}${x.research?.fit?.score != null ? `, fit ${x.research.fit.score}` : ""}`)}`;
      const list = orders.list().filter((o) => o.source === "wholesale" && o.status !== "cancelled").sort((a, b) => b.placedAt.localeCompare(a.placedAt));
      return `Wholesale orders:\n${rows(list, (o) => `${o.number} ${o.wholesale?.business || ""}, ${money(o.total)}, ${o.status}, ${o.payment}`)}`;
    }
    case "reviews":
      return `Latest reviews:\n${rows(reviews.list(), (r) => `${r.rating}★ ${r.product}: “${String(r.text || "").slice(0, 100)}”`, 15)}`;
    default:
      return "";
  }
}

// The record open in the back office (a side panel, or the page's editor), as a few lines of what
// it says, for the assistant. Null when nothing is open or it's gone.
function onScreen(context) {
  const clip = (o) => JSON.stringify(o).slice(0, 2500);
  const conv = String(context?.conversation || "");
  if (conv) {
    try {
      const c = inbox.get(conv);
      return `Inbox conversation ${c.id} with ${c.name || c.phone || c.email} (${c.channel}${c.box ? `, ${c.box}` : ""}), ${c.status}:\n${c.messages
        .slice(-8)
        .map((m) => `${m.from === "customer" ? c.name || "Them" : "Us"}: ${String(m.text).slice(0, 300)}`)
        .join("\n")}`;
    } catch {
      return null;
    }
  }
  const [kind, id] = String(context?.record || "").split(/:(.+)/);
  if (!kind || !id) return null;
  const view = catalog.adminView();
  switch (kind) {
    case "product": {
      const p = view.products.find((x) => x.id === id);
      if (!p) return null;
      const supplier = p.supplierId ? trade.supplier(p.supplierId)?.name : null;
      return `Product ${clip({ id: p.id, name: p.name, roast: p.type, price250g: p.price, price1kg: p.price1kg, cost250g: p.cost250 ?? null, cost1kg: p.cost1kg ?? null, supplier, inShop: p.visible, soldOut: Boolean(p.soldOut), labels: p.badges, notes: p.notes, region: p.region, process: p.process })}`;
    }
    case "tea": {
      const t = view.teas.find((x) => x.id === id);
      return t ? `Tea ${clip({ id: t.id, name: t.name, price: t.price, kind: t.type, notes: t.notes, inShop: t.visible !== false, soldOut: Boolean(t.soldOut) })}` : null;
    }
    case "customer": {
      const c = accounts.customer(id);
      if (!c) return null;
      const theirs = orders.list().filter((o) => o.userId === c.id || (c.email && o.contact?.email === c.email));
      const lead = leadFor({ userId: c.id, email: c.email, phone: c.phone });
      return `Customer ${clip({ name: c.name, email: c.email, phone: c.phone || null, since: c.createdAt, orders: theirs.length, spent: round2(theirs.reduce((n, o) => n + (o.total || 0) - (o.refunded || 0), 0)), lastOrder: theirs.map((o) => o.placedAt).sort().at(-1) || null, leadScore: lead ? `${lead.score} (${lead.level}): ${lead.reasons.join("; ")}` : null })}`;
    }
    case "account": {
      const a = trade.account(id);
      if (!a) return null;
      const theirs = orders.list().filter((o) => o.source === "wholesale" && o.wholesale?.accountId === a.id && o.status !== "cancelled");
      return `Wholesale account ${clip({ business: a.business, contact: a.contactName, email: a.email, phone: a.phone, terms: `Net ${a.terms}`, discount: `${trade.pricing(a).discount}%`, priceList: trade.pricing(a).priceListName || null, orders: theirs.length, unpaid: theirs.filter((o) => o.payment !== "paid").map((o) => `${o.number} ${money(o.total)}`), archived: Boolean(a.archivedAt) })}`;
    }
    case "supplier": {
      const s = trade.supplier(id);
      if (!s) return null;
      const pos = trade.purchaseOrders.filter((p) => p.supplierId === s.id);
      return `Supplier ${clip({ name: s.name, contact: s.contactName, email: s.email, phone: s.phone, notes: s.notes, purchaseOrders: pos.slice(0, 8).map((p) => `${p.number} ${p.status} ${money(p.total)}`) })}`;
    }
    case "po": {
      const po = trade.purchaseOrder(id);
      return po ? `Purchase order ${clip({ number: po.number, supplier: po.supplierName, status: po.status, total: po.total, items: po.items.map((i) => `${i.qty} ${i.unit} ${i.description} at ${money(i.unitCost)}, ${i.received} received`) })}` : null;
    }
    case "prospect": {
      const p = prospectStore.data.prospects.find((x) => x.id === id);
      return p ? `Wholesale prospect ${clip({ id: p.id, name: p.name, category: p.category, city: p.city || p.address, website: p.website, status: p.status, fit: p.research?.fit || null, contacts: (p.contacts?.people || []).map((x) => [x.name, x.title].filter(Boolean).join(", ")), notes: p.notes || "" })}` : null;
    }
    case "promo": {
      const c = promos.list().find((x) => x.id === id);
      return c ? `Discount code ${clip(c)}` : null;
    }
    case "menu": {
      const m = catalog.menuItem(id);
      return m ? `Café menu item ${clip({ name: m.name, price: m.price, section: m.sectionId, soldOut: Boolean(m.soldOut), hidden: Boolean(m.hidden) })}` : null;
    }
    default:
      return null;
  }
}

async function handleTeamAssistant(req, res, body) {
  if (!client) return sendJson(res, 503, { error: "The assistant isn't connected yet." });
  if (body.tooLarge) return sendJson(res, 413, { error: "Those files are too big together. Try fewer." });
  const messages = assistantMessages(body.messages);
  while (messages[0]?.role === "assistant") messages.shift();
  if (!messages.length || messages.at(-1).role !== "user") return sendJson(res, 400, { error: "Ask something." });
  const before = new Set(assistantStore.data.proposals.map((p) => p.id));
  const actions = teamActionsFor("admin");
  delete actions.approve; // the buttons approve here
  // What it looked at on the way, for the steps under the answer.
  const steps = [];
  const cards = [];
  const timings = [];
  const started = Date.now();
  // Streamed (Accept: application/x-ndjson): one JSON line per step looked at, per bit of
  // the answer as it's written, and the finished answer last. Otherwise one JSON reply.
  const live = /application\/x-ndjson/.test(String(req.headers.accept || ""));
  const line = (o) => res.write(`${JSON.stringify(o)}\n`);
  if (live) res.writeHead(200, { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store", "X-Accel-Buffering": "no" });
  try {
    const { reply } = await runAgent({
      client,
      // Quick, like Chat Us: Haiku answers, Opus takes over if it fails or declines. Low effort:
      // most questions are a lookup and a line or two.
      model: QUICK_MODEL,
      fallbackModel: MODEL,
      effort: "low",
      ...(live && { onText: (text) => line({ text }), onReset: () => line({ reset: true }) }),
      // Cached an hour (not the default five minutes): back office questions are often further
      // apart than that, and re-reading all of this is most of a short answer's wait.
      system: [{ type: "text", text: `${MERCHANT_PERSONA("admin")}\n\n# About Mimi Food\n\n${SYSTEM_PROMPT}`, cache_control: { type: "ephemeral", ttl: "1h" } }, { type: "text", text: [teamContext(), lookingAt(body.context)].filter(Boolean).join("\n\n") }],
      tools: MERCHANT_TOOLS.filter((t) => t.name !== "approve"),
      messages,
      execute: (name, input) => {
        if (!actions[name]) throw new Error("Unknown tool.");
        if (!steps.includes(name)) {
          steps.push(name);
          if (live) line({ step: name });
        }
        // The latest look at each thing becomes its card. Each lookup's time goes in the log.
        const t0 = Date.now();
        return Promise.resolve(actions[name](null, input)).finally(() => timings.push(`${name} ${Date.now() - t0}ms`)).then((result) => {
          const card = teamCard(name, result);
          if (card) cards.splice(0, cards.length, ...cards.filter((x) => x.tool !== name), { tool: name, ...card });
          return result;
        });
      },
    });
    const proposals = assistantStore.data.proposals.filter((p) => !before.has(p.id)).map(proposalView);
    const answer = { reply: reply || "Done.", proposals, steps, cards: cards.slice(-4), ms: Date.now() - started };
    console.log(`[assistant] answered in ${answer.ms} ms (${timings.join(", ") || "no lookups"})`);
    if (live) return res.end(`${JSON.stringify({ done: answer })}\n`);
    return sendJson(res, 200, answer);
  } catch (error) {
    // The whole reason in the log (status, type, request id); a plain one for the team.
    console.error(`[assistant] ${error.status || "-"} ${error.error?.error?.type || error.name || ""} ${error.requestID || error.request_id || ""}: ${error.message}`);
    const said = String(error.error?.error?.message || error.message || "");
    const msg =
      error.status === 401 || error.status === 403
        ? "The assistant isn't connected. Check its key in the server settings."
        : /credit balance|billing|spend limit/i.test(said)
          ? "The assistant is paused until its account is topped up."
          : error.status === 413 || /too large|too long|maximum.*tokens|prompt is too long/i.test(said)
            ? "That's too much for one question. Start a new chat, or attach fewer files."
            : error.status === 429 || error.status === 529 || /overloaded/i.test(said)
              ? "The assistant is busy right now. Try again in a minute."
              : "The assistant couldn't answer just now. Please try again.";
    if (live) return res.end(`${JSON.stringify({ error: msg })}\n`);
    return sendJson(res, 502, { error: msg });
  }
}
// The first sentence of a message, as a subject.
const firstLine = (s, n = 70) => {
  const line = String(s || "").trim().split(/\n/)[0].trim().replace(/^(.{12,}?[.?!])\s.*$/, "$1");
  return line.length > n ? `${line.slice(0, n - 1).trim()}…` : line;
};

// POST /api/contact (the contact page) and /api/handoff ("Talk to a person" in the FAQ assistant).
const CONTACT_TOPICS = ["General", "Order", "Wholesale", "Press", "Careers"];
async function handleContact(req, res, kind) {
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "contact", 5)) return sendJson(res, 429, { error: `Too many messages. Please try again later, or email us at ${DATA.SITE.email}.` });
  let body;
  try {
    body = await readJson(req, 40_000);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that message." });
  }
  const name = String(body?.name ?? "").trim().slice(0, 80);
  const email = String(body?.email ?? "").trim().toLowerCase().slice(0, 254);
  const text = String(body?.message ?? "").trim().slice(0, 5000);
  const transcript = kind === "handoff" ? cleanMessages({ messages: [...(Array.isArray(body?.messages) ? body.messages : []), { role: "user", content: "." }] })?.slice(0, -1) || [] : [];
  if (!name || !EMAIL_RE.test(email)) return sendJson(res, 400, { error: "Add your name and email." });
  if (!text && !transcript.length) return sendJson(res, 400, { error: "Please write a message." });
  try {
    if (rateLimited("all", "contact-site", 60)) throw new SpamError(`We're getting a lot of messages right now. Please email us at ${DATA.SITE.email}.`, { status: 429 });
    guardForm(req, kind, body, { names: [name], message: text });
    await checkEmailDomain(email);
  } catch (error) {
    if (!(error instanceof SpamError)) throw error;
    if (error.silent) return sendJson(res, 200, { ok: true });
    return sendJson(res, error.status, { error: error.message, code: error.code, wait: error.wait });
  }
  const topic = CONTACT_TOPICS.includes(body?.topic) ? body.topic : "General";
  const asked = [...transcript].reverse().find((m) => m.role === "user")?.content;
  const subject = kind === "handoff" ? firstLine(asked || text) : `${topic === "General" ? "" : `${topic}: `}${firstLine(text)}`;
  // A chat gets a key its window keeps, to show replies and carry on the conversation.
  const token = kind === "handoff" ? randomBytes(24).toString("base64url") : null;
  const c = await inbox.start({ name, email, subject, channel: kind === "handoff" ? "chat" : "email", source: kind === "handoff" ? "chat" : "form", box: "forms", text, transcript, chatHash: token && sha256hex(token) });
  console.log(`[inbox] new ${c.channel} from ${email}`);
  await notifyShop(topic === "Wholesale" ? DATA.SITE.wholesaleEmail : DATA.SITE.email, `New message from ${name}: ${subject}`, `${text || asked}\n\nFrom ${name} <${email}>\nReply in the back office: ${SITE_URL}/admin/inbox/${c.id}`);
  sendJson(res, 200, token ? { ok: true, chat: { id: c.id, token, ...chatPayload(c) } } : { ok: true });
}

