// A booked call: a to-do on its day for whoever takes calls, the café's confirmation, and a
// note to the shop. Cancelling takes the to-do away and tells the other side.
async function callBooked(b, acct) {
  const when = `${callLabel(b.day, b.time)} (Pacific)`;
  const t = await todos.add({ title: `Call with ${b.business}`, description: [`${when}, ${b.minutes} minutes.`, `${b.name ? `${b.name}, ` : ""}${b.email}${b.phone ? `, ${b.phone}` : ""}`, b.note && `They wrote: ${b.note}`].filter(Boolean).join("\n"), due: b.day, assignee: b.who, assigneeName: b.whoName, link: { kind: "account", id: acct.id, label: acct.business } }, "calls");
  await calls.linkTodo(b.id, t.id);
  // A video link when Google Meet or Zoom is connected (Google also sends the café an invite).
  const host = staff.person(b.who)?.email || "";
  const meeting = await meetings
    .create({ title: `${b.business} and ${DATA.SITE.name}`, details: [`${b.name ? `${b.name}, ` : ""}${b.email}${b.phone ? `, ${b.phone}` : ""}`, b.note && `About: ${b.note}`].filter(Boolean).join("\n"), day: b.day, time: b.time, minutes: b.minutes, guests: [b.email, host] })
    .catch((error) => (console.error("[calls] meeting:", error.message), null));
  if (meeting?.url) {
    b.meeting = meeting;
    await calls.setMeeting(b.id, meeting);
    await todos.update(t.id, { description: `${t.description}\nJoin: ${meeting.url}` }).catch(() => {});
  }
  // The confirmation's button puts the call in their calendar.
  const endMin = Number(b.time.slice(0, 2)) * 60 + Number(b.time.slice(3)) + b.minutes;
  const ends = `${String(Math.floor(endMin / 60)).padStart(2, "0")}:${String(endMin % 60).padStart(2, "0")}`;
  const addToCalendar = googleCalendarLink({ title: `Call with ${DATA.SITE.name}`, startsAt: `${b.day}T${b.time}`, endsAt: `${b.day}T${ends}`, summary: b.note ? `About: ${b.note}` : "", body: b.meeting?.url ? `Join: ${b.meeting.url}` : "", place: b.meeting?.url || "", address: "" }, { tz: "America/Los_Angeles", url: `${SITE_URL}/trade` });
  const join = b.meeting?.url ? `Join on ${PROVIDER_NAMES[b.meeting.provider]}: ${b.meeting.url}` : "";
  const intro = `You're booked for a call with ${DATA.SITE.name} on ${when}. ${join ? `${join}` : `We'll call you on ${b.phone}.`}${b.note ? `\n\nYou wrote: ${b.note}` : ""}\n\nTo cancel or pick another time, open Chats in your wholesale portal.`;
  await sendEmail({ kind: "wholesale", to: b.email, subject: `Your call with ${DATA.SITE.name}: ${callLabel(b.day, b.time)}`, text: `${intro}\n\nAdd it to your calendar: ${addToCalendar}\n\n${DATA.SITE.name}`, html: emailHtml(intro, "", b.meeting?.url ? { href: b.meeting.url, label: "Join Call" } : { href: addToCalendar, label: "Add to Calendar" }, { contact: DATA.SITE.wholesaleEmail }), replyTo: replyAddress(DATA.SITE.wholesaleEmail) }).catch((e) => console.error("[calls] email:", e.message));
  await notifyShop(DATA.SITE.wholesaleEmail, `Call booked: ${b.business}, ${when}`, `${b.business} booked a ${b.minutes}-minute call for ${when}.\n${b.name ? `${b.name}, ` : ""}${b.email}${b.phone ? `, ${b.phone}` : ""}${b.note ? `\n\nThey wrote: ${b.note}` : ""}${join ? `\n\n${join}` : ""}\n\nIt's in To-Dos: ${SITE_URL}/admin/todos`);
}
async function callCancelled(b, byCafe) {
  if (b.todoId) await todos.remove(b.todoId).catch(() => {});
  if (b.meeting) await meetings.cancel(b.meeting).catch((error) => console.error("[calls] meeting cancel:", error.message));
  const when = `${callLabel(b.day, b.time)} (Pacific)`;
  if (byCafe) await notifyShop(DATA.SITE.wholesaleEmail, `Call cancelled: ${b.business}, ${when}`, `${b.business} cancelled their call for ${when}.`);
  else {
    const intro = `We've had to cancel your call on ${when}. Book another time from Chats in your wholesale portal, or reply to this email.`;
    await sendEmail({ kind: "wholesale", to: b.email, subject: `Your call on ${callLabel(b.day, b.time)} is cancelled`, text: `${intro}\n\n${DATA.SITE.name}`, html: emailHtml(intro, "", { href: `${SITE_URL}/trade`, label: "Open Your Portal" }, { contact: DATA.SITE.wholesaleEmail }), replyTo: replyAddress(DATA.SITE.wholesaleEmail) }).catch((e) => console.error("[calls] email:", e.message));
  }
}
