// Puts the live catalogue everywhere the site data is used: the pricer, wholesale, the FAQ
// assistant and the js/data.js the browser loads. DATA.PRODUCTS is changed in place, so
// everything holding it sees the new list.
function syncCatalog() {
  const menu = catalog.shopMenu();
  // Counted stock: sold out at 0, and how many are left.
  const { products: list, accessories } = stock.apply(catalog.shopProducts(), [...catalog.labelAccessories(BASE_ACCESSORIES), ...catalog.shopFoods(), ...catalog.shopTeas()]);
  const teas = accessories.filter((a) => a.category === "Tea");
  DATA.PRODUCTS.splice(0, DATA.PRODUCTS.length, ...list);
  DATA.CAFE_MENU.splice(0, DATA.CAFE_MENU.length, ...menu);
  DATA.ACCESSORIES.splice(0, DATA.ACCESSORIES.length, ...accessories);
  SYSTEM_PROMPT = buildSystemPrompt(DATA);
  catalogRev = createHash("sha256").update(JSON.stringify([list, menu, accessories, DATA.SITE.cafesLive])).digest("hex").slice(0, 10);
  scheduleCatalogTranslation();
  if (typeof notifyBack === "function") setTimeout(() => notifyBack().catch((error) => console.error("[stock] notify:", error.message)), 0);
  // Prices may have moved: subscriptions follow (once the server has started; see listen below).
  if (started) {
    repriceSoon();
    merchantSoon();
  }
}
