// The calendar (events and classes). Paid class seats are counted from the orders (paid ones,
// not cancelled); free places from the calendar's own reservations.
const happenings = createHappenings({
  store: await storage.open("calendar", HAPPENING_PARTS),
  timeZone: DATA.SITE.timezone || "America/Los_Angeles",
  // `slot`: just the tickets for that time slot ("11:00").
  seatsSold: (id, slot) =>
    orders
      .list()
      .filter((o) => o.status !== "cancelled")
      .flatMap((o) => o.lines)
      .filter((l) => l.kind === "class" && l.product === id && (slot === undefined || l.slot === slot))
      .reduce((n, l) => n + l.qty, 0),
});
const money = (n) => `${DATA.SITE.currency}${Number(n).toFixed(2)}`;

const shipToLine = (t) => `${t.address}, ${t.city}${t.state ? `, ${t.state}` : ""} ${t.postcode}`;

// A line's options, as the customer reads them: a ticket's date and time ("Sat, Nov 21 · 12:00 PM
// to 1:00 PM · Roastery House"), otherwise its variant ("250g · Whole Bean").
const lineDetail = (l) => (l.kind === "class" ? ticketWhen(l) : l.variant || "");
// A line as the customer reads it (as the shop shows it): the bare product name, the roast with
// the options ("Espresso Roast · 250g · Whole Bean", so a roast never reads like a grind), and
// who a gift is for on its own.
const lineGift = (l) => String(l.recipient || l.sub?.recipient || String(l.title || "").match(/(?:, gift for| Gift Subscription for) (.+)$/)?.[1] || "");
const lineName = (l) => String(l.title || "").replace(/, gift for .*$/, "").replace(/ Gift Subscription for .*$/, " Gift Subscription").replace(/, (Espresso|Filter)(?=$|\s\()/, "");
const lineRoast = (l) => {
  const p = l.kind === "coffee" ? DATA.PRODUCTS.find((x) => x.id === l.product) : null;
  return p?.type ? `${p.type} Roast` : "";
};
const lineText = (l) => {
  const detail = [lineRoast(l), lineDetail(l)].filter(Boolean).join(" · ");
  return `${l.qty} × ${lineName(l)}${detail ? ` (${detail})` : ""}: ${money(l.price * l.qty)}${lineGift(l) ? `\n    Gift for ${lineGift(l)}` : ""}${l.note ? `\n    Gift message: "${l.note}"` : ""}`;
};
const courierDayText = (d) => (!d ? "" : d === new Date().toLocaleDateString("en-CA", { timeZone: DATA.SITE.timezone || "America/Los_Angeles" }) ? " today" : ` on ${new Date(`${d}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric", timeZone: "UTC" })}`);
const deliveryTo = (o) => `${o.fulfilment === "Local delivery" ? `Local delivery${courierDayText(o.courier?.day)} to` : "Shipping to"}: ${o.shipTo.name ? `${o.shipTo.name}, ` : ""}${shipToLine(o.shipTo)}`;

// A ticket's when and where. The class's own times when it has no slots; its date alone (from
// the line) if the class has gone from the calendar.
function ticketWhen(l) {
  const x = happenings.published(l.product);
  const parts = String(l.variant || "").split(" · ");
  const day = x?.startsAt?.slice(0, 10) || (/^\d{4}-\d{2}-\d{2}$/.test(parts[0]) ? parts[0] : "");
  if (!day) return l.variant || "";
  const date = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" });
  const clock = (hm) => new Date(`2000-01-01T${hm}:00Z`).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" });
  const days = x?.endsAt && x.endsAt.slice(0, 10) !== day ? `${date(day)} to ${date(x.endsAt.slice(0, 10))}` : date(day);
  const start = l.slot || (x?.startsAt?.length > 10 ? x.startsAt.slice(11, 16) : "");
  const end = l.slot ? l.slotEnd : x?.endsAt?.length > 10 && x.endsAt.slice(0, 10) === day ? x.endsAt.slice(11, 16) : "";
  const place = x ? x.place : parts.length > 1 && !/\d:\d\d/.test(parts.at(-1)) ? parts.at(-1) : "";
  return [days, start && `${clock(start)}${end ? ` to ${clock(end)}` : ""}`, place].filter(Boolean).join(" · ");
}
// "Add to Calendar" for a ticket: the file (Apple, Outlook) or Google Calendar, at its time slot.
const ticketCalendar = (l, google = false) => `${SITE_URL}/api/calendar/${l.product}${google ? "/google" : ".ics"}${l.slot ? `?slot=${encodeURIComponent(l.slot)}` : ""}`;

// The order in plain text. forCustomer: without their own name, email and phone (they know).
function orderText(o, { forCustomer = false } = {}) {
  const gifts = o.giftDeliveries || [];
  return [
    `Order ${o.number}${o.source === "renewal" ? " (subscription delivery)" : ""}${o.parent ? ` (gift delivery, paid with ${o.parent})` : ""}`,
    "",
    ...o.lines.map(lineText),
    ...o.lines.filter((l) => l.kind === "class").map((l) => `    Add it to your calendar: ${ticketCalendar(l)}`),
    ...gifts.flatMap((g) => ["", `Gift delivery${g.number ? ` ${g.number}` : ""} to ${g.shipTo.name}:`, ...g.lines.map(lineText), deliveryTo(g)]),
    "",
    ...orderTotals(o).map(([label, value, , paid = ""]) => `${label}: ${value}${paid}`),
    "",
    forCustomer ? null : `Name: ${o.contact.name}`,
    forCustomer ? null : `Email: ${o.contact.email}`,
    !forCustomer && o.contact.phone ? `Phone: ${o.contact.phone}` : null,
    ...orderWhere(o),
  ]
    .filter((x) => x !== null)
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}
// The money under an order's lines: [label, amount, bold?] (a gift delivery carries none).
function orderTotals(o) {
  if (o.parent) return [];
  return [
    ["Subtotal", money(o.subtotal)],
    // How it gets there, by name: by courier or by post. A pickup has no cost row (where to collect
    // it is under the totals).
    o.fulfilment && !(o.fulfilment === "Pickup" && !o.shipping) ? [o.fulfilment === "Pickup" ? "Pickup" : o.fulfilment === "Local delivery" ? "Local Delivery" : "Shipping", o.shipping ? money(o.shipping) : "Free"] : null,
    o.cafeFee ? ["Café delivery", money(o.cafeFee)] : null,
    o.tax ? ["Tax", money(o.tax)] : null,
    o.discount ? [discountName(o.discount), [o.discount.freeShipping && "Free shipping", o.discount.amount && `−${money(o.discount.amount)}`].filter(Boolean).join(", ")] : null,
    ["Total", money(o.total), true, o.payment === "paid" ? " (paid)" : ""],
    o.square?.giftPaymentId ? ["Paid", `${money(o.square.giftPaid)} by gift card ••${o.giftCard?.last4 || ""}${o.square.cardPaid > 0 ? ` and ${money(o.square.cardPaid)} by card` : ""}`] : null,
  ].filter(Boolean);
}
// A wholesale pickup's day and time (" on Tue, Nov 3 at 10 AM"), or "".
const pickupWhen = (o) => {
  const p = o.wholesale?.pickupAt;
  if (!p) return "";
  const [h, m] = p.time.split(":").map(Number);
  return ` on ${new Date(`${p.day}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" })} at ${h % 12 || 12}${m ? `:${String(m).padStart(2, "0")}` : ""} ${h >= 12 ? "PM" : "AM"}`;
};
// Where it's going (or where to collect it), and their notes.
const orderWhere = (o) => [
  o.shipTo ? deliveryTo(o) : o.fulfilment ? `Pickup: ${o.wholesale?.pickupAt?.placeName || "Roastery House"}${pickupWhen(o)}` : null,
  o.cafe ? (o.cafe.mode === "delivery" ? `Café delivery: ${o.cafe.when} from ${o.cafe.locationName} to ${o.cafe.address.street}, ${o.cafe.address.city} ${o.cafe.address.postcode}` : `Café pickup: ${o.cafe.when} at ${o.cafe.locationName}`) : null,
  o.notes ? `Notes: ${o.notes}` : null,
].filter(Boolean);

// Tells the customer we have their order and the shop that there's one to pack.
async function announceOrder(order) {
  const summary = orderText(order);
  const emailed = await emailConfirmation(order);
  await notifyShop(DATA.SITE.ordersEmail, `New order ${order.number}: ${money(order.total)}${order.payment === "paid" ? " paid" : ""}`, summary);
  return { summary, emailed };
}

// The customer's order confirmation email (also sent again from the back office's More actions).
// True when it went.
async function emailConfirmation(order) {
  let emailed = false;
  if (emailConfigured()) {
    const first = firstName(order.contact.name);
    const all = allLines(order);
    const when = order.cafe ? (order.cafe.asap ? order.cafe.when.replace(/^As soon as possible \(|\)$/g, "") : `on ${order.cafe.when}`) : "";
    const tickets = all.filter((l) => l.kind === "class");
    const onlyTickets = tickets.length > 0 && tickets.length === all.length;
    const onlyGiftCards = all.every((l) => l.kind === "giftcard");
    const next = order.cafe
      ? order.cafe.mode === "delivery"
        ? `A courier will bring it from ${order.cafe.locationName} ${when}.`
        : `It'll be ready at ${order.cafe.locationName} ${when}.`
      : onlyTickets
      ? "Your places are booked."
      : onlyGiftCards
      ? `We've emailed the gift card${all.reduce((n, l) => n + l.qty, 0) > 1 ? "s" : ""} to ${[...new Set(all.map((l) => l.giftcard.toName))].join(" and ")}.`
      : order.fulfilment === "Pickup"
      ? "We'll email you when it's ready to collect at Roastery House."
      : "We'll email you when it's on its way.";
    const intro = order.payment === "paid" ? `Hi ${first},\n\nThanks for your order. ${next}` : `Hi ${first},\n\nThanks for your order. We'll email you to confirm.`;
    // One button: Add to Calendar for a single booking, nothing for gift cards (they've gone to
    // their recipients), otherwise the tracking page. Each of several bookings has its own links.
    const oneBooking = onlyTickets && new Set(tickets.map((l) => `${l.product} ${l.slot || ""}`)).size === 1;
    const button = onlyGiftCards ? null : oneBooking ? { href: ticketCalendar(tickets[0]), label: "Add to Calendar" } : onlyTickets ? null : { href: await trackUrl(order), label: "Track Your Order" };
    // Our receipt, once it's paid (under the button).
    const receiptLink = order.payment === "paid" && !oneBooking ? { href: await receiptUrl(order), label: "View Receipt" } : null;
    const cta = `${button ? `${button.label}: ${button.href}${oneBooking ? `\nGoogle Calendar: ${ticketCalendar(tickets[0], true)}` : ""}\n` : ""}${receiptLink ? `Receipt: ${receiptLink.href}\n` : ""}${button || receiptLink ? "\n" : ""}`;
    try {
      await sendOrderEmail({
        to: order.contact.email,
        subject: `Your Mimi Food order ${order.number}`,
        text: `${intro}\n\n${cta}${orderText(order, { forCustomer: true })}\n\nQuestions? Reply to this email.\n\n${DATA.SITE.name}`,
        html: emailHtml(intro, "", button, { link: oneBooking ? { href: ticketCalendar(tickets[0], true), label: "Google Calendar" } : receiptLink, table: orderTable(order, { calendarLinks: !oneBooking }) }),
      });
      emailed = true;
    } catch (error) {
      console.error("[orders] confirmation email failed:", error.message);
    }
  }
  return emailed;
}

/* ── The emails' HTML (the shared look is server/emaillayout.js) ── */

const emailP = (html, { size = 16, color = EMAIL_INK, margin = "0 0 16px" } = {}) => `<p style="margin:${margin};font:400 ${size}px/1.55 ${EMAIL_FONT};color:${color}">${html}</p>`;
// Plain text as paragraphs. A web address after a label ("Directions: https://…") becomes that label
// as a link; any other address, a link showing just its site.
const emailLink = (href, label) => `<a href="${href}" style="color:${EMAIL_INK};text-decoration:underline">${label}</a>`;
const linkify = (html) =>
  html
    .replace(/([A-Z][A-Za-z ]{1,30}): (https?:\/\/[^\s<]+?)(?=[.,;)]?(\s|<|$))/g, (_, label, href) => emailLink(href, label))
    .replace(/(^|[\s(])(https?:\/\/[^\s<]+?)(?=[.,;)]?(\s|<|$))/g, (_, pre, href) => `${pre}${emailLink(href, href.replace(/^https?:\/\/(www\.)?/, "").split(/[/?#]/)[0])}`);
const emailParas = (text) => linkify(escapeHtml(text)).split(/\n{2,}/).map((p) => emailP(p.replace(/\n/g, "<br>"))).join("");
const mutedLink = (href, label) => `<a href="${escapeHtml(href)}" style="color:${EMAIL_MUTED};text-decoration:underline">${escapeHtml(label)}</a>`;
// The shop's address for the foot of every email: the mailing address set in the back office,
// or Roastery House's.
const footerAddress = () => {
  const roastery = DATA.LOCATIONS.find((l) => l.id === "roastery");
  return mailingAddress().replace(/\s*\n\s*/g, ", ") || [DATA.SITE.name, ...(roastery?.address || [])].join(", ");
};

// An order's lines as a table: quantity × item (its options muted under it) and the price on the
// right, then the totals, Total in bold, and where it's going. prices: false for just the items
// (the shipping email). calendarLinks: Add to Calendar under each ticket.
function orderTable(o, { prices = true, calendarLinks = false } = {}) {
  const td = (html, { right = false, bold = false, top = false, pad = "10px 0", muted = false } = {}) =>
    `<td${right ? ' align="right"' : ""} style="padding:${pad};${top ? `border-top:1px solid ${EMAIL_LINE};` : ""}vertical-align:top;font:${bold ? 600 : 400} ${bold ? 16 : 15}px/1.4 ${EMAIL_FONT};color:${muted ? EMAIL_MUTED : EMAIL_INK};${right ? "white-space:nowrap;padding-left:16px;" : ""}">${html}</td>`;
  const small = (html) => `<br><span style="font-size:13px;color:${EMAIL_MUTED}">${html}</span>`;
  const rows = (lines) =>
    lines.map((l) => {
      const detail = [lineRoast(l), lineDetail(l)].filter(Boolean).join(" · ");
      const under = [detail && escapeHtml(detail).replace(/ (AM|PM)\b/g, "&nbsp;$1"), lineGift(l) && `Gift for ${escapeHtml(lineGift(l))}`, l.note && `Gift message: “${escapeHtml(l.note)}”`, calendarLinks && l.kind === "class" && `${mutedLink(ticketCalendar(l), "Add to Calendar")} · ${mutedLink(ticketCalendar(l, true), "Google Calendar")}`].filter(Boolean);
      return `<tr>${td(`${l.qty} × ${escapeHtml(lineName(l))}${under.map(small).join("")}`, { top: true })}${prices ? td(money(l.price * l.qty), { right: true, top: true }) : ""}</tr>`;
    });
  const span = prices ? ' colspan="2"' : "";
  const gifts = (prices ? o.giftDeliveries || [] : []).flatMap((g) => [`<tr><td${span} style="padding:18px 0 4px;font:600 13px/1.4 ${EMAIL_FONT};color:${EMAIL_MUTED}">Gift to ${escapeHtml(g.shipTo.name)}${small(escapeHtml(shipToLine(g.shipTo)))}</td></tr>`, ...rows(g.lines)]);
  const totals = prices ? orderTotals(o).map(([label, value, bold], i) => `<tr>${td(escapeHtml(label), { bold, top: i === 0 || bold, pad: i === 0 ? "14px 0 4px" : bold ? "12px 0 4px" : "4px 0", muted: !bold })}${td(escapeHtml(value), { right: true, bold, top: i === 0 || bold, pad: i === 0 ? "14px 0 4px" : bold ? "12px 0 4px" : "4px 0" })}</tr>`) : [];
  const where = prices ? orderWhere(o) : [];
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 4px">
<tr><td${span} style="padding:0 0 8px;font:600 13px/1.4 ${EMAIL_FONT};color:${EMAIL_MUTED}">Order ${escapeHtml(o.number)}</td></tr>
${[...rows(o.lines), ...gifts, ...totals].join("\n")}
</table>${where.map((w) => emailP(escapeHtml(w), { size: 14, color: EMAIL_MUTED, margin: "12px 0 0" })).join("")}`;
}

// A code set on its own line, large and selected with one tap (sign-in codes, store credit,
// ambassador codes).
const emailCode = (code, { spaced = false } = {}) =>
  `<p style="margin:0 0 20px;font:600 ${spaced ? "32px/1.2" : "24px/1.3"} ${EMAIL_FONT};letter-spacing:${spaced ? "6px" : "1px"};color:${EMAIL_INK};-webkit-user-select:all;user-select:all">${escapeHtml(code)}</p>`;

// The HTML for a shop email, in the newsletters' look.
// intro: the message (plain text, blank lines between paragraphs). summary: plain text set under
// it (a purchase order). button: { href, label }, the one button. link: { href, label }, a plain
// link under it (e.g. "Google Calendar"). note: a gray line under that ("The link works for 7
// days."). block: HTML between the message and the button (a gift card, a code). after: plain
// text after the button. table: HTML under it all (orderTable). contact: false for no "Questions?
// Reply to this email." line in the footer (sign-in codes and links). marketing: { unsubscribeUrl, reason } for an email
// that needs an unsubscribe link. The preview line in the inbox is the message's first sentence.
const emailHtml = (intro, summary, button = null, { note = "", contact = DATA.SITE.ordersEmail, link = null, block = "", after = "", table = "", marketing = null } = {}) => {
  const preheader = String(intro).replace(/^(Hi|Hello)[^\n]*\n+/, "").split(/(?<=[.!?])\s/)[0].slice(0, 140);
  const body = [
    emailParas(intro),
    block,
    button ? emailButton(button.label, button.href) : "",
    link ? emailP(`<a href="${escapeHtml(link.href)}" style="color:${EMAIL_INK};text-decoration:underline">${escapeHtml(titleCase(link.label))}</a>`, { size: 15, margin: "-8px 0 20px" }) : "",
    note ? emailP(escapeHtml(note), { size: 14, color: EMAIL_MUTED }) : "",
    after ? emailParas(after) : "",
    table,
    summary ? `<pre style="margin:8px 0 16px;padding:16px 0;border-top:1px solid ${EMAIL_LINE};border-bottom:1px solid ${EMAIL_LINE};font:400 14px/1.55 ${EMAIL_FONT};color:${EMAIL_INK};white-space:pre-wrap">${escapeHtml(summary)}</pre>` : "",
  ].join("\n");
  const site = mutedLink(`${SITE_URL}/`, DATA.SITE.name);
  const footer = marketing
    ? [footLine(`You're getting this because ${escapeHtml(marketing.reason)}.`), footLine(`${mutedLink(marketing.unsubscribeUrl, "Unsubscribe")} · ${site}`), footLine(escapeHtml(footerAddress()), true)]
    : [contact ? `<p style="margin:0 0 10px;font:400 14px/1.5 ${EMAIL_FONT};color:${EMAIL_INK}">Questions? Reply to this email.</p>` : "", footLine(`${site} · ${escapeHtml(footerAddress().replace(new RegExp(`^${DATA.SITE.name.replace(/\W/g, "\\$&")}[^,]*,\\s*`), ""))}`, true)];
  return emailLayout({ siteUrl: SITE_URL, siteName: DATA.SITE.name, preheader, body, footer: footer.filter(Boolean).join("\n") });
};
// Order and account emails: replies go to the orders inbox.
const sendOrderEmail = (m) => sendEmail({ kind: "orders", replyTo: replyAddress(DATA.SITE.ordersEmail), ...m });

/* ── Checkout with Square ──────────────────────────────────────
   1. POST /api/orders prices the cart and saves the order as "pending_payment". A delivery
      address within SITE.localDelivery.radiusMiles of Roastery House becomes "Local delivery"
      (an Uber Direct courier, booked when the order is packed); anything further ships.
   2. The page draws Square's card form (Web Payments SDK) and sends its token to
      POST /api/orders/pay. One-off items (and delivery) become a Square order, paid at once, which
      lands in Square POS: a shipment, a Roastery House pickup, or a café order at that bar. A
      subscription saves the card to the customer in Square and starts a Square subscription,
      which bills the card itself. Café delivery books its courier as soon as it's paid. */

const CURRENCY = () => DATA.SITE.currencyCode;
const round2 = (n) => Math.round(n * 100) / 100;
const LOCAL = DATA.SITE.localDelivery;
const KM_TO_MILES = 0.621371;

// What's charged now: everything except the subscription, which Square bills itself.
const allLines = (order) => [...order.lines, ...(order.giftDeliveries || []).flatMap((g) => g.lines)];
// What the card pays today: what's due, less what a gift card covers.
const cardDue = (order) => round2(chargeNow(order) - (order.giftCard?.applied || 0));
// A gift card's balance by its number: { id, last4, balance } or { error, status }.
async function giftCardFor(typed) {
  const gan = cleanGan(typed);
  if (!/^\d{8,20}$/.test(gan)) return { error: "Check the card number." };
  let card;
  try {
    card = await sq.giftCardByGan(gan);
  } catch (error) {
    console.error("[gift cards] lookup:", error.message);
    return { error: "Couldn't check the card. Try again.", status: 502 };
  }
  const balance = sq.fromMoney(card?.balance_money);
  if (!card || card.state === "DEACTIVATED" || card.state === "BLOCKED") return { error: "Card not found. Check the number." };
  if (card.state === "PENDING") return { error: "This card isn't active yet." };
  if (!(balance > 0)) return { error: "This card has no balance." };
  return { id: card.id, last4: gan.slice(-4), balance };
}

// What the card was charged. An order edited down (back office → Edit Items) was refunded the
// difference (editedOff): it counts here, so "left to refund" stays what the order now holds.
const chargeNow = (order) => round2(chargeFor(order) + (order.editedOff || 0));
// What the order's contents cost now (one-off lines, delivery, tax, less its discount).
const chargeFor = (order) => round2(allLines(order).filter((l) => l.kind !== "sub").reduce((n, l) => n + l.price * l.qty, 0) + (order.shipping || 0) + (order.cafeFee || 0) + (order.tax || 0) - (order.discount?.amount || 0));
// Where a subscription's boxes go: a gift subscription sent to its recipient goes to their
// address (kept on the subscription, so renewals go there too), otherwise the order's.
const subShipTo = (order) => {
  const gift = (order.giftDeliveries || []).find((g) => g.lines.some((l) => l.kind === "sub"));
  return gift ? gift.shipTo : order.shipTo;
};
// Where a prepaid gift's monthly boxes go: the recipient's address, or the order's.
const prepaidShipTo = (order, line) => {
  const gift = (order.giftDeliveries || []).find((g) => g.lines.includes(line) || g.lines.some((l) => l.kind === "prepaid" && l.sub.recipient === line.sub.recipient));
  return gift ? gift.shipTo : order.shipTo;
};
// The phone a courier calls: the gift recipient's, else the customer's.
const dropoffPhone = (order) => order.shipTo?.phone || order.contact.phone;

// Miles from Roastery House to a delivery address, or null if the address can't be found.
async function localMiles(shipTo) {
  const from = shopCoords.get(LOCAL.from);
  if (!from || !shipTo) return null;
  const point = await geocoder.geocodeAddress({ street: shipTo.address, city: shipTo.city, state: shipTo.state, zip: shipTo.postcode });
  return point ? Math.round(distanceKm(point, from) * KM_TO_MILES * 10) / 10 : null;
}

// Local addresses go by Uber Direct courier, as checkout showed it.
// At checkout the customer can choose shipping instead ({ ship: true }).
async function routeDelivery(order, { ship = false } = {}) {
  if (ship || order.fulfilment !== "Delivery" || !order.shipTo || !couriers.configured().length) return order;
  const miles = await localMiles(order.shipTo);
  if (miles == null || miles > LOCAL.radiusMiles) return order;
  const pick = await courierChoice(order.shipTo, { name: order.shipTo.name || order.contact.name, phone: dropoffPhone(order) });
  // No price from the courier: it goes by post, at the postage price.
  if (pick?.fee == null) return order;
  return { ...order, fulfilment: "Local delivery", courier: { provider: pick?.provider || couriers.configured()[0] || "uber", status: "waiting", miles, from: LOCAL.from, quote: pick?.fee ?? null, day: DATA.courierDay().date } };
}

// What the customer pays for local delivery: the courier's quote, to the cent. Without a quote
// (the courier's service didn't answer) it's null, and delivery costs what shipping would.
const courierFee = (pick) => (pick?.fee != null ? Math.ceil(pick.fee * 100) / 100 : null);
// What the customer pays for local delivery: nothing when the parcel would ship free (`free`),
// else the courier's fee, capped at SITE.localDelivery.maxFee when set.
const courierCharge = (fee, free) => (free ? 0 : LOCAL.maxFee != null ? Math.min(fee, LOCAL.maxFee) : fee);

/* ── Courier jobs (server/couriers.js: Uber Direct) ── */

// "Los Angeles, CA 90020" → { city, state, zip }.
const cityLine = (line) => {
  const m = /^(.*?),\s*([A-Z]{2})\s+(\d{5})/.exec(String(line || ""));
  return m ? { city: m[1], state: m[2], zip: m[3] } : { city: String(line || ""), state: DATA.SITE.shipFrom.state || "CA", zip: "" };
};
const barOf = (id) => DATA.LOCATIONS.find((l) => l.id === id) || DATA.LOCATIONS[0];
const pickupFrom = (bar) => ({ name: `${DATA.SITE.name} ${bar.name}`, phone: bar.phone || DATA.SITE.shipFrom.phone, parts: { street: bar.address[0], ...cityLine(bar.address[1]) } });
const shipParts = (s) => ({ street: s.address, city: s.city, state: s.state || DATA.SITE.shipFrom.state || "CA", zip: s.postcode });

// The cheaper courier for an address, quoted at most every 10 minutes per address (checkout asks
// as the address is typed, and again when the order is placed).
const choiceCache = new Map();
async function courierChoice(shipTo, to: any = {}) {
  if (!couriers.configured().length) return null;
  const parts = shipParts(shipTo);
  const key = JSON.stringify(parts).toLowerCase();
  const hit = choiceCache.get(key);
  if (hit && hit.at > Date.now() - 10 * 60e3) return hit.pick;
  const from = pickupFrom(barOf(LOCAL.from));
  // A quote needs a phone to call; before the customer adds theirs, the shop's stands in.
  const job = { id: `quote-${randomBytes(4).toString("hex")}`, ref: "quote", from, to: { name: to.name || "Customer", phone: to.phone || from.phone, parts }, value: 30, items: [], note: "" };
  const pick = await couriers.choose(job).catch(() => null);
  if (pick) console.log(`[courier] quote ${parts.zip}: ${Object.entries<any>(pick.quotes || {}).map(([k, q]) => `${couriers.providerName(k)} ${q.fee != null ? `$${q.fee.toFixed(2)}` : q.error}`).join(", ") || couriers.providerName(pick.provider)}`);
  choiceCache.set(key, { at: Date.now(), pick });
  if (choiceCache.size > 500) choiceCache.delete(choiceCache.keys().next().value);
  return pick;
}

// As they type: is this email real (and a likely typo), and is this address real (and USPS's version)?
async function handleVerify(req, res, pathname) {
  if (rateLimited(clientIp(req), "verify", 40)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body;
  try {
    body = await readJson(req, 4000);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that." });
  }
  if (pathname === "/api/check-email") return sendJson(res, 200, await checkEmail(body?.email));
  return sendJson(res, 200, await checkAddress(body || {}));
}

async function handleOrder(req, res) {
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "orders", 10)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let priced;
  let wants: any = {}; // the delivery the customer chose, and the fee they were shown
  const user = accounts.userFromToken(cookie(req, SESSION_COOKIE));
  // Wholesale logins order at their wholesale prices, from /trade only.
  if (user && trade.accountForEmail(user.email)) return sendJson(res, 403, { error: "Wholesale login. Order from your wholesale page.", wholesale: true });
  try {
    const input = await readJson(req);
    const num = (v) => (v !== null && v !== "" && v !== undefined && Number.isFinite(Number(v)) ? Number(v) : null);
    wants = { express: input.express === true, ship: input.delivery === "ship", fee: num(input.courierFee), postage: num(input.postage), tax: num(input.tax), addressConfirmed: input.addressConfirmed === true, giftCard: cleanGan(input.giftCard).slice(0, 40) };
    priced = applyPromo(pricer.price(input), String(input.promo || "").slice(0, 40), user?.id);
  } catch (error) {
    if (error instanceof OrderError || error instanceof PromoError) return sendJson(res, 400, { error: error.message, promo: error instanceof PromoError });
    return sendJson(res, 400, { error: "Couldn't read that order." });
  }
  // Guests leave a phone (order updates, a carrier collecting a return). A wallet's contact may
  // not have one, so Apple Pay and Google Pay go through without it.
  if (!user && !wants.express && String(priced.contact.phone || "").replace(/\D/g, "").length < 10) return sendJson(res, 400, { error: "Add your phone number.", field: "phone" });
  // A signed-in customer's first phone at checkout is kept on their account (unconfirmed).
  if (user && !user.phone && e164(priced.contact.phone)) accounts.setPhone(user.id, e164(priced.contact.phone)).catch(() => {});
  const lacking = stockShort(allLines(priced));
  if (lacking) return sendJson(res, 400, { error: lacking, stock: true });
  // The email the receipt and updates go to has to receive mail.
  const mail = await checkEmail(priced.contact.email);
  if (!mail.ok) return sendJson(res, 400, { error: mail.error, field: "email", suggestion: mail.suggestion });
  // Where it ships has to be a real address (USPS), unless they've said theirs is right.
  if (!wants.addressConfirmed) {
    const places = [priced.shipTo && { to: priced.shipTo, who: "" }, ...(priced.giftDeliveries || []).map((g) => ({ to: g.shipTo, who: g.shipTo.name }))].filter(Boolean);
    for (const { to, who } of places) {
      const found = await checkAddress(to);
      if (found.status === "invalid" || found.status === "unit") {
        const where = who ? `${who}'s address` : "that address";
        return sendJson(res, 400, { error: found.status === "unit" ? `${where[0].toUpperCase()}${where.slice(1)} needs an apartment, suite or unit number.` : `We couldn't find ${where}. Please check it.`, field: "address", recipient: who || null, addressCheck: found });
      }
    }
  }
  // Café delivery: the address has to be inside the delivery area of the bar making it.
  if (priced.cafe?.mode === "delivery") {
    const shops = await deliveryDistances(priced.cafe.address);
    const from = shops?.find((s) => s.id === priced.cafe.location);
    if (from) {
      priced.cafe.distanceKm = from.distanceKm;
      if (!from.inRange) {
        return sendJson(res, 400, { error: `That address is outside our delivery area. Choose pickup or another bar.` });
      }
    }
  }
  priced = await routeDelivery(priced, { ship: wants.ship });
  // Local delivery costs the courier's fee, in place of this order's own shipping (gifts sent
  // elsewhere keep theirs). It has to be the fee checkout showed; if it's moved, say so.
  if (priced.fulfilment === "Local delivery" && priced.courier.quote != null) {
    const fee = courierFee({ fee: priced.courier.quote });
    // Free when this order would ship free (the flat shipping already worked that out).
    const own = round2(priced.shipping - priced.giftDeliveries.reduce((n, g) => n + (g.shipping || 0), 0));
    const charge = courierCharge(fee, own === 0);
    if (wants.fee != null && Math.abs(wants.fee - charge) >= 0.01) {
      return sendJson(res, 409, { error: `Delivery is now ${charge ? money(charge) : "free"}. Check your total and place the order again.`, courierFee: fee });
    }
    priced.courier.fee = fee; // what Uber charges the shop
    priced.courier.charged = charge; // what the customer pays
    priced.shipping = round2(priced.shipping - own + charge);
    priced.total = round2(priced.total - own + charge);
  }
  if (priced.fulfilment === "Local delivery" && dropoffPhone(priced).replace(/\D/g, "").length < 10) {
    return sendJson(res, 400, { error: `Add a phone number for delivery.` });
  }
  // Each gift sent to its recipient goes by courier or post, by its own address.
  priced.giftDeliveries = await Promise.all(priced.giftDeliveries.map((g) => routeDelivery({ ...g, contact: priced.contact })));
  // Parcels by post: the USPS price, as checkout showed it; if it's moved, say so.
  const moved = await pricePostage(priced, wants.postage);
  if (moved != null) return sendJson(res, 409, { error: `Shipping is now ${money(moved)}. Check your total and place the order again.`, postage: moved });
  for (const g of priced.giftDeliveries) {
    delete g.contact;
    if (g.fulfilment === "Local delivery" && (g.shipTo.phone || priced.contact.phone).replace(/\D/g, "").length < 10) {
      return sendJson(res, 400, { error: `Add a phone number for ${g.shipTo.name}'s delivery.` });
    }
  }

  // Sales tax, as checkout showed it; if it's moved, say so.
  const tax = await priceTax(priced);
  if (wants.tax != null && Math.abs(wants.tax - tax) >= 0.01) return sendJson(res, 409, { error: `Tax is now ${money(tax)}. Check your total and place the order again.`, tax });

  const subs = allLines(priced).filter((l) => l.kind === "sub");
  const prepaid = allLines(priced).filter((l) => l.kind === "prepaid");
  for (const line of prepaid) {
    if (!prepaidShipTo(priced, line)) return sendJson(res, 400, { error: `Add ${line.sub.recipient}'s address for their gift subscription.` });
  }

  const buyingGiftCards = allLines(priced).some((l) => l.kind === "giftcard");
  if (buyingGiftCards && !squareConfigured()) return sendJson(res, 400, { error: "Gift cards aren't on sale. Remove them from your cart." });
  // Paying with a gift card: what it covers now (its balance, up to what's due today).
  if (wants.giftCard) {
    if (buyingGiftCards) return sendJson(res, 400, { error: "Gift cards can't be bought with a gift card.", field: "giftCard" });
    const card = await giftCardFor(wants.giftCard);
    if (card.error) return sendJson(res, card.status || 400, { error: card.error, field: "giftCard" });
    priced.giftCard = { id: card.id, last4: card.last4, applied: round2(Math.min(card.balance, chargeNow(priced))) };
  }

  if (squareConfigured()) {
    if (subs.length > 1 || subs.some((l) => l.qty > 1)) return sendJson(res, 400, { error: "One subscription per checkout." });
    if (subs.length && !subShipTo(priced)) return sendJson(res, 400, { error: "Add a delivery address for your subscription." });
    // Only this browser can pay for the order it started.
    const payToken = randomBytes(18).toString("base64url");
    const order = await orders.add({ ...priced, userId: user?.id || null, source: "web", square: { payTokenHash: createHash("sha256").update(payToken).digest("hex") } }, { status: "pending_payment" });
    return sendJson(res, 201, {
      number: order.number,
      payToken,
      total: order.total,
      chargeNow: cardDue(order),
      giftCard: order.giftCard ? { last4: order.giftCard.last4, applied: order.giftCard.applied } : null,
      subscription: subs.length ? { label: subs[0].title, price: subs[0].price, variant: subs[0].variant } : null,
      square: sq.browserConfig(),
    });
  }

  // No card payments set up: take the order and arrange payment by email.
  let savedSubs = 0;
  const account = subs.length || prepaid.length ? await subscriberAccount({ ...priced, userId: user?.id || null }) : null;
  if (account) {
    for (const line of subs) {
      for (let i = 0; i < line.qty; i++) {
        try {
          await accounts.create(account.userId, line.sub, { shipTo: subShipTo(priced), phone: subShipTo(priced)?.phone || priced.contact.phone });
          savedSubs++;
        } catch (error) {
          console.error("[orders] couldn't save subscription:", error.message);
        }
      }
    }
  }
  let order = await orders.add({ ...priced, userId: account?.userId || user?.id || null, source: "web" });
  order = await addGiftOrders(order, { payment: "unpaid" });
  if (account) savedSubs += await savePrepaid(order, account);
  // (Its code counts as used once it's paid: marked paid in the back office.)
  console.log(`[orders] ${order.number} ${money(order.total)} <${order.contact.email}>`);
  const { summary, emailed } = await announceOrder(order);
  if (account) await emailAccountSetup(order, account);
  sendJson(res, 201, { number: order.number, total: order.total, track: await trackUrl(order), summary, emailed, savedSubs, account: accountReply(order, account), cafe: cafeReply(order) });
}

// Subscription plans in Square's catalog, created as needed (see server/square.js).
const squareIds = await storage.open("square", { ids: (x) => x.key });
const planCache = {
  get: (k) => squareIds.data.ids.find((x) => x.key === k)?.id,
  set: async (k, id) => {
    squareIds.data.ids.push({ key: k, id });
    await squareIds.save();
  },
};

// Going live (SQUARE_ENVIRONMENT from sandbox to production, or back): the Square ids saved here
// belong to the other Square, so they're dropped (plans and categories, wholesale customers and
// saved cards, the item library's ids) and the products and café menu are pushed to the new one.
// Orders keep their payment records; refunds for orders paid in the sandbox are done there.
async function squareMoved() {
  if (!squareConfigured()) return;
  const now = sq.environment();
  if (/^sandbox-/.test(process.env.SQUARE_APPLICATION_ID) !== (now === "sandbox")) console.warn(`[square] SQUARE_APPLICATION_ID is a ${now === "sandbox" ? "production" : "sandbox"} app ID but SQUARE_ENVIRONMENT is ${now}: card payments will fail until they match`);
  const was = setting("squareEnvironment")?.value || "sandbox"; // before this was kept, only the sandbox was used
  if (was === now) return;
  console.log(`[square] ${was} → ${now}: Square ids reset, pushing the catalog`);
  squareIds.data.ids = [];
  await squareIds.save();
  await catalog.forgetSquare();
  await trade.forgetSquare();
  await saveSetting("squareEnvironment", now);
  for (const p of catalog.adminView().products) await pushProduct(p.id);
  for (const sec of catalog.menuView().sections) for (const item of sec.items) await pushMenuItem(item.id);
}

// The account a subscription lives in: the signed-in customer's, the existing account for the
// checkout email, or a new one made from it (they log in with a code sent to that email).
async function subscriberAccount(order) {
  if (order.userId) return { userId: order.userId, signedIn: true };
  const { user, created } = await accounts.ensureUser({ name: order.contact.name, email: order.contact.email });
  return { userId: user.id, created, existing: !created };
}

// What the thank-you page shows for a café order: where, how and when.
const cafeReply = (order) =>
  order.cafe
    ? { mode: order.cafe.mode, location: order.cafe.location, locationName: order.cafe.locationName, when: order.cafe.when, window: order.cafe.window || "", asap: Boolean(order.cafe.asap), time: order.cafe.time, firstName: firstName(order.contact.name) }
    : null;

// What the thank-you page needs: which email to log in with (by a code sent to it).
const accountReply = (order, account) => (account && !account.signedIn ? { email: order.contact.email, existing: Boolean(account.existing) } : null);

async function emailAccountSetup(order, account) {
  if (account.signedIn || !emailConfigured()) return;
  const first = firstName(order.contact.name);
  const link = `${SITE_URL}/login`;
  const text = account.created
    ? `Hi ${first},\n\nYour subscription is set up, with an account for ${order.contact.email} so you can skip, pause or change it any time. Your order ${order.number} is in it too.\n\nLog in with a code sent to this email, no password needed:\n${link}`
    : `Hi ${first},\n\nYour subscription from order ${order.number} is in your account (${order.contact.email}). Log in with a code sent to this email to skip, pause or change it any time:\n${link}`;
  await sendOrderEmail({
    to: order.contact.email,
    subject: account.created ? `Your ${DATA.SITE.name} account is ready` : `Your ${DATA.SITE.name} subscription`,
    text: `${text}\n\n${DATA.SITE.name}`,
    html: emailHtml(text.split("\n\n").slice(0, -1).join("\n\n"), "", { href: link, label: "Log In" }),
  }).catch((error) => console.error("[accounts] setup email failed:", error.message));
}

// Gifts sent to their recipients: each address becomes its own order to pack and send (a
// label or a courier, like any other), linked to the order that paid for it. They carry no
// money of their own, so sales aren't counted twice.
async function addGiftOrders(order, { payment }) {
  const gifts = order.giftDeliveries || [];
  if (!gifts.length || gifts.every((g) => g.number)) return order;
  const numbered = [];
  for (const g of gifts) {
    if (g.number) {
      numbered.push(g);
      continue;
    }
    const child = await orders.add(
      { contact: order.contact, lines: g.lines, fulfilment: g.fulfilment, shipTo: g.shipTo, courier: g.courier, cafe: null, notes: order.notes, subtotal: 0, shipping: 0, cafeFee: 0, total: 0, userId: order.userId || null, source: "gift", parent: order.number },
      { status: "new", payment, by: "system" }
    );
    numbered.push({ ...g, number: child.number });
  }
  return orders.update(order.number, { giftDeliveries: numbered }, { by: "system" });
}

// Saves each prepaid gift in the buyer's account, so they can see how many boxes are left
// (and skip or pause one). Returns how many were saved.
async function savePrepaid(order, account) {
  let saved = 0;
  for (const line of allLines(order).filter((l) => l.kind === "prepaid")) {
    const shipTo = prepaidShipTo(order, line);
    try {
      await accounts.create(account.userId, line.sub, { prepaid: line.sub.prepaid, order: order.number, shipTo, phone: shipTo?.phone || order.contact.phone });
      saved++;
    } catch (error) {
      console.error(`[orders] ${order.number} couldn't save prepaid gift:`, error.message);
      await notifyShop(DATA.SITE.ordersEmail, `Prepaid gift not saved: ${order.number}`, `The gift subscription for ${line.sub.recipient} in order ${order.number} couldn't be saved. Its monthly deliveries won't be created by themselves; please add them by hand.`);
    }
  }
  return saved;
}

// Prepaid gifts: each delivery due today becomes an order to pack (paid, no charge), sent
// to the recipient like any other. Runs hourly; a delivery is counted before its order is
// made, so a restart can't send a box twice.
async function sendPrepaidDeliveries() {
  for (const { sub, user } of accounts.duePrepaid(shopToday())) {
    if (!user || !sub.shipTo) continue;
    try {
      const done = await accounts.prepaidSent(sub.id);
      if (!done) continue;
      const n = done.prepaid.sent;
      const line = { kind: "sub", title: `${sub.coffeeLabel} Gift Subscription for ${sub.recipient}`, variant: [sub.sizeLabel, sub.grind, `Delivery ${n} of ${done.prepaid.deliveries}`].filter(Boolean).join(" · "), note: "", gift: true, qty: 1, price: 0, sub: { coffee: sub.coffee, size: sub.size, freq: sub.freq, grind: sub.grind || "" } };
      const routed = await routeDelivery({ contact: { name: user.name, email: user.email, phone: sub.phone || "" }, lines: [line], fulfilment: "Delivery", shipTo: sub.shipTo, cafe: null, notes: "", subtotal: 0, shipping: 0, cafeFee: 0, total: 0, userId: user.id, source: "prepaid", parent: sub.prepaid.order || undefined });
      const order = await orders.add(routed, { status: "new", payment: "paid", by: "system" });
      console.log(`[orders] ${order.number} prepaid gift delivery ${n}/${done.prepaid.deliveries}`);
      autoLabel(order.number).catch((e) => console.error("[labels]", e.message));
      await notifyShop(DATA.SITE.ordersEmail, `Gift subscription delivery ${order.number}: ${sub.coffeeLabel}, ${sub.sizeLabel} (${n} of ${done.prepaid.deliveries})`, orderText(order));
    } catch (error) {
      console.error(`[orders] prepaid delivery for ${sub.id} failed:`, error.message);
    }
  }
}

async function handlePay(req, res) {
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (!squareConfigured()) return sendJson(res, 404, { error: "Card payments aren't available right now. Please try again later." });
  if (rateLimited(clientIp(req), "pay", 12)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body;
  try {
    body = await readJson(req);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that payment." });
  }
  const order = orders.get(String(body.number || ""));
  const tokenOk = order?.square?.payTokenHash && createHash("sha256").update(String(body.payToken || "")).digest("hex") === order.square.payTokenHash;
  if (!order || !tokenOk) return sendJson(res, 404, { error: "Order not found. Start checkout again." });
  if (order.status !== "pending_payment") return sendJson(res, 200, { number: order.number, paid: true, total: order.total, amounts: gaAmounts(order), track: await trackUrl(order), summary: orderText(order) });
  // An old checkout is placed again, so prices, codes, class seats and times are checked afresh.
  if (Date.parse(order.placedAt) < Date.now() - 30 * 60e3 && !order.square.lastOrderId && !order.square.paymentId) {
    return sendJson(res, 409, { error: "Checkout timed out. Tap Pay again.", expired: true });
  }
  // One payment at a time per order: a double tap or a second tab waits for the first.
  if (paying.has(order.number)) return sendJson(res, 409, { error: "Payment in progress. One moment." });
  paying.set(order.number, order);
  try {
    return await payOrder(req, res, order, body);
  } finally {
    paying.delete(order.number);
  }
}

// Orders being paid right now. What they buy is held (stock, class places, a code's uses) until
// they finish, so two people can't both pay for the last one.
const paying = new Map();
async function payOrder(req, res, order, body) {
  // Someone else may have bought the last ones since checkout began, or be paying for them now:
  // stop before charging. (No awaits until the charge, so the check and the hold go together.)
  const others = [...paying.values()].filter((o) => o.number !== order.number);
  const lacking = stockShort(allLines(order), stockUnits(others.flatMap(allLines)));
  if (lacking) return sendJson(res, 409, { error: lacking, stock: true });
  for (const l of allLines(order).filter((x) => x.kind === "class")) {
    const item = happenings.published(l.product);
    const held = others.flatMap(allLines).filter((x) => x.kind === "class" && x.product === l.product && x.slot === l.slot).reduce((n, x) => n + x.qty, 0);
    const left = item ? (l.slot ? happenings.slotLeft(item, l.slot) : happenings.left(item)) : 0;
    if (!item || (left !== null && left - held < l.qty)) return sendJson(res, 409, { error: `${l.title} has just filled up. Please remove it from your cart.`, expired: true });
  }
  const sameCode = order.discount?.code ? others.filter((o) => o.discount?.code === order.discount.code) : [];
  if (order.discount?.code && !promos.usable(order.discount.code, { today: shopToday(), holding: sameCode.length, amount: [order, ...sameCode].reduce((n, o) => n + (o.discount.amount || 0), 0) })) {
    return sendJson(res, 409, { error: `The code ${order.discount.code} is no longer valid. Please remove it and try again.`, expired: true });
  }
  const subLine = allLines(order).find((l) => l.kind === "sub");
  // A code or gift card that covers everything: no card is needed.
  const free = !subLine && cardDue(order) <= 0;
  const sourceId = String(body.sourceId || "");
  if (!sourceId && !free) return sendJson(res, 400, { error: "Enter your card details." });
  const verificationToken = body.verificationToken ? String(body.verificationToken) : undefined;
  const attempt = (order.square.attempts || 0) + 1;
  const currency = CURRENCY();
  const record = { ...order.square };
  // Apple Pay or Google Pay (what the wallet said), for the receipt.
  if (["Apple Pay", "Google Pay"].includes(body.wallet)) record.wallet = body.wallet;
  let account = null;

  try {
    const customerId = await sq.customerFor({ email: order.contact.email, name: order.contact.name });
    record.customerId = customerId;
    // A subscription needs the card on file; the one-off part is then paid with that card.
    let source = sourceId;
    if (subLine) {
      // A new card entered after a decline replaces the one saved before.
      if (!record.cardId || (sourceId && record.cardSource !== sourceId)) {
        record.cardId = await sq.saveCard({ sourceId, customerId, verificationToken, idempotencyKey: sq.key("card", order.number, attempt) });
        record.cardSource = sourceId;
      }
      source = record.cardId;
    }
    // A payment that timed out (or went through before a later step failed) isn't taken again.
    if (!record.paymentId && record.lastOrderId) {
      const done = await sq.completedPayment(record.lastOrderId).catch(() => null);
      if (done) Object.assign(record, { orderId: record.lastOrderId, paymentId: done.id, receiptUrl: done.receipt_url || null, card: sq.cardOf(done) });
    }
    const now = chargeNow(order);
    if (now > 0 && !record.paymentId) {
      // Gifts sent elsewhere are on the same Square order, each line noting where it goes.
      // Each line carries its sales tax rate (its destination's), for Square's tax on it.
      const oneOff = [
        ...order.lines.filter((l) => l.kind !== "sub").map((l) => ({ ...l, taxRate: order.taxRates?.[DATA.taxClass(l)] || 0 })),
        ...(order.giftDeliveries || []).flatMap((g) => g.lines.filter((l) => l.kind !== "sub").map((l) => ({ ...l, taxRate: g.taxRates?.[DATA.taxClass(l)] || 0, note: [l.note && `Gift message: ${l.note}`, `Send to ${g.shipTo.name}, ${shipToLine(g.shipTo)}`].filter(Boolean).join(" · ") }))),
      ];
      const bar = order.cafe && DATA.LOCATIONS.find((l) => l.id === order.cafe.location);
      const location = bar?.squareLocationId || sq.locationId();
      const pickupAt = order.cafe ? shopTimeToIso(order.cafe.time) : new Date(Date.now() + 2 * 3600e3).toISOString();
      const sqOrder = await sq.createOrder(order, { currency, customerId, lines: oneOff, suffix: attempt, pickupAt, location });
      // Square works the tax out itself; a cent of rounding either way is kept on our order too.
      const squareTotal = sq.fromMoney(sqOrder.total_money);
      // More than a few cents out means the order and the charge disagree: charge nothing.
      if (Math.abs(squareTotal - now) > 0.05) throw new Error(`Square's total ${squareTotal} doesn't match ours ${now}`);
      record.lastOrderId = sqOrder.id;
      if (Math.abs(squareTotal - now) >= 0.01) {
        console.warn(`[tax] ${order.number}: Square's total ${squareTotal} vs ours ${now}`);
        await orders.update(order.number, { tax: round2((order.tax || 0) + squareTotal - now), total: round2(order.total + squareTotal - now) }, { by: "square" });
      }
      const total = sq.fromMoney(sqOrder.total_money);
      const common = { location, orderId: sqOrder.id, currency, customerId, email: order.contact.email, reference: order.number };
      if (order.giftCard) {
        // The gift card first, for as much as its balance covers (held), then the card for the
        // rest (held), then both taken together. If the card fails, the gift card is let go.
        await sq.linkGiftCard(order.giftCard.id, customerId);
        const gift = await sq.pay({ ...common, sourceId: order.giftCard.id, amount: total, autocomplete: false, partial: true, idempotencyKey: sq.key("gpay", order.number, attempt) });
        const covered = sq.fromMoney(gift.amount_money);
        const rest = round2(total - covered);
        let card = null;
        try {
          if (rest > 0) {
            if (!source) throw new SquareError("Gift card balance changed", { code: "GIFT_CARD_SHORT" });
            card = await sq.pay({ ...common, sourceId: source, amount: rest, autocomplete: false, verificationToken: subLine ? undefined : verificationToken, idempotencyKey: sq.key("pay", order.number, attempt) });
          }
          await sq.payOrder({ orderId: sqOrder.id, paymentIds: [gift.id, card?.id].filter(Boolean), idempotencyKey: sq.key("payorder", order.number, attempt) });
          Object.assign(record, { orderId: sqOrder.id, paymentId: card?.id || gift.id, giftPaymentId: gift.id, giftPaid: covered, cardPaid: rest, card: card ? sq.cardOf(card) : null, receiptUrl: (card || gift).receipt_url || null });
        } catch (error) {
          await sq.cancelPayment(gift.id).catch((e) => console.error("[gift cards] couldn't release the hold:", e.message));
          if (card) await sq.cancelPayment(card.id).catch((e) => console.error("[square] couldn't release the card hold:", e.message));
          if (error.code === "GIFT_CARD_SHORT") error.covered = covered;
          throw error;
        }
      } else {
        const payment = await sq.pay({ ...common, sourceId: source, amount: total, verificationToken: subLine ? undefined : verificationToken, idempotencyKey: sq.key("pay", order.number, attempt) });
        if (payment.status !== "COMPLETED") throw new SquareError("Payment not completed", { code: "GENERIC_DECLINE" });
        Object.assign(record, { orderId: sqOrder.id, paymentId: payment.id, receiptUrl: payment.receipt_url || null, card: sq.cardOf(payment) });
      }
      // Charged: noted at once, so if a later step fails, paying again doesn't charge twice.
      await orders.update(order.number, { square: record }, { by: "system" }).catch((e) => console.error(`[square] ${order.number} couldn't note the payment:`, e.message));
    }
    if (subLine) {
      const S = DATA.SUBSCRIPTION;
      // (prepaid gifts are saved after payment, below)
      const coffee = DATA.subscriptionCoffee(subLine.sub.coffee);
      const size = S.sizes.find((x) => x.id === subLine.sub.size);
      const planVariationId = await sq.planVariation({ coffee, size, freq: subLine.sub.freq, price: subLine.price, currency, cache: planCache });
      const subscription = await sq.subscribe({ customerId, cardId: record.cardId, planVariationId, idempotencyKey: sq.key("sub", order.number) });
      record.subscriptionId = subscription.id;
      // No account needed to check out: the subscription makes one from the checkout email
      // (or joins the existing one), and the order moves into it.
      account = await subscriberAccount(order);
      {
        try {
          const shipTo = subShipTo(order);
          await accounts.create(account.userId, subLine.sub, { squareSubscriptionId: subscription.id, squareCustomerId: customerId, billedPrice: subLine.price, shipTo, phone: shipTo?.phone || order.contact.phone });
        } catch (error) {
          console.error("[square] couldn't save subscription:", error.message);
        }
      }
    }
  } catch (error) {
    record.attempts = attempt;
    await orders.update(order.number, { square: record }, { by: "system" });
    const decline = sq.declineMessage(error);
    console.error(`[square] ${order.number} payment failed:`, error.message);
    if (error.code === "GIFT_CARD_SHORT") return sendJson(res, 402, { error: `Your gift card covers ${money(error.covered)} now. Please add a card for the rest.`, giftCardShort: true });
    if (decline) return sendJson(res, 402, { error: decline });
    return sendJson(res, 502, { error: "Payment didn't go through. Try again; you won't be charged twice." });
  }

  delete record.payTokenHash;
  // Prepaid gift subscriptions: paid in full just now; the server sends the monthly boxes.
  if (allLines(order).some((l) => l.kind === "prepaid")) account ||= await subscriberAccount(order);
  // Only class seats: nothing to pack or send, so it's done once paid.
  const seatsOnly = allLines(order).every((l) => l.kind === "class" || l.kind === "giftcard");
  await orders.update(order.number, { status: seatsOnly ? "completed" : "new", payment: "paid", square: record, ...(account ? { userId: account.userId } : {}) }, { by: "square", note: record.giftPaymentId ? `Paid ${money(record.giftPaid)} by gift card ••${order.giftCard.last4}${record.cardPaid > 0 ? ` and ${money(record.cardPaid)} by card` : ""}` : free ? "Nothing to pay (code covered it)" : "Paid by card" });
  // Gift cards bought: issued in Square and emailed to the people they're for.
  if (allLines(order).some((l) => l.kind === "giftcard")) await issueGiftCards(orders.get(order.number));
  await addGiftOrders(orders.get(order.number), { payment: "paid" });
  if (account) await savePrepaid(orders.get(order.number), account);
  await countCode(order.number);
  // Café delivery: book the courier now, for the time the order will be ready.
  if (order.cafe?.mode === "delivery") await bookCourier(order.number);
  // Paid: take what it bought from the counted stock (put back if it's cancelled). Each gift
  // delivery holds its own, so cancelling one (or the order, once some have gone) puts back
  // only what didn't go out.
  let moved = false;
  for (const o of [orders.get(order.number), ...(orders.get(order.number).giftDeliveries || []).map((g) => g.number && orders.get(g.number)).filter(Boolean)]) {
    const taken = await stock.move(stockUnits(o.lines), -1, { reason: "Sold", ref: o.number });
    if (!taken.length) continue;
    await orders.update(o.number, { stockTaken: taken }, { by: "system" });
    moved = true;
  }
  if (moved) syncCatalog();
  const paid = orders.get(order.number);
  console.log(`[orders] ${paid.number} paid ${money(paid.total)}`);
  checkOrderEmail(paid.number).catch((error) => console.error("[orders] email check:", error.message));
  await announceOrder(paid);
  // Parcels that ship get their labels now, in the background.
  autoLabels(paid).catch((e) => console.error("[labels]", e.message));
  checkNexus().catch((e) => console.error("[tax]", e.message));
  if (account) await emailAccountSetup(paid, account);
  sendJson(res, 200, { number: paid.number, paid: true, total: paid.total, amounts: gaAmounts(paid), track: await trackUrl(paid), cafe: cafeReply(paid), summary: orderText(paid), subscription: Boolean(subLine) || allLines(paid).some((l) => l.kind === "prepaid"), account: accountReply(paid, account) });
}

// Each gift card in a paid order: issued in Square against its line of the Square order, kept
// here, and emailed to its recipient. Safe to run again (what's done is skipped).
async function issueGiftCards(order) {
  const oneOff = order.lines.filter((l) => l.kind !== "sub");
  const done = new Set(giftCards.forOrder(order.number).map((c) => c.uid));
  let failed = 0;
  for (const [i, line] of oneOff.entries()) {
    if (line.kind !== "giftcard") continue;
    for (let n = 0; n < line.qty; n++) {
      const uid = sq.giftCardUid(i, n);
      if (done.has(uid)) continue;
      try {
        const card = await sq.issueGiftCard({ orderId: order.square.orderId, lineItemUid: uid, idempotencyKey: `${order.number}-${i}-${n}` });
        await giftCards.add({ id: card.id, gan: card.gan, uid, amount: line.price, order: order.number, ...line.giftcard });
        await emailGiftCard(giftCards.get(card.id));
        await textGiftCard(giftCards.get(card.id));
      } catch (error) {
        failed++;
        console.error(`[gift cards] ${order.number} ${uid}:`, error.message);
      }
    }
  }
  if (failed) await notifyShop(DATA.SITE.ordersEmail, `Gift card not issued: ${order.number}`, `${failed} gift card${failed === 1 ? "" : "s"} in order ${order.number} couldn't be issued in Square. Open the order in the back office and press Issue gift cards to try again.`).catch(() => {});
}

// Back office: the gift cards sold (with their balances from Square), email one again, or issue
// the ones an order is still owed.
async function handleAdminGiftCards(req, res, pathname) {
  try {
    if (pathname === "/api/admin/gift-cards" && req.method === "GET") {
      const list = giftCards.list();
      // Balances, for the newest 50 (one Square call each).
      const balances = squareConfigured()
        ? await Promise.all(list.slice(0, 50).map((c) => sq.giftCardByGan(c.gan).then((x) => [c.id, x ? sq.fromMoney(x.balance_money) : null], () => [c.id, null])))
        : [];
      const bal = Object.fromEntries(balances);
      // Paid orders still owed cards (Square was down when they were bought).
      const owed = orders
        .list()
        .filter((o) => o.payment === "paid" && o.status !== "cancelled")
        .map((o) => ({ number: o.number, owed: allLines(o).filter((l) => l.kind === "giftcard").reduce((n, l) => n + l.qty, 0) - giftCards.forOrder(o.number).length }))
        .filter((x) => x.owed > 0);
      return sendJson(res, 200, { owed, cards: list.map((c) => ({ id: c.id, last4: String(c.gan).slice(-4), amount: c.amount, balance: bal[c.id] ?? null, order: c.order, toName: c.toName, toEmail: c.toEmail, toPhone: c.toPhone || "", fromName: c.fromName, createdAt: c.createdAt, emailedAt: c.emailedAt, textedAt: c.textedAt || null, acceptedAt: c.acceptedAt || null })) });
    }
    let m = /^\/api\/admin\/gift-cards\/([^/]+)\/email$/.exec(pathname);
    if (m && req.method === "POST") {
      const card = giftCards.get(decodeURIComponent(m[1]));
      if (!card) return sendJson(res, 404, { error: "Gift card not found." });
      if (!(await emailGiftCard(card))) return sendJson(res, 502, { error: "Email didn't send. Try again." });
      return sendJson(res, 200, { ok: true, emailedAt: giftCards.get(card.id).emailedAt });
    }
    m = /^\/api\/admin\/gift-cards\/issue\/(MF-[A-Z0-9]{1,12})$/.exec(pathname);
    if (m && req.method === "POST") {
      const order = orders.get(m[1]);
      if (!order || order.payment !== "paid") return sendJson(res, 404, { error: "That order isn't paid." });
      await issueGiftCards(order);
      const owed = allLines(order).filter((l) => l.kind === "giftcard").reduce((n, l) => n + l.qty, 0);
      const issued = giftCards.forOrder(order.number).length;
      return sendJson(res, issued >= owed ? 200 : 502, issued >= owed ? { issued } : { error: `${owed - issued} still couldn't be issued. Please try again shortly.` });
    }
    return sendJson(res, 404, { error: "Not found" });
  } catch (error) {
    console.error("[gift cards] admin:", error.message);
    return sendJson(res, 500, { error: "Something went wrong." });
  }
}

// A gift card's link, where its recipient accepts it.
const giftLink = async (card) => `${SITE_URL}/gift/${await giftCards.tokenOf(card.id)}`;

// The gift link's data. Before accepting: the amount, who it's from and the message. Accepting
// shows the number (and balance), and is noted for the back office.
async function handleGiftLink(req, res, token, accept) {
  if (rateLimited(clientIp(req), "gift-link", 30)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  const card = giftCards.byToken(token);
  if (!card) return sendJson(res, 404, { error: "This gift card link doesn't work." });
  if (accept) {
    if (req.method !== "POST") return send(res, 405, "Method not allowed", { Allow: "POST" });
    await giftCards.accepted(card.id);
  }
  const open = Boolean(giftCards.get(card.id).acceptedAt);
  const viewer = accounts.userFromToken(cookie(req, SESSION_COOKIE));
  const saved = Boolean(viewer && (card.userId === viewer.id || (!card.userId && viewer.verified && viewer.email === card.toEmail)));
  let balance = null;
  if (open && squareConfigured()) balance = await sq.giftCardByGan(card.gan).then((x) => (x ? sq.fromMoney(x.balance_money) : null), () => null);
  return sendJson(res, 200, { amount: card.amount, fromName: card.fromName, toName: card.toName, message: card.message || "", accepted: open, signedIn: Boolean(viewer), saved, takenByOther: Boolean(viewer && card.userId && card.userId !== viewer.id), ...(open && { number: formatGan(card.gan), code: card.gan, last4: String(card.gan).slice(-4), balance }) });
}

// An order as a card, 1200 × 630, for the preview a tracking link gets (in iMessage, say): its
// number, total, where it is on its steps and what's in it, as the order card in a chat shows it.
// A preview is drawn when the link is sent, so it says where the order was then; the page itself
// is always current.
async function serveOrderPicture(req, res, url) {
  const o = orders.get(String(url.searchParams.get("order") || "").toUpperCase());
  const t = String(url.searchParams.get("t") || "");
  if (!o || o.status === "pending_payment" || !o.trackToken || t !== o.trackToken) return notFound(res);
  try {
    const { default: sharp } = await import("sharp");
    const pickup = o.fulfilment === "Pickup" || Boolean(o.cafe);
    const steps = pickup ? ["Placed", "Being Made", "Ready", "Picked Up"] : ["Placed", "Packed", "Shipped", "Delivered"];
    const cancelled = o.status === "cancelled";
    const at = { new: 0, packed: 1, ready: 2, shipped: 2, completed: 3 }[o.status] ?? 0;
    const W = 1200, H = 630, cw = 1000, ch = 470, x = (W - cw) / 2, y = (H - ch) / 2, pad = 64;
    const blue = "#2f5bd3", ink = "#111", muted = "#6b6b6b", track = "#e4e4e7";
    const placed = new Date(o.placedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: DATA.SITE.timezone || "America/Los_Angeles" });
    const items = o.lines.map((l) => `${l.qty} × ${l.title}`).join(", ");
    const itemsLine = items.length > 40 ? `${items.slice(0, 39).replace(/[,\s]+\S*$/, "")}…` : items;
    const segW = (cw - pad * 2 - 3 * 12) / 4;
    const bars = steps
      .map((label, i) => {
        const sx = x + pad + i * (segW + 12);
        const on = !cancelled && i <= at;
        return `<rect x="${sx}" y="${y + 268}" width="${segW}" height="12" rx="6" fill="${on ? blue : track}"/><text x="${sx}" y="${y + 324}" font-size="28" fill="${!cancelled && i === at ? ink : muted}"${!cancelled && i === at ? ' font-weight="600"' : ""}>${escapeHtml(label)}</text>`;
      })
      .join("");
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><rect width="${W}" height="${H}" fill="#ececee"/>
      <rect x="${x}" y="${y}" width="${cw}" height="${ch}" rx="32" fill="#fff"/>
      <g font-family="Instrument Sans, Helvetica, Arial, sans-serif">
        <text x="${x + pad}" y="${y + 104}" font-size="60" font-weight="600" fill="${ink}">${escapeHtml(o.number)}</text>
        <text x="${x + cw - pad}" y="${y + 104}" font-size="60" text-anchor="end" fill="${ink}">${escapeHtml(money(o.total))}</text>
        <circle cx="${x + pad + 14}" cy="${y + 176}" r="12" fill="none" stroke="${cancelled ? muted : blue}" stroke-width="6"/>
        <text x="${x + pad + 44}" y="${y + 188}" font-size="36" fill="${muted}">${escapeHtml(`${ORDER_STATUS_SAID[o.status] || o.status} · ${placed}`)}</text>
        ${bars}
        <text x="${x + pad}" y="${y + 404}" font-size="30" fill="${muted}">${escapeHtml(itemsLine)}</text>
        <text x="${x + cw - pad}" y="${y + 404}" font-size="26" letter-spacing="5" text-anchor="end" fill="${ink}">${escapeHtml(DATA.SITE.name)}</text>
      </g></svg>`;
    const jpeg = await sharp(Buffer.from(svg)).jpeg({ quality: 88 }).toBuffer();
    res.writeHead(200, { "Content-Type": "image/jpeg", "Cache-Control": "private, max-age=300", "X-Robots-Tag": "noindex" });
    res.end(jpeg);
  } catch (error) {
    console.error("[track] picture:", error.message);
    notFound(res);
  }
}

// The gift card at an amount, 1200 × 630, for link previews. Drawn once per amount.
const cardPictures = new Map();
async function serveGiftCardPicture(res, amount) {
  if (!(amount > 0 && amount <= 10000)) return notFound(res);
  try {
    let jpeg = cardPictures.get(amount);
    if (!jpeg) {
      const { default: sharp } = await import("sharp");
      const W = 1200, H = 630, cw = 760, ch = Math.round(cw / 1.586), x = (W - cw) / 2, y = (H - ch) / 2, r = 38;
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><rect width="${W}" height="${H}" fill="#e6e6e6"/>
        <rect x="${x}" y="${y + 14}" width="${cw}" height="${ch}" rx="${r}" fill="#000" opacity="0.18"/>
        <rect x="${x}" y="${y}" width="${cw}" height="${ch}" rx="${r}" fill="#111"/>
        <g transform="translate(${x + 54} ${y + 50}) scale(1.1)" fill="none"><ellipse cx="23" cy="33" rx="21.5" ry="31.5" stroke="#fff" stroke-width="3"/><path fill-rule="evenodd" d="M10 41V13h5.6L23 28.2 30.4 13H36v28h-5.3V22.6L23 37.6 15.3 22.6V41z" fill="#fff"/></g>
        <g font-family="Instrument Sans, Helvetica, Arial, sans-serif" fill="#fff">
          <text x="${x + cw - 54}" y="${y + 84}" font-size="32" text-anchor="end" opacity="0.75">Gift Card</text>
          <text x="${x + 54}" y="${y + ch - 54}" font-size="120" font-weight="500">${escapeHtml(money(amount).replace(/\.00$/, ""))}</text>
          <text x="${x + cw - 54}" y="${y + ch - 62}" font-size="32" letter-spacing="6" text-anchor="end">${escapeHtml(DATA.SITE.name)}</text>
        </g></svg>`;
      jpeg = await sharp(Buffer.from(svg)).jpeg({ quality: 88 }).toBuffer();
      cardPictures.set(amount, jpeg);
    }
    res.writeHead(200, { "Content-Type": "image/jpeg", "Cache-Control": "public, max-age=86400" });
    res.end(jpeg);
  } catch (error) {
    console.error("[gift cards] picture:", error.message);
    send(res, 500, "Couldn't draw the card.");
  }
}

// The gift card by iMessage too, when their number already has a conversation with us (we don't
// start new ones). With confetti, and noted in that conversation in the Inbox.
async function textGiftCard(card) {
  if (!card?.toPhone || !imessageConfigured()) return false;
  const c = inbox.byPhone(card.toPhone);
  if (!c) return false;
  // Just the link: iMessage shows it as a card (who it's from, the card), tapped to accept.
  const text = await giftLink(card);
  try {
    // Confetti if iMessage takes an effect on a link; the plain link if not.
    let effect = "confetti";
    const sent = await sendText(c, text, { effect }).catch(() => ((effect = undefined), sendText(c, text)));
    await inbox.say(c, text, { ...(effect && { effect }), textId: sent?.id });
    await giftCards.texted(card.id);
    return true;
  } catch (error) {
    console.error("[gift cards] text:", error.message);
    return false;
  }
}

// The gift card email: who it's from, the amount (drawn as the card), their message, and how to
// use it. The number shows on the gift page once they accept it.
async function emailGiftCard(card) {
  if (!emailConfigured() || !card) return false;
  const link = await giftLink(card);
  const amount = money(card.amount).replace(/\.00$/, "");
  const intro = `Hi ${firstName(card.toName)},\n\n${card.fromName} sent you a ${amount} ${DATA.SITE.name} gift card.`;
  const how = `Accept it to see the card number. Use it at checkout on ${SITE_URL.replace(/^https?:\/\//, "")} or at Roastery House. It never expires.`;
  const white = (size, weight, extra = "") => `font:${weight} ${size}px/1.2 ${EMAIL_FONT};color:#ffffff;${extra}`;
  const block = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#111111" style="max-width:400px;margin:4px 0 20px;background:#111111;border-radius:18px"><tr>
<td style="padding:22px 24px 0;${white(14, 600, "letter-spacing:.12em")}">${escapeHtml(DATA.SITE.name)}</td><td align="right" style="padding:22px 24px 0;${white(14, 400)}">Gift Card</td></tr>
<tr><td colspan="2" style="padding:56px 24px 22px;${white(44, 500, "line-height:1")}">${escapeHtml(amount)}</td></tr></table>
${card.message ? `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 20px"><tr><td style="padding:2px 0 2px 16px;border-left:3px solid ${EMAIL_LINE};font:400 16px/1.55 ${EMAIL_FONT};color:${EMAIL_INK}">“${escapeHtml(card.message).replace(/\n/g, "<br>")}”<br><span style="font-size:14px;color:${EMAIL_MUTED}">${escapeHtml(card.fromName)}</span></td></tr></table>` : ""}`;
  const text = `${intro}${card.message ? `\n\n“${card.message}”\n${card.fromName}` : ""}`;
  try {
    await sendEmail({ kind: "orders", secret: "Gift card", to: card.toEmail, replyTo: replyAddress(DATA.SITE.ordersEmail), subject: `${card.fromName} sent you a ${amount} ${DATA.SITE.name} gift card`, text: `${text}\n\nAccept Gift Card: ${link}\n\n${how}\n\nQuestions? Reply to this email.\n\n${DATA.SITE.name}`, html: emailHtml(intro, "", { href: link, label: "Accept Gift Card" }, { block, after: how }) });
    await giftCards.emailed(card.id);
    return true;
  } catch (error) {
    console.error("[gift cards] email:", error.message);
    return false;
  }
}

// Refunds part or all of what the card paid, keeps it on the order and (unless told not to)
// emails the customer. Throws if Square refuses.
// One refund at a time per order: a double-click, or two staff at once, can't refund it twice.
const refunding = new Set();
const tradePaying = new Set();
async function refundCard(order, amount, reason = "", opts: any = {}) {
  amount = round2(Number(amount) || 0);
  if (amount <= 0) throw new OrderError("There's nothing left to refund on this order.");
  if (refunding.has(order.number)) throw new OrderError("A refund for this order is already going through.");
  refunding.add(order.number);
  try {
    return await refundCardNow(order, amount, reason, opts);
  } finally {
    refunding.delete(order.number);
  }
}
async function refundCardNow(order, amount, reason = "", { by = "shop", cancel = false, notify = true, shown = reason } = {}) {
  // Paid partly by gift card: the card's part is refunded first, then the rest to the gift card.
  const s0 = order.square;
  const cardLeft = s0.giftPaymentId ? round2((s0.cardPaid || 0) - (s0.cardRefunded || 0)) : amount;
  const fromCard = round2(Math.min(amount, Math.max(0, cardLeft)));
  const fromGift = round2(amount - fromCard);
  const refundsMade = {};
  // Square's idempotency: the same refund (this order, how many before it, this amount, within
  // ten minutes) is one, so a retry after a dropped connection doesn't refund twice.
  const stamp = `${Object.keys(s0.refunds || {}).length}-${Math.round(amount * 100)}-${Math.floor(Date.now() / 600e3).toString(36)}`;
  let r = null;
  if (fromCard > 0) {
    r = await sq.refund({ paymentId: s0.paymentId, amount: fromCard, currency: CURRENCY(), reason: reason || `Refund for order ${order.number}`, idempotencyKey: sq.key("refund", order.number, stamp) });
    refundsMade[r.id] = fromCard;
  }
  if (fromGift > 0) {
    r = await sq.refund({ paymentId: s0.giftPaymentId, amount: fromGift, currency: CURRENCY(), reason: reason || `Refund for order ${order.number}`, idempotencyKey: sq.key("grefund", order.number, stamp) });
    refundsMade[r.id] = fromGift;
  }
  const fresh = orders.get(order.number);
  await orders.update(order.number, { square: { ...fresh.square, cardRefunded: round2((fresh.square.cardRefunded || 0) + (s0.giftPaymentId ? fromCard : 0)), refunds: { ...(fresh.square.refunds || {}), ...refundsMade } } }, { by: "system" });
  // Only what Square's webhook hasn't counted already (it may land while this was going through).
  const counted = fresh.square.refunds || {};
  const refunded = round2((fresh.refunded || 0) + Object.entries(refundsMade).reduce((n, [id, v]: [string, any]) => n + (counted[id] === undefined ? v : 0), 0));
  const changes: any = { refunded, payment: refunded >= chargeNow(fresh) - 0.005 ? "refunded" : "partially_refunded" };
  if (cancel) changes.status = "cancelled";
  await orders.update(order.number, changes, { by, note: `Refunded ${money(amount)}${reason ? `: ${reason}` : ""}` });
  let emailed = false;
  if (emailConfigured() && notify) {
    const first = firstName(order.contact.name);
    const why = String(shown || "").trim().replace(/([^.!?])$/, "$1.");
    const where = fromGift > 0 ? (fromCard > 0 ? ` ${money(fromGift)} goes back on your gift card now, and ${money(fromCard)} should appear on your statement within 5–10 business days.` : " It goes back on your gift card.") : " It should appear on your statement within 5–10 business days.";
    const text = `Hi ${first},\n\nWe've refunded ${money(amount)} for order ${order.number}${cancel ? ", which has been cancelled" : ""}.${why ? ` ${why}` : ""}${where}`;
    try {
      await sendOrderEmail({ to: order.contact.email, subject: `Refund for your Mimi Food order ${order.number}`, text: `${text}\n\nQuestions? Reply to this email.\n\nMimi Food`, html: emailHtml(text, "") });
      emailed = true;
    } catch (error) {
      console.error("[refund] email failed:", error.message);
    }
  }
  return { id: r.id, emailed };
}

/* ── Couriers (Uber Direct) ─────────────── */

// "2026-10-14T09:30" in the shop's time zone → an ISO instant.
function shopTimeToIso(local) {
  const guess = new Date(`${local}:00Z`);
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", { timeZone: DATA.SITE.timezone || "America/Los_Angeles", hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })
      .formatToParts(guess)
      .map((p) => [p.type, p.value])
  );
  const offsetAt = (d) => {
    const p = Object.fromEntries(
      new Intl.DateTimeFormat("en-US", { timeZone: DATA.SITE.timezone || "America/Los_Angeles", hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })
        .formatToParts(d)
        .map((x) => [x.type, x.value])
    );
    return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute) - d.getTime();
  };
  const shown = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute);
  const first = new Date(guess.getTime() - (shown - guess.getTime()));
  // Again with the offset in force at that moment, so days the clocks change come out right.
  return new Date(guess.getTime() - offsetAt(first)).toISOString();
}

// Books an Uber Direct courier for a café delivery (at its scheduled time) or a local delivery of
// coffee (now, once packed). Failures are kept on the order and sent to the shop to sort out.
// When the courier collects: a café order at its time; a bag delivery ordered after the cutoff at
// the morning pickup on its day (booked the evening before, the courier comes at 7 AM).
// When the courier collects: a café delivery at its time; a local delivery now while Roastery House
// still takes same-day orders, otherwise the next morning pickup (judged when it's booked, so a
// bag packed after closing waits for the morning rather than going to a closed shop).
function courierPickup(cafe, order) {
  const later = (iso) => (iso && Date.parse(iso) > Date.now() + 15 * 60e3 ? iso : undefined);
  if (cafe) return later(shopTimeToIso(cafe.time));
  const d = DATA.courierDay();
  const day = d.today ? (order.courier?.day > d.date ? order.courier.day : null) : d.date;
  return day ? later(shopTimeToIso(`${day}T${DATA.SITE.localDelivery?.morningPickup || "07:00"}`)) : undefined;
}

/* ── Order edits (back office → an order → Edit Items) ──
   An order still to pack, with no label or courier yet, can have its coffee and tea lines
   changed: quantities, lines taken off, lines added (at today's price; the rest keep what was
   paid). Delivery stays as charged; tax is worked out again. Less to pay: the difference is
   refunded to the card. More: the customer is emailed a Square invoice for the difference.
   Wholesale orders (unpaid) are priced again at the account's prices and re-invoiced, as the
   text assistant's change_order does. Stock taken is put back and taken again. */
const EDITABLE = (l) => l.kind === "coffee" || l.kind === "accessory";
// Why an order can't be edited, or "".
function editBlock(o) {
  if (!o) return "Order not found.";
  if (o.status !== "new") return o.status === "cancelled" ? "It's cancelled." : "It's already packed. Unpack it first.";
  if (o.parent) return "Edit the order it's part of.";
  if (o.label && !o.label.voided) return "It has a shipping label. Void it first.";
  if (o.courier?.deliveryId) return "A courier is booked for it.";
  if (o.editDue && !o.editDue.paid && !o.editDue.cancelled) return "The last change is waiting on payment.";
  if (o.source === "wholesale") return o.payment !== "unpaid" || o.wholesale?.processing ? "It's paid or being paid." : "";
  if (o.source !== "web") return "Only shop and wholesale orders can be edited.";
  if (!["paid", "partially_refunded"].includes(o.payment)) return "It isn't paid.";
  if (!o.lines.some(EDITABLE)) return "Nothing on it can be edited here.";
  return "";
}
// The edited order (not saved): `qty` is one quantity per current line (lines that can't be
// edited keep theirs), `add` new lines as checkout sends them ({ kind, product, size, grind,
// variant, qty }).
async function editedOrder(o, { qty = [], add = [] }) {
  const why = editBlock(o);
  if (why) throw new OrderError(`This order can't be edited: ${why}`);
  const keyOf = (l) => `${l.kind}:${l.product}:${l.size || ""}:${l.variant || ""}:${l.grind || ""}`;
  const bad = [...(Array.isArray(qty) ? qty : []), ...(Array.isArray(add) ? add.map((x) => x?.qty) : [])].some((n) => n !== undefined && !(Number.isInteger(Number(n)) && Number(n) >= 0 && Number(n) <= 500));
  if (bad) throw new OrderError("Quantities go from 0 to 500.");
  let lines = o.lines.map((l, i) => (EDITABLE(l) && qty[i] !== undefined ? { ...l, qty: Number(qty[i]) } : l)).filter((l) => l.qty > 0);
  const extra = (Array.isArray(add) ? add : []).filter((x) => x && Number(x.qty) > 0);
  if (o.source === "wholesale") {
    const acct = trade.account(o.wholesale.accountId);
    if (!acct) throw new OrderError("The account for this order no longer exists.");
    const raw = [...lines.map((l) => ({ product: l.product, size: l.size, qty: l.qty })), ...extra.map((x) => ({ product: x.product, size: x.size, qty: x.qty }))];
    if (!raw.length) throw new OrderError("Leave at least one item, or cancel the order.");
    const { local } = o.fulfilment === "Pickup" ? { local: true } : await tradeLocal(acct, o.shipTo ? { street: o.shipTo.address, city: o.shipTo.city, state: o.shipTo.state, postcode: o.shipTo.postcode } : acct.address);
    const q = priceWholesale(acct, { lines: raw, fulfilment: o.fulfilment, notes: o.notes, poRef: o.wholesale?.poRef, shipping: o.shipping }, { local, credits: creditsLeft(acct, o.number), quoting: true });
    return { ...o, lines: q.lines, subtotal: q.subtotal, shipping: q.shipping, total: q.total, discount: q.discount || null, wholesale: { ...o.wholesale, credits: q.wholesale.credits || [], tier: q.wholesale.tier || null } };
  }
  if (extra.length) {
    const priced = pricer.price({ name: o.contact.name, email: o.contact.email, lines: extra.map((x) => ({ ...x, kind: x.kind === "accessory" ? "accessory" : "coffee" })), fulfilment: "Pickup" });
    for (const l of priced.lines) {
      if (!EDITABLE(l)) throw new OrderError("Only coffee and accessories can be added here.");
      const same = lines.find((x) => EDITABLE(x) && keyOf(x) === keyOf(l));
      if (same) same.qty += l.qty;
      else lines.push(l);
    }
  }
  if (!lines.length) throw new OrderError("Leave at least one item, or cancel the order.");
  const lacking = stockShort(lines, o.stockTaken || []);
  if (lacking) throw new OrderError(lacking.replace(/ Please (remove it from|change the quantity in) your cart\./, ""));
  // The order as it stands must price out to what it is (else it was changed some other way).
  const gifts = (o.giftDeliveries || []).flatMap((g) => g.lines);
  const goods = (ls) => round2([...ls, ...gifts].reduce((n, l) => n + l.price * l.qty, 0));
  if (Math.abs(round2(goods(o.lines) - (o.subtotal || 0))) >= 0.01) throw new OrderError("This order's total has been changed another way, so it can't be edited here. Change it in Square.");
  const discount = o.discount?.amount ? { ...o.discount, amount: round2(Math.min(o.discount.amount, goods(lines))) } : o.discount || null;
  // Tax: what was charged, moved by the tax on what changed (today's rates for both, so a rate
  // that changed since doesn't touch the lines that stay).
  const taxOf = async (ls, d) => {
    const t: any = { ...o, lines: ls, giftDeliveries: o.giftDeliveries || [], discount: d, total: 0 };
    return priceTax(t);
  };
  const tax = round2(Math.max(0, (o.tax || 0) + (await taxOf(lines, discount)) - (await taxOf(o.lines, o.discount || null))));
  const next: any = { ...o, lines, subtotal: goods(lines), discount, tax };
  next.total = round2(next.subtotal + (o.shipping || 0) + (o.cafeFee || 0) + tax - (discount?.amount || 0));
  return next;
}
// What can be added to an order in Edit Items, as the lines checkout would send: shop coffees
// (each size and grind) and accessories (each color and size); wholesale, the portal's sizes.
function editAddable(o) {
  if (o.source === "wholesale") {
    return [
      ...DATA.PRODUCTS.filter((p) => !p.soldOut).flatMap((p) => ["5lb", "250g"].map((size) => ({ label: `${p.name} · ${size === "5lb" ? "5 lb" : "250g retail bag"}`, line: { product: p.id, size } }))),
      ...DATA.ACCESSORIES.filter((a) => a.category === "Tea" && a.price != null && !a.soldOut).flatMap((t) => ["tin", "1kg"].map((size) => ({ label: `${t.name} · ${size === "1kg" ? "1 kg loose" : "pack"}`, line: { product: t.id, size } }))),
    ];
  }
  return [
    ...DATA.PRODUCTS.filter((p) => !p.soldOut).flatMap((p) => ["250g", "1kg"].flatMap((size) => DATA.grindsFor(p).map((grind) => ({ label: `${p.name} · ${size} · ${grind}`, line: { kind: "coffee", product: p.id, size, grind } })))),
    ...DATA.ACCESSORIES.filter((a) => a.price != null && !a.soldOut).flatMap((a) => {
      const colors = a.colors?.length ? a.colors.map((c) => c.name) : [""];
      const sizes = a.sizes?.length ? a.sizes : [""];
      return colors.flatMap((color) => sizes.map((size) => ({ label: [a.name, color, size && `Size ${size}`].filter(Boolean).join(" · "), line: { kind: "accessory", product: a.id, ...(size && { size }), ...(color && { color }) } })));
    }),
  ].slice(0, 400);
}
// What an edit does to the money: + the customer pays more, − we refund.
const editDelta = (o, next) => round2(chargeFor(next) - chargeFor(o));
async function applyOrderEdit(number, input, by) {
  const o = orders.get(number);
  const next = await editedOrder(o, input);
  const delta = editDelta(o, next);
  const was = o.total;
  const n = (o.edits || []).length + 1;
  const change: any = { lines: next.lines, subtotal: next.subtotal, tax: next.tax ?? o.tax, total: next.total, discount: next.discount, shipping: next.shipping ?? o.shipping };
  if (o.source === "wholesale") {
    // The old invoice can't be paid once the amount changes: cancel it, then send a new one.
    const old = o.wholesale?.invoice;
    if (old?.id) await sq.cancelInvoice(old.id);
    change.wholesale = { ...next.wholesale, invoice: null, ...(old && { voided: [...(o.wholesale.voided || []), old] }) };
  } else if (delta < 0 && o.square?.paymentId && squareConfigured()) {
    // Less to pay: refund the difference first (nothing changes if Square says no).
    await refundCard(o, -delta, `Order ${o.number} changed`, { by, notify: false });
    change.editedOff = round2((o.editedOff || 0) - delta);
  } else if (delta > 0 && squareConfigured() && o.square?.paymentId) {
    // More to pay: a Square invoice for the difference, due now, emailed to them.
    const customerId = await sq.customerFor({ email: o.contact.email, name: o.contact.name });
    const invNumber = `${o.number}-E${n}`;
    const { order: sqOrder } = await square("POST", "orders", { idempotency_key: sq.key("edit", invNumber), order: { location_id: sq.locationId(), reference_id: o.number, customer_id: customerId, source: { name: "Mimi Food order change" }, line_items: [{ name: `Added to order ${o.number}`, quantity: "1", base_price_money: sq.money(delta, CURRENCY()) }] } });
    const inv = await sq.invoice({ orderId: sqOrder.id, customerId, dueDate: shopToday(), number: invNumber, title: `${DATA.SITE.name} order ${o.number}: what you added`, idempotencyKey: sq.key("einv", invNumber) });
    change.editDue = { amount: delta, invoiceId: inv.id, number: inv.invoice_number || invNumber, url: inv.public_url || null, at: new Date().toISOString(), paid: false };
  } else if (delta > 0) change.editDue = { amount: delta, invoiceId: null, number: null, url: null, at: new Date().toISOString(), paid: false };
  // Less to pay but not paid by card through Square: the team refunds it, and the order says so.
  else if (delta < 0) change.editRefundDue = round2((o.editRefundDue || 0) - delta);
  // Stock: put back what it took, take what it holds now.
  if (o.stockTaken?.length) await stock.move(o.stockTaken, 1, { reason: "Order edited", ref: o.number, by });
  change.stockTaken = o.stockTaken?.length || o.payment === "paid" ? await stock.move(stockUnits(next.lines), -1, { reason: "Order edited", ref: o.number, by }) : o.stockTaken || null;
  change.edits = [...(o.edits || []), { at: new Date().toISOString(), by, from: was, to: next.total, delta }];
  let updated = await orders.update(o.number, change, { by, note: `Items changed: ${money(was)} → ${money(next.total)}${delta < 0 ? (change.editedOff ? `, ${money(-delta)} refunded` : `, ${money(-delta)} to refund`) : delta > 0 ? `, ${money(delta)} to pay` : ""}` });
  syncCatalog();
  if (o.source === "wholesale" && o.wholesale?.invoice && squareConfigured()) {
    try {
      updated = await invoiceWholesale(updated);
    } catch (error) {
      // Changed, but the new invoice didn't go: the order shows Send Invoice for it.
      console.error(`[edit] ${o.number} invoice:`, error.message);
    }
  }
  if (o.source !== "wholesale" && emailConfigured()) {
    const first = firstName(o.contact.name);
    const items = updated.lines.map((l) => `${l.qty} × ${l.title}${l.variant ? ` (${l.variant})` : ""}`).join("\n");
    const money2 = delta < 0 ? (change.editedOff ? `We've refunded ${money(-delta)}. It should appear on your statement within 5–10 business days.` : `We'll refund you ${money(-delta)}.`) : delta > 0 ? (updated.editDue?.url ? `There's ${money(delta)} to pay for what you added: ${updated.editDue.url}` : `There's ${money(delta)} to pay for what you added. We'll be in touch about it.`) : "";
    const text = `Hi ${first},\n\nWe've changed order ${o.number} as asked. It's now:\n\n${items}\n\nTotal ${money(updated.total)}.${money2 ? `\n\n${money2}` : ""}`;
    await sendOrderEmail({ to: o.contact.email, subject: `Your Mimi Food order ${o.number} has changed`, text: `${text}\n\nQuestions? Reply to this email.\n\nMimi Food`, html: emailHtml(text, "", updated.editDue?.url && delta > 0 ? { href: updated.editDue.url, label: "Pay the Difference" } : null) }).catch((e) => console.error("[edit] email:", e.message));
  }
  return { order: updated, delta };
}
// The invoice for what was added to an order, paid or cancelled in Square.
async function editInvoiceChanged(inv, type) {
  const o = orders.find((x) => x.editDue?.invoiceId === inv.id);
  if (!o) return false;
  const balance = inv.payment_requests?.[0];
  const paid = inv.status === "PAID" || (type === "invoice.payment_made" && (!balance || sq.fromMoney(balance.total_completed_amount_money) + 0.005 >= sq.fromMoney(balance.computed_amount_money)));
  if (paid && !o.editDue.paid) await orders.update(o.number, { editDue: { ...o.editDue, paid: true, paidAt: new Date().toISOString() } }, { by: "square", note: `${money(o.editDue.amount)} for the change paid` });
  else if (inv.status === "CANCELED" && !o.editDue.cancelled) await orders.update(o.number, { editDue: { ...o.editDue, cancelled: true } }, { by: "square", note: "Invoice for the change cancelled in Square" });
  return true;
}

// A cancelled order stops what's under way: its courier is cancelled, an unused label is voided
// (the carrier refunds it), and its gift deliveries are cancelled too. What can't be undone is
// noted on the order and emailed to the shop.
async function cancelUnderway(number) {
  const order = orders.get(number);
  if (!order) return;
  const problems = [];
  if (courierActive(order.courier) && (COURIER_RANK[order.courier.status] ?? 0) < 5) {
    try {
      await couriers.PROVIDERS[order.courier.provider || "uber"]?.cancel(order.courier.id);
      await orders.update(number, { courier: { ...order.courier, status: "cancelled", updatedAt: new Date().toISOString() } }, { by: "system", note: "Courier cancelled" });
    } catch (error) {
      problems.push("The courier couldn't be cancelled. Cancel it in Uber Direct.");
    }
  } else if (courierActive(order.courier)) problems.push("The courier already has the order: ask them to bring it back.");
  if (order.label && !order.label.voided) {
    try {
      await (order.label.provider === "shippo" ? shippo : shipstation).voidLabel(order.label.shipmentId);
      await orders.update(number, { label: { ...order.label, voided: true }, tracking: null }, { by: "system", note: `Voided ${order.label.carrier} label ${order.label.trackingNumber}` });
    } catch (error) {
      problems.push(`The ${order.label.carrier} label couldn't be voided. Void it in ${order.label.provider === "shippo" ? "Shippo" : "ShipStation"}.`);
    }
  }
  for (const g of order.giftDeliveries || []) {
    const child = g.number && orders.get(g.number);
    // One that's gone out already stays as it is.
    if (!child || ["cancelled", "shipped", "completed"].includes(child.status)) continue;
    await orders.update(child.number, { status: "cancelled" }, { by: "system", note: `Cancelled with ${number}` });
    await cancelUnderway(child.number);
  }
  if (problems.length) {
    await orders.update(number, {}, { by: "system", note: problems.join(" ") });
    await notifyShop(DATA.SITE.ordersEmail, `Check cancelled order ${number}`, `${problems.join("\n")}\n\n${orderText(order)}`);
  }
}

// One booking at a time per order, and never while a courier is already on it (a double tap
// or a second tab would book two).
const booking = new Set();
const courierActive = (c) => c?.id && (COURIER_RANK[c.status] ?? 0) >= 1 && (COURIER_RANK[c.status] ?? 0) <= 7;
async function bookCourier(number) {
  if (booking.has(number)) return orders.get(number);
  booking.add(number);
  try {
    return await bookCourierOnce(number);
  } finally {
    booking.delete(number);
  }
}
async function bookCourierOnce(number) {
  const order = orders.get(number);
  if (!order || order.status === "cancelled") return null;
  if (courierActive(order.courier)) return order;
  const cafe = order.cafe?.mode === "delivery" ? order.cafe : null;
  if (!cafe && order.fulfilment !== "Local delivery") return null;
  const attempt = (order.courier?.attempt || 0) + 1;
  const keep = (courier, note?) => orders.update(number, { courier: { provider: couriers.configured()[0] || order.courier?.provider, miles: order.courier?.miles, from: order.courier?.from, quote: order.courier?.quote ?? null, ...courier, attempt } }, { by: "system", note });
  if (!couriers.configured().length) {
    await keep({ status: "not_booked", error: "Uber Direct isn't set up, so book a courier yourself." });
    await notifyShop(DATA.SITE.ordersEmail, `Book a courier for ${number}`, `${orderText(order)}

No courier service is set up on the site, so this delivery needs a courier booked by hand.`);
    return orders.get(number);
  }
  const bar = barOf(cafe ? cafe.location : LOCAL.from);
  const to = cafe
    ? { name: order.contact.name, phone: order.contact.phone, parts: { street: cafe.address.street, city: cafe.address.city, state: DATA.SITE.shipFrom.state || "CA", zip: cafe.address.postcode } }
    : { name: order.shipTo.name || order.contact.name, phone: dropoffPhone(order), parts: shipParts(order.shipTo) };
  const job = {
    id: `${number}-${attempt}`,
    ref: number,
    from: pickupFrom(bar),
    to,
    value: order.subtotal,
    pickupTime: courierPickup(cafe, order),
    items: order.lines,
    note: order.notes,
  };
  // The courier calls the shop at pickup: Uber won't book without its number.
  if (!uber.phoneE164(job.from.phone)) {
    await keep({ id: job.id, status: "failed", error: `Add ${bar.name}'s phone number to the site (couriers need it to book a pickup).` }, "Courier booking failed");
    return orders.get(number);
  }
  try {
    const { provider, delivery } = await couriers.book(job, order.courier?.provider);
    await keep({ ...delivery, provider, error: null }, `Courier booked (${couriers.providerName(provider)} ${delivery.id})`);
  } catch (error) {
    console.error(`[courier] ${number}:`, error.message);
    await keep({ id: job.id, status: "failed", error: error.message }, "Courier booking failed");
    await notifyShop(DATA.SITE.ordersEmail, `Courier not booked for ${number}`, `${error.message}

Open the order in the back office and press “Book courier” to try again.

${orderText(order)}`);
  }
  return orders.get(number);
}

// Uber Direct status updates (signed with UBER_DIRECT_WEBHOOK_SECRET).
// A courier update (Uber's webhook, or a fresh look): the order follows the courier, and the
// customer hears when it's on its way and when it's delivered.
// The courier's steps in order: a late update for an earlier step doesn't move it back.
const COURIER_RANK = { waiting: 0, not_booked: 0, failed: 0, created: 1, confirmed: 2, enroute_to_pickup: 3, arrived_at_pickup: 4, picked_up: 5, enroute_to_dropoff: 6, arrived_at_dropoff: 7, delivered: 8, cancelled: 9, returned: 9 };
async function applyCourier(order, latest, by) {
  const known = Object.fromEntries(Object.entries(latest).filter(([, v]) => v != null && v !== ""));
  let status = known.status || order.courier.status;
  if ((COURIER_RANK[status] ?? 0) < (COURIER_RANK[order.courier.status] ?? 0)) status = order.courier.status;
  const changes: any = { courier: { ...order.courier, ...known, status, updatedAt: new Date().toISOString() } };
  // A cancelled order stays cancelled, whatever the courier does next.
  const live = order.status !== "cancelled";
  if (live && ["picked_up", "enroute_to_dropoff", "arrived_at_dropoff"].includes(status) && ["new", "packed", "ready"].includes(order.status)) changes.status = "shipped";
  if (live && status === "delivered" && order.status !== "completed") changes.status = "completed";
  const updated = await orders.update(order.number, changes, { by, note: uber.COURIER_STATUS[status] && status !== order.courier.status ? `Courier: ${uber.COURIER_STATUS[status]}` : undefined });
  if (changes.status === "shipped") await tellCustomer(updated, "shipped");
  if (changes.status === "completed") await tellCustomer(updated, "delivered");
  if (status === "cancelled" && order.courier.status !== status) {
    await notifyShop(DATA.SITE.ordersEmail, `Courier ${status} for ${order.number}`, `The courier reports the delivery for ${order.number} was ${status}. Open it in the back office to book another courier.`);
  }
  // Brought back undelivered: the customer chooses a free reship or a refund.
  if (status === "returned" && order.courier.status !== status) return flagDeliveryIssue(updated, "courier", "", by);
  return updated;
}

// Where a parcel is, from Shippo (its webhook says when to look; the tracking page looks too
// when it's been a while). The order follows it: first scan = shipped, delivered = completed,
// and the customer is emailed at each, and when it's out for delivery.
async function refreshParcel(order, by = "shippo") {
  const t = order.tracking;
  if (!t?.number || !shippo.shippoConfigured()) return order;
  t.sent ||= {}; // on the live order before the lookup, so two lookups at once email once
  const now = await shippo.track(t.carrier, t.number);
  order = orders.get(order.number) || order;
  const sent = order.tracking?.sent || t.sent;
  const tracking = { ...(order.tracking || t), status: now.status, text: now.text, at: now.at, place: now.place, zip: now.zip, eta: now.eta, history: now.history, checkedAt: new Date().toISOString(), sent };
  const changes: any = { tracking };
  const live = order.status !== "cancelled" && order.status !== "completed"; // delivered stays delivered
  const moving = ["transit", "out_for_delivery", "delivered"].includes(now.status);
  if (live && moving && ["new", "packed", "ready"].includes(order.status)) changes.status = "shipped";
  if (live && now.status === "delivered") changes.status = "completed";
  const note = now.status !== t.status && now.text ? `${t.carrier || "Carrier"}: ${now.text}${now.place ? ` (${now.place})` : ""}` : undefined;
  const outNow = live && now.status === "out_for_delivery" && !sent.outForDelivery;
  if (outNow) sent.outForDelivery = true;
  const updated = await orders.update(order.number, changes, { by, note });
  if (changes.status === "shipped") await tellCustomer(updated, "shipped");
  if (outNow) await tellCustomer(updated, "out_for_delivery");
  if (changes.status === "completed") await tellCustomer(updated, "delivered");
  // The carrier is sending it back (refused, bad address, unclaimed): the customer chooses what next.
  if (live && (now.status === "returned" || now.status === "failure") && !updated.deliveryIssue) return flagDeliveryIssue(updated, "returned", now.text, by);
  return updated;
}

// What the customer's tracking page shows: our own steps and times, with no courier or
// carrier branding (the courier's first name, a parcel's latest scan and expected day).
function trackView(o) {
  const kind = o.cafe ? (o.cafe.mode === "delivery" ? "courier" : "cafe") : o.fulfilment === "Local delivery" ? "courier" : o.fulfilment === "Pickup" ? "pickup" : o.shipTo ? "parcel" : "other";
  const when = (...states) => o.history.find((h) => states.includes(h.status))?.at || null;
  const rank = { pending_payment: 0, new: 1, packed: 2, ready: 2, shipped: 3, completed: 5, cancelled: -1 }[o.status] ?? 1;
  const out = o.tracking?.status === "out_for_delivery" || o.tracking?.status === "delivered";
  const outAt = (o.tracking?.history || []).find((h) => h.status === "out_for_delivery")?.at || null;
  // Scans without the carrier's name ("Arrived at USPS regional facility" → "Arrived at regional facility").
  const plain = (text) => String(text || "").replace(/\b(USPS|UPS|FedEx|FEDEX|DHL( Express)?)\b\s*/g, "").replace(/\s{2,}/g, " ").trim();
  const scan = (h) => ({ text: plain(h.text), at: h.at, place: h.place });
  const c = o.courier || {};
  const steps =
    kind === "courier"
      ? [["Ordered", o.placedAt, rank >= 1], ["Preparing", when("packed", "ready"), rank >= 2 || ["created", "confirmed", "enroute_to_pickup", "arrived_at_pickup"].includes(c.status)], ["On its way", when("shipped"), rank >= 3], ["Delivered", when("completed"), rank >= 5]]
      : kind === "parcel"
        ? [["Ordered", o.placedAt, rank >= 1], ["Packed", when("packed") || o.label?.createdAt || null, rank >= 2 || Boolean(o.label && !o.label.voided)], ["Shipped", when("shipped"), rank >= 3], ["Out for delivery", outAt, out || rank >= 5], ["Delivered", when("completed"), rank >= 5]]
        : [["Ordered", o.placedAt, rank >= 1], ["Preparing", when("packed"), rank >= 2], ["Ready", when("ready"), rank >= 2 && o.status !== "packed"], ["Collected", when("completed"), rank >= 5]];
  const loc = o.cafe ? DATA.LOCATIONS.find((l) => l.id === o.cafe.location) : DATA.LOCATIONS.find((l) => l.id === "roastery");
  return {
    number: o.number,
    placedAt: o.placedAt,
    status: o.status,
    kind,
    steps: steps.map(([label, at, done]) => ({ label, at: done ? at : null, done: Boolean(done) })),
    courier: kind === "courier" ? { name: String(c.dasher || "").split(" ")[0] || null, status: c.status || null, pickupEta: c.pickupEta || null, dropoffEta: c.dropoffEta || null, day: c.day || null } : null,
    parcel: kind === "parcel" && o.tracking?.number ? { number: o.tracking.number, status: o.tracking.status || null, eta: o.tracking.eta || null, latest: o.tracking.text ? scan(o.tracking) : null, history: (o.tracking.history || []).map(scan) } : null,
    place: kind === "pickup" || kind === "cafe" ? { name: loc?.name || "Roastery House", address: loc?.address || [] } : null,
    to: o.shipTo ? { city: o.shipTo.city, state: o.shipTo.state } : null,
    lines: allLines(o).map((l) => ({ title: l.title, variant: l.variant, qty: l.qty })),
    total: o.total,
    receipt: ["paid", "refunded", "partially_refunded"].includes(o.payment) && o.trackToken ? `/receipt?order=${encodeURIComponent(o.number)}&t=${o.trackToken}` : null,
    returnable: returnableLines(o).map(({ index, l, left }) => ({ index, title: l.title, variant: l.variant, qty: left, swaps: swapsFor(l) })),
    returnReasons: RETURN_REASONS,
    claimable: claimableLines(o).map(({ index, l, left }) => ({ index, title: l.title, variant: l.variant, qty: left })),
    claimBy: claimBy(o),
    claimRefund: claimRefundable(o),
    claimProblems: CLAIM_PROBLEMS,
    claims: (o.claims || []).map(claimView),
    deliveryIssue: o.deliveryIssue ? { kind: o.deliveryIssue.kind, status: o.deliveryIssue.status, reship: o.deliveryIssue.reship || null, canRefund: Boolean(o.square?.paymentId) && chargeNow(o) - (o.refunded || 0) > 0.004, shipTo: o.shipTo ? { address: o.shipTo.address, city: o.shipTo.city, state: o.shipTo.state, postcode: o.shipTo.postcode } : null } : null,
    credits: promos.creditsFor(o.contact.email),
    returnBy: returnBy(o),
    returns: (o.returns || []).filter((r) => r.status !== "cancelled").map(returnView),
  };
}

/* ── Receipts ──────────────────────────────────────────────────
   Our own receipt for a paid order (/receipt?order=…&t=…, the same link token as tracking), in
   place of Square's: the items, the totals as the order email shows them, how it was paid (card
   brand and last four, Apple Pay or Google Pay, a gift card), refunds, and the shop. */

async function receiptView(o) {
  // Orders paid before the card was kept: asked of Square once, then kept.
  if (o.square?.paymentId && o.square.card === undefined && squareConfigured()) {
    try {
      const { payment } = await square("GET", `payments/${encodeURIComponent(o.square.paymentId)}`);
      o = (await orders.update(o.number, { square: { ...o.square, card: sq.cardOf(payment) } }, { by: "system" })) || o;
    } catch (error) {
      console.warn(`[receipt] ${o.number}: ${error.message}`);
    }
  }
  const s = o.square || {};
  const paidAt = o.history.find((h) => /^Paid|^Nothing to pay/.test(h.note || ""))?.at || o.history.find((h) => h.status === "new")?.at || o.placedAt;
  const card = s.card ? `${s.card.brand} •••• ${s.card.last4}` : "Card";
  const payments = s.giftPaymentId
    ? [{ method: `Gift card •••• ${o.giftCard?.last4 || ""}`.trim(), amount: s.giftPaid || 0 }, ...(s.cardPaid > 0 ? [{ method: card, wallet: s.wallet || null, amount: s.cardPaid }] : [])]
    : s.paymentId
      ? [{ method: card, wallet: s.wallet || null, amount: chargeNow(o) }]
      : [];
  const roastery = DATA.LOCATIONS.find((l) => l.id === "roastery");
  return {
    number: o.number,
    paidAt,
    name: o.contact?.name || "",
    lines: allLines(o).map((l) => ({ title: l.title, detail: lineDetail(l), qty: l.qty, total: round2(l.price * l.qty), later: l.kind === "sub" })),
    totals: orderTotals(o)
      .filter(([label]) => label !== "Paid")
      .map(([label, value, bold]) => ({ label, value, bold: Boolean(bold) })),
    payments,
    refunded: o.refunded || 0,
    where: orderWhere(o).filter((x) => !x.startsWith("Notes:")),
    shop: { name: DATA.SITE.name, address: mailingAddress().split(/\s*\n\s*/).filter(Boolean).length ? mailingAddress().split(/\s*\n\s*/).filter(Boolean) : roastery?.address || [], email: DATA.SITE.ordersEmail, site: SITE_URL.replace(/^https?:\/\//, "") },
  };
}

async function handleReceipt(req, res, url, number) {
  if (rateLimited(clientIp(req), "track", 120)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  const order = orders.get(number);
  if (!trackAllowed(req, order, url.searchParams.get("t"))) return sendJson(res, 404, { error: "Receipt not found. Check your email link." });
  if (!["paid", "refunded", "partially_refunded"].includes(order.payment)) return sendJson(res, 404, { error: "There's no receipt for this order yet." });
  sendJson(res, 200, { receipt: await receiptView(order) }, { "Cache-Control": "no-store" });
}

const receiptUrl = async (order) => (await trackUrl(order)).replace("/track?", "/receipt?");

/* ── Returns ───────────────────────────────────────────────────
   Coffee can't come back; anything else can, unused, within SITE.returns.days of delivery, free.
   The customer starts it from the order's tracking page, says why, and picks what they'd like:
   their money back, store credit, or (for a size or color) a swap. It's dropped at Roastery House
   (staff scan its QR code to check it in) or sent by mail on a prepaid Shippo return label
   (charged only once used; its QR code goes in the box, scanned when it arrives). Checking it in
   records its condition (a resellable item goes back into stock) and then refunds the card,
   issues the credit, or sends the swap. */

const RETURN_REASONS = { changed_mind: "Changed my mind", wrong_size: "Wrong size or color", not_as_described: "Not as described", not_needed: "Ordered by mistake", other: "Something else" };
// Other sizes or colors an accessory line could be swapped for (in stock, or not counted).
function swapsFor(l) {
  const a = DATA.ACCESSORIES.find((x) => x.id === l.product);
  if (!a || l.kind !== "accessory") return [];
  const sizes = a.sizes?.length ? a.sizes : null;
  const all = sizes || (a.colors || []).map((c) => c.name);
  const mine = sizes ? l.size : l.color;
  return all.filter((v) => v && v !== mine && a.leftBy?.[v] !== 0 && !a.soldOut);
}
// The line a swap sends: the same item in the other size or color, at no charge.
function swappedLine(l, to) {
  const a = DATA.ACCESSORIES.find((x) => x.id === l.product);
  const size = a?.sizes?.length ? to : l.size || "";
  const color = a?.sizes?.length ? l.color || "" : to;
  return { ...l, size, color, variant: [color, size && `Size ${size}`, a?.pack].filter(Boolean).join(" · "), price: 0 };
}

const deliveredAt = (o) => o.history.find((h) => h.status === "completed")?.at || null;
const returnBy = (o) => {
  const d = deliveredAt(o);
  return d ? new Date(Date.parse(d) + RETURN_DAYS() * 864e5).toISOString() : null;
};
// The order's own lines that can still come back: { index, l, left } (gifts are their own orders).
function returnableLines(o) {
  const by = returnBy(o);
  if (!by || Date.now() > Date.parse(by) || o.status !== "completed" || !o.square?.paymentId || o.payment === "refunded") return [];
  const back = new Map();
  for (const r of o.returns || []) if (r.status !== "cancelled") for (const i of r.items) back.set(i.index, (back.get(i.index) || 0) + i.qty);
  return o.lines.map((l, index) => ({ index, l, left: l.qty - (back.get(index) || 0) })).filter(({ l, left }) => l.kind === "accessory" && l.category !== "Tea" && left > 0);
}
// What the returned items cost the customer: their price, less their share of a code, plus their tax.
function returnValue(o, items) {
  // The lines the code took money off (as at checkout): not subscriptions, prepaid gifts or gift cards.
  const goods = allLines(o).filter((l) => l.kind !== "sub" && l.kind !== "prepaid" && l.kind !== "giftcard").reduce((n, l) => n + l.price * l.qty, 0);
  const off = o.discount?.amount || 0;
  const value = items.reduce((n, i) => {
    const l = o.lines[i.index];
    const net = l.price * i.qty * (goods > 0 ? 1 - off / goods : 1);
    return n + net * (1 + (o.taxRates?.[DATA.taxClass(l)] || 0));
  }, 0);
  return Math.min(round2(value), round2(chargeNow(o) - (o.refunded || 0)));
}
const returnQr = (r) => `${SITE_URL}/api/returns/qr/${r.code}.png`;
const returnView = (r) => ({
  id: r.id,
  method: r.method,
  status: r.status,
  items: r.items.map((i) => ({ title: i.title, variant: i.variant, qty: i.qty, swapTo: i.swapTo || null })),
  amount: r.amount,
  resolution: r.resolution || "refund",
  refunded: r.refunded ?? null,
  credit: r.creditCode ? { code: r.creditCode, amount: r.creditAmount } : null,
  exchange: r.exchange || null,
  createdAt: r.createdAt,
  qr: r.status === "open" ? returnQr(r) : null,
  label: r.label && !r.label.voided && r.status === "open" ? { url: r.label.labelUrl, carrier: r.label.carrier, qr: r.label.qrUrl || null, dropoff: r.label.dropoff || null, doorPickup: Boolean(r.label.doorPickup) && !r.label.scannedAt, pickupDays: r.label.doorPickup && !r.pickup ? pickupDays() : [] } : null,
  pickup: r.pickup && r.status === "open" ? { day: r.pickup.day, spot: r.pickup.spot, note: r.pickup.note || "", start: r.pickup.start, end: r.pickup.end, confirmation: r.pickup.confirmation } : null,
  onItsWay: Boolean(r.label?.scannedAt),
  arrived: Boolean(r.arrivedAt),
  labelPending: Boolean(r.labelPending && !r.label),
});

const RESOLUTION_LABEL = { refund: "Refund", credit: "Store credit", exchange: "Exchange" };
// One return at a time per order, so two quick taps can't start two (or take the same items twice).
const startingReturn = new Set();
async function startReturn(order, input = {}) {
  if (startingReturn.has(order.number)) throw new OrderError("A return for this order is already being started.");
  startingReturn.add(order.number);
  try {
    return await startReturnNow(orders.get(order.number) || order, input);
  } finally {
    startingReturn.delete(order.number);
  }
}
async function startReturnNow(order, { items = [], method, reason: reasonKey = "", note = "", want = "refund" }: { items?: any; method?: any; reason?: any; note?: any; want?: any } = {}) {
  if (!["dropoff", "mail"].includes(method)) throw new OrderError("Choose how to send it back.");
  const open = new Map<any, any>(returnableLines(order).map((x) => [x.index, x]));
  const picked = [];
  for (const it of [].concat(items)) {
    const x = open.get(Number(it.index));
    const qty = Math.round(Number(it.qty) || 0);
    if (!x || qty < 1 || qty > x.left) throw new OrderError("That item can't be returned.");
    picked.push({ index: x.index, qty, title: x.l.title, variant: x.l.variant, price: x.l.price, weightOz: x.l.weightOz || 0 });
  }
  if (!picked.length) throw new OrderError("Choose what to return.");
  const reason = RETURN_REASONS[reasonKey] ? reasonKey : "other";
  const resolution = ["refund", "credit", "exchange"].includes(want) ? want : "refund";
  if (resolution === "exchange") {
    for (const it of picked) {
      const to = String([].concat(items).find((x) => Number(x.index) === it.index)?.swapTo || "");
      if (!swapsFor(order.lines[it.index]).includes(to)) throw new OrderError(`Choose the size or color you'd like for ${it.title}.`);
      it.swapTo = to;
    }
  }
  const r: any = { id: `R${(order.returns || []).length + 1}`, code: randomBytes(12).toString("base64url"), method, status: "open", items: picked, amount: returnValue(order, picked), reason, note: String(note || "").trim().slice(0, 500), resolution, createdAt: new Date().toISOString() };
  // A mail return always starts: if no label can be made now, it's emailed once it can.
  if (method === "mail") r.label = (await returnLabel(order, r)) || null;
  if (method === "mail" && !r.label) r.labelPending = { since: r.createdAt, tries: 1 };
  await orders.update(order.number, { returns: [...(orders.get(order.number).returns || []), r] }, { by: "customer", note: `Return ${r.id} started (${method === "mail" ? "by mail" : "drop-off"}, ${RESOLUTION_LABEL[resolution].toLowerCase()}): ${picked.map((i) => `${i.qty} × ${i.title}`).join(", ")}. Why: ${RETURN_REASONS[reason]}${r.note ? ` (${r.note})` : ""}` });
  const updated = orders.get(order.number);
  emailReturn(updated, r).catch((e) => console.error("[returns] email:", e.message));
  notifyShop(DATA.SITE.ordersEmail, `Return started for ${order.number}`, `${r.method === "mail" ? (r.label ? `By mail (${r.label.carrier} ${r.label.trackingNumber})` : "By mail (label still being made)") : "Drop-off at Roastery House"}\n${picked.map((i) => `${i.qty} × ${i.title} ${i.variant || ""}${i.swapTo ? ` → ${i.swapTo}` : ""}`).join("\n")}\nWhy: ${RETURN_REASONS[reason]}${r.note ? ` (${r.note})` : ""}\nWhen checked in: ${resolution === "exchange" ? "send the swap" : `${RESOLUTION_LABEL[resolution].toLowerCase()} of ${money(r.amount)}`}\n\n${SITE_URL}/admin/returns/${r.code}`).catch(() => {});
  return { order: updated, ret: r };
}

// A prepaid return label from the carrier that's best for both sides: what the label costs us
// plus how far the customer has to take it (server/dropoff.ts), and where to drop it off: the
// nearest location for that carrier, with the next two. USPS labels are charged only once used;
// another carrier's is voided later if it's never sent. Null if no label can be bought.
async function returnLabel(order, r) {
  if (!shippo.shippoConfigured()) return null;
  const P = DATA.SITE.postage || {};
  const job = { shipFrom: shipFromAddress(), shipTo: labelShipTo(order), weightOz: Math.max(8, r.items.reduce((n, i) => n + (i.weightOz || 0) * i.qty, 0) + 4), box: P.box || { length: 9, width: 6, height: 4 }, maxDays: null, isReturn: true };
  const to = job.shipTo;
  const [quotes, places] = await Promise.all([
    shippo.rates(job).catch((error) => (console.error(`[returns] ${order.number} rates:`, error.message), [])),
    geocoder.geocodeAddress({ street: to.street1, city: to.city, state: to.state, zip: to.postalCode }).then(nearbyDropoffs).catch(() => []),
  ]);
  const spot = (p) => p && { name: p.name, address: p.address, miles: p.miles, point: p.point, hours: p.hours || "" };
  for (const pick of rankReturnCarriers(quotes, places, DATA.SITE.returnChoice || {})) {
    try {
      const label = await shippo.buyRate(pick.rate, { orderNumber: order.number, isReturn: true });
      const usps = /^usps$/i.test(label.carrier);
      console.log(`[returns] ${order.number}: ${label.carrier} ${money(label.cost)}${pick.place ? `, ${pick.place.name} ${pick.place.miles} mi` : ""} (score ${pick.score})`);
      return {
        provider: "shippo", shipmentId: label.shipmentId, trackingNumber: label.trackingNumber, labelUrl: label.labelUrl, carrier: label.carrier, cost: label.cost, createdAt: new Date().toISOString(), payOnUse: usps,
        // USPS's printer-free code (shown at a Post Office counter), when it gives one.
        qrUrl: label.qrCodeUrl || null,
        carrierAccount: label.carrierAccount || "",
        dropoff: pick.place ? { ...spot(pick.place), week: await placeHours(pick.place), others: pick.nearby.slice(1).map(spot) } : null,
        // USPS collects from the door: booked on the return page (Shippo's pickups).
        doorPickup: usps && Boolean(label.carrierAccount),
      };
    } catch (error) {
      console.error(`[returns] ${order.number} ${pick.rate.carrierCode} label:`, error.message);
    }
  }
  return null;
}

// A drop-off's opening hours by day ([{ day: "Monday", hours: "9 AM–5 PM" }]), from its Google
// Maps listing through AnyAPI: one lookup, for the place we send them to. Empty without AnyAPI.
async function placeHours(p) {
  if (!research.paid() || !p?.name) return [];
  try {
    const r = await research.run("maps.place", { query: [p.name, p.address].filter(Boolean).join(", ") }, `Drop-off hours: ${p.name}`);
    return weekHours(r.data?.items?.[0]?.hours);
  } catch (error) {
    console.warn("[returns] hours:", error.message);
    return [];
  }
}
// Google's hours, in whatever shape the source gives them: "Monday: 9 AM–5 PM", or an object with
// the day's name and its hours.
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
function weekHours(list) {
  const out = [];
  for (const h of Array.isArray(list) ? list : []) {
    let day = "";
    let hours = "";
    if (typeof h === "string") [day, hours] = h.split(/:\s*(.*)/s);
    else if (h && typeof h === "object") {
      day = String(h.day ?? h.dayOfWeek ?? h.weekday ?? h.name ?? "");
      const v = h.hours ?? h.time ?? h.times ?? h.open ?? h.value;
      hours = Array.isArray(v) ? v.join(", ") : String(v ?? "");
    }
    const key = String(day).trim().toLowerCase().slice(0, 3);
    const name = key.length === 3 && WEEKDAYS.find((d) => d.toLowerCase().startsWith(key));
    if (name && hours.trim()) out.push({ day: name, hours: hours.trim().slice(0, 60) });
  }
  return out.slice(0, 7);
}
// "Open today 9 AM–5 PM" for a drop-off, on the shop's calendar day (for emails).
const todayHours = (d) => {
  const today = new Date().toLocaleDateString("en-US", { weekday: "long", timeZone: DATA.SITE.timezone || "America/Los_Angeles" });
  const h = (d?.week || []).find((x) => x.day === today);
  return h ? (/closed/i.test(h.hours) ? "closed today" : `open today ${h.hours}`) : "";
};

// Every 15 minutes: labels that couldn't be made are tried again (emailed when made; the shop
// hears after two hours of trying), and a label from a carrier that charges up front is voided
// (refunded) if it hasn't been used within 21 days.
async function returnsTick() {
  for (const o of orders.list({})) {
    for (const r of o.returns || []) {
      if (r.status !== "open" || r.method !== "mail") continue;
      if (!r.label && r.labelPending) {
        const label = await returnLabel(o, r);
        const fresh = orders.get(o.number);
        const next = (x) => (x.id !== r.id ? x : label ? { ...x, label, labelPending: null } : { ...x, labelPending: { ...x.labelPending, tries: x.labelPending.tries + 1 } });
        await orders.update(o.number, { returns: fresh.returns.map(next) }, label ? { by: "system", note: `Return ${r.id} label made (${label.carrier})` } : { by: "system" });
        if (label) await emailReturn(orders.get(o.number), { ...r, label, labelPending: null });
        else if (r.labelPending.tries + 1 === 8) await notifyShop(DATA.SITE.ordersEmail, `Return label needed for ${o.number}`, `The return label couldn't be made. Make one by hand and email it to ${o.contact.email}, or ask them to drop it at Roastery House.\n\n${SITE_URL}/admin/returns/${r.code}`);
      } else if (r.label && !r.label.payOnUse && !r.label.voided && !r.arrivedAt && Date.now() - Date.parse(r.label.createdAt || r.createdAt) > 21 * 864e5) {
        try {
          await shippo.voidLabel(r.label.shipmentId);
          const fresh = orders.get(o.number);
          await orders.update(o.number, { returns: fresh.returns.map((x) => (x.id === r.id ? { ...x, label: { ...x.label, voided: true } } : x)) }, { by: "system", note: `Unused return label ${r.label.trackingNumber} voided` });
        } catch (error) {
          console.error(`[returns] void ${o.number}:`, error.message);
        }
      }
    }
  }
}
const runReturnsTick = () =>
  returnsTick()
    .then(trackingSweep)
    .catch((e) => console.error("[returns]", e.message));
setTimeout(runReturnsTick, 60_000).unref?.();
setInterval(runReturnsTick, 15 * 60_000).unref?.();

// Where to take a return, for its email: the nearest place for the label's carrier, with
// directions, then the next ones, and USPS's free pickup.
const directionsTo = (p) => `https://www.google.com/maps/dir/?api=1&destination=${p.point.join(",")}`;
function dropoffText(label) {
  const d = label.dropoff;
  const any = DATA.returnDropoff(label.carrier);
  const lines = d
    ? [`Drop it off at ${d.name}${d.address ? `, ${d.address}` : ""} (${d.miles} mi${todayHours(d) ? `, ${todayHours(d)}` : ""}). Directions: ${directionsTo(d)}`, ...(d.others?.length ? [`Also near you: ${d.others.map((o) => `${o.name}${o.address ? `, ${o.address}` : ""} (${o.miles} mi)`).join("; ")}.`] : [])]
    : [`Drop it off: ${any?.where || `any ${label.carrier} location`}.${any ? ` Find one: ${any.find}` : ""}`];
  if (label.qrUrl) lines.unshift("No printer? Show the USPS code below at any Post Office counter. They print the label for you.");
  if (label.doorPickup) lines.push("Or have USPS collect it from your door, free: book a day on your order page.");
  return lines.join("\n");
}

// A return's next steps, by email: a pickup booked, on its way back (first scan), arrived.
async function emailReturnStep(order, r, step) {
  if (!emailConfigured()) return;
  const first = firstName(order.contact.name);
  const what = r.items.map((i) => `${i.qty} × ${i.title}`).join(", ");
  const dayName = (ymd) => new Date(`${ymd}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", timeZone: "UTC" });
  const text = {
    pickup: r.pickup && `Hi ${first},\n\nUSPS will collect your return (${what}) on ${dayName(r.pickup.day)}. Leave it ${r.pickup.spot === "Other" ? `where you said (${r.pickup.note})` : `at your ${r.pickup.spot.toLowerCase().replace("in/at mailbox", "mailbox")}`} by 9 AM, with the label on it.${r.pickup.confirmation ? `\n\nConfirmation: ${r.pickup.confirmation}` : ""}`,
    transit: `Hi ${first},\n\nYour return (${what}) is on its way back to us. ${afterReturn(r)} once it arrives and we've checked it.`,
    arrived: `Hi ${first},\n\nYour return (${what}) has arrived. We'll check it, then ${afterReturn(r).replace(/^We'll /, "")}.`,
  }[step];
  if (!text) return;
  const subject = { pickup: "Your return pickup is booked", transit: "Your return is on its way", arrived: "We've got your return" }[step];
  const link = await trackUrl(order);
  await sendOrderEmail({ to: order.contact.email, subject: `${subject} (order ${order.number})`, text: `${text}\n\nYour order: ${link}\n\nMimi Food`, html: emailHtml(text, "", { href: link, label: "View Order" }) });
}

// What happens once a return is checked in, for its emails.
const afterReturn = (r) => (r.resolution === "exchange" ? `We'll send ${r.items.map((i) => `${i.title} in ${i.swapTo}`).join(", ")}` : r.resolution === "credit" ? `We'll email you ${money(r.amount)} in store credit` : `We'll refund ${money(r.amount)}`);
async function emailReturn(order, r) {
  if (!emailConfigured()) return;
  const first = firstName(order.contact.name);
  const what = r.items.map((i) => `${i.qty} × ${i.title}`).join(", ");
  const roastery = DATA.LOCATIONS.find((l) => l.id === "roastery");
  const text =
    r.method === "mail" && !r.label
      ? `Hi ${first},\n\nYour return for ${what} is set up. We'll email your prepaid label shortly. Pack the item with this QR code inside. ${afterReturn(r)} once it arrives.`
      : r.method === "mail"
      ? `Hi ${first},\n\nYour return for ${what} is set up. Pack the item with the "Put in the box" code inside, then ${r.label.qrUrl ? "show the USPS code at a Post Office, or print the label and" : "print the label and"} send it back.\n\n${dropoffText(r.label)}\n\n${afterReturn(r)} once it arrives.`
      : `Hi ${first},\n\nYour return for ${what} is set up. Bring it to Roastery House, ${(roastery?.address || []).join(", ")}, and show this QR code. ${afterReturn(r)} once it's checked in.`;
  // USPS's code (no printer needed) first, when there is one; then ours, for inside the box.
  const uspsQr = r.label?.qrUrl ? `<p style="margin:0 0 6px;font-weight:600">Show at the Post Office</p><img src="${r.label.qrUrl}" width="180" height="180" alt="USPS label code" style="display:block;margin:0 0 20px;border:0">` : "";
  const html = emailHtml(text, "", r.label ? { href: r.label.labelUrl, label: "Print Return Label" } : null, { block: `${uspsQr}<p style="margin:0 0 6px;font-weight:600">Put in the box</p><img src="${returnQr(r)}" width="180" height="180" alt="Return code" style="display:block;margin:0 0 20px;border:0">` });
  await sendOrderEmail({ to: order.contact.email, subject: `Your return for order ${order.number}`, text: `${text}\n\n${r.label ? `Label: ${r.label.labelUrl}\n` : ""}QR code: ${returnQr(r)}\n\nMimi Food`, html });
}

// Checking a return in (the QR code scanned, or from the back office): refunds the card.
// Returns being checked in right now: a double scan waits for the first, so it's refunded once.
const receiving = new Set();
async function receiveReturn(code, by = "shop", check: any = {}) {
  const order = orders.list({}).find((o) => (o.returns || []).some((r) => r.code === code));
  const r = order?.returns.find((x) => x.code === code);
  if (!r) throw new OrderError("Return not found.");
  if (r.status !== "open") return { order, ret: r };
  if (receiving.has(code)) throw new OrderError("This return is being checked in already.");
  receiving.add(code);
  try {
    return await receiveOpenReturn(order, r, code, by, check);
  } finally {
    receiving.delete(code);
  }
}
// Checking a return in: its condition (resellable goes back into stock), then what the customer
// picked: the card refunded, store credit emailed, or the swap sent as a new order. Staff can
// refund less than the full amount (`amount`), say for an item that's been used.
async function receiveOpenReturn(order, r, code, by, { condition = "resellable", amount = null, note = "" }: any = {}) {
  const good = condition !== "damaged";
  const resolution = r.resolution || "refund";
  const value = amount == null || amount === "" ? r.amount : round2(Math.min(r.amount, Math.max(0, Number(amount) || 0)));
  const what = r.items.map((i) => `${i.qty} × ${i.title}`).join(", ");
  const done: any = { receivedAt: new Date().toISOString(), condition: good ? "resellable" : "damaged", checkNote: String(note || "").trim().slice(0, 300) };
  if (resolution === "exchange") {
    const lines = r.items.map((i) => ({ ...swappedLine(order.lines[i.index], i.swapTo), qty: i.qty }));
    const swap = await sendReplacement(order, lines, { source: "exchange", note: `Exchange for return ${r.id} on ${order.number}` });
    Object.assign(done, { status: "exchanged", exchange: swap.number });
  } else if (resolution === "credit") {
    const credit = value > 0 ? await promos.storeCredit({ amount: value, email: order.contact.email, order: order.number }) : null;
    Object.assign(done, { status: "credited", creditCode: credit?.code || null, creditAmount: value });
    if (credit) emailStoreCredit(order, credit, what).catch((e) => console.error("[returns] credit email:", e.message));
  } else {
    const refund = value > 0 ? await refundCard(order, value, `Return ${r.id}: ${what}`, { by, notify: true, shown: `For your return of ${what}.` }) : null;
    Object.assign(done, { status: "refunded", refundId: refund?.id || null, refunded: value });
  }
  // Back on the shelf: what came back, in its original size or color.
  if (good) {
    const units = stockUnits(r.items.map((i) => ({ ...order.lines[i.index], qty: i.qty })));
    if ((await stock.move(units, 1, { reason: "Returned", ref: order.number })).length) syncCatalog();
  }
  const now = orders.get(order.number);
  const returns = now.returns.map((x) => (x.code === code ? { ...x, ...done } : x));
  const said = { refunded: `refunded ${money(value)}`, credited: `${money(value)} store credit`, exchanged: `exchange sent as ${done.exchange}` }[done.status];
  await orders.update(order.number, { returns }, { by, note: `Return ${r.id} checked in (${done.condition}${good ? ", back in stock" : ""}): ${said}${done.checkNote ? `. ${done.checkNote}` : ""}` });
  return { order: orders.get(order.number), ret: returns.find((x) => x.code === code) };
}

// Store credit, by email: the code, what it's worth, and that it keeps until it's spent.
async function emailStoreCredit(order, credit, what) {
  if (!emailConfigured()) return;
  const first = firstName(order.contact.name);
  const intro = `Hi ${first},\n\nYour return (${what}) is checked in. Here's ${money(credit.value)} in store credit. Enter this code at checkout:`;
  const after = "Whatever you don't spend stays on the code for next time.";
  await sendOrderEmail({ to: order.contact.email, subject: `Your ${money(credit.value)} store credit`, text: `${intro}\n\n${credit.code}\n\n${after}\n\nShop: ${SITE_URL}/shop\n\nMimi Food`, html: emailHtml(intro, "", { href: `${SITE_URL}/shop`, label: "Shop Now" }, { block: emailCode(credit.code), note: after }) });
}

// A replacement or swap: a new order (paid, no charge) for these lines, to the same place as the
// original, packed and sent like any other. Takes its stock; the shop hears.
async function sendReplacement(order, lines, { source, note }) {
  const base = { contact: order.contact, lines, fulfilment: order.fulfilment === "Local delivery" ? "Delivery" : order.fulfilment, shipTo: order.shipTo || null, cafe: null, notes: note, subtotal: 0, shipping: 0, cafeFee: 0, total: 0, userId: order.userId || null, source, parent: order.number };
  const routed = await routeDelivery(base);
  const fresh = await orders.add(routed, { status: "new", payment: "paid", by: "system" });
  const taken = await stock.move(stockUnits(lines), -1, { reason: "Replacement sent", ref: fresh.number });
  if (taken.length) {
    await orders.update(fresh.number, { stockTaken: taken }, { by: "system" });
    syncCatalog();
  }
  autoLabel(fresh.number).catch((e) => console.error("[labels]", e.message));
  await notifyShop(DATA.SITE.ordersEmail, `${source === "exchange" ? "Exchange" : "Replacement"} ${fresh.number} for ${order.number}`, `${note}\n\n${orderText(orders.get(fresh.number))}`).catch(() => {});
  return orders.get(fresh.number);
}

/* ── Problems with an order ─────────────────────────────────────
   Report a Problem: something arrived damaged, wrong or missing (coffee and tea too, which can't
   be returned). The customer says what and sends photos from the tracking page; a wholesale
   account does the same from its portal. The shop approves it (a replacement sent at no charge,
   the card refunded, or for a wholesale account a credit off its next order) or declines it with
   a note. Delivery issues: a parcel the carrier sends back to us, or a courier who brings it back,
   is flagged; the customer confirms their address for a free reship, or takes a refund. */

const CLAIM_DAYS = () => DATA.SITE.claims?.days ?? 14;
const CLAIM_PROBLEMS = { damaged: "Arrived damaged", wrong: "Wrong item", missing: "Missing from the box", other: "Something else" };
const claimPhotos = await storage.open("claimphotos", { photos: (x) => x.id });

// A café's logo (portal Account, or the account in the back office): kept apart from the account
// so lists stay light, as a 256px PNG drawn here (an SVG becomes plain pixels, nothing runs).
const tradeLogos = await storage.open("tradelogos", { logos: (x) => x.id });
const tradeLogoOf = (id) => tradeLogos.data.logos.find((x) => x.id === id) || null;
async function setTradeLogo(id, body) {
  const type = String(body?.type || "");
  if (!["image/png", "image/jpeg", "image/webp", "image/svg+xml"].includes(type)) return { status: 400, error: "Use a PNG, JPG, WebP or SVG logo." };
  const data = Buffer.from(String(body?.data || ""), "base64");
  if (!data.length || data.length > 2_000_000) return { status: 400, error: "That logo is too big. Use one under 2 MB." };
  let png;
  try {
    const { default: sharp } = await import("sharp");
    png = await sharp(data, { density: 300 }).resize(256, 256, { fit: "inside", withoutEnlargement: false }).png().toBuffer();
  } catch {
    return { status: 400, error: "That file couldn't be opened as an image." };
  }
  const at = new Date().toISOString();
  tradeLogos.data.logos = tradeLogos.data.logos.filter((x) => x.id !== id);
  tradeLogos.data.logos.push({ id, data: png.toString("base64"), at });
  await tradeLogos.save();
  return { status: 200, at };
}
async function clearTradeLogo(id) {
  tradeLogos.data.logos = tradeLogos.data.logos.filter((x) => x.id !== id);
  await tradeLogos.save();
}
/* ── Samples for cafés ──────────────────────────────────────
   A café (a new one, mostly) asks for up to three of our coffees to try, from the portal's Samples
   tab: how they brew, delivered or picked up, a note. The team roasts and sends them from
   Wholesale › Samples (Requested → Roasting → Sent), and the café says how each one tasted, which
   the team sees beside the request. */
const cafeSamples = await storage.open("cafesamples", { requests: (x) => x.id });
const SAMPLE_STEPS = ["requested", "roasting", "sent", "tasted", "cancelled"];
const sampleCoffees = () => DATA.PRODUCTS.filter((x) => !x.hidden).map((x) => ({ id: x.id, name: x.short || x.name, notes: x.notes || "", roast: x.roast || x.type || "" }));
const sampleView = (r) => ({ id: r.id, coffees: r.coffees, brew: r.brew, how: r.how, location: r.location || "", note: r.note || "", status: r.status, by: r.by, at: r.at, sentAt: r.sentAt || null, feedback: r.feedback || null });
// The samples as an order in the queue: a 50g bag of each coffee, nothing to pay, no invoice.
async function sampleOrder(acct, r, locationId, by) {
  const lines = r.coffees.map((c) => ({ product: c.id, size: "250g", qty: 1 }));
  const priced = priceWholesale(acct, { lines, fulfilment: r.how === "pickup" ? "Pickup" : "Delivery", location: locationId || "", shipping: 0, notes: [`Samples (${r.brew}).`, r.note].filter(Boolean).join(" ") }, { local: true, quoted: lines.map((l) => ({ ...l, price: 0 })) });
  (priced as any).wholesale = { ...priced.wholesale, sample: r.id };
  // A sample is a 50g bag, not a retail bag (and isn't taken from the shelf's stock).
  for (const l of priced.lines as any[]) Object.assign(l, { size: "50g", variant: "50g sample · Whole Bean", price: 0 });
  const order = await orders.add(priced, { status: "new", payment: "paid", by });
  r.order = order.number;
  await cafeSamples.save();
  return order;
}
async function sampleOrderStatus(r, status, by, note) {
  const o = r.order && orders.get(r.order);
  if (o && OPEN_STATUSES.includes(o.status)) await orders.update(o.number, { status }, { by, note }).catch((error) => console.error("[samples] order:", error.message));
}
async function sampleRequested(acct, r) {
  const t = await todos.add({ title: `Roast samples for ${acct.business}`, description: [`${r.order ? `${r.order}: ` : ""}${r.coffees.map((c) => `50g ${c.name}`).join(", ")}`, `Brews ${r.brew}. ${r.how === "pickup" ? "Picking up." : `Deliver to ${r.location || "their address"}.`}`, r.note && `They wrote: ${r.note}`].filter(Boolean).join("\n"), link: { kind: "account", id: acct.id, label: acct.business } }, "samples");
  r.todoId = t.id;
  await cafeSamples.save();
  await notifyShop(DATA.SITE.wholesaleEmail, `Samples requested: ${acct.business}`, `${acct.business} asked to try ${r.coffees.map((c) => c.name).join(", ")} (${r.brew}). It's order ${r.order}, at no charge.\n${r.note ? `\n${r.note}\n` : ""}\nWholesale › Samples: ${SITE_URL}/admin/wholesale/samples`).catch(() => {});
}

// GET, POST (upload) or DELETE (remove) a café's logo; the same for the portal and the back office.
async function tradeLogoRoute(req, res, id, method, canChange = true) {
  if (method === "GET") {
    const l = tradeLogoOf(id);
    if (!l) return notFound(res);
    return send(res, 200, Buffer.from(l.data, "base64"), { "Content-Type": "image/png", "Cache-Control": "private, max-age=31536000, immutable", "X-Content-Type-Options": "nosniff" });
  }
  if (!canChange) return sendJson(res, 403, { error: "Ask the account owner to change the logo." });
  if (method === "DELETE") {
    await clearTradeLogo(id);
    return sendJson(res, 200, { logo: "" });
  }
  if (method === "POST") {
    let body;
    try {
      body = await readJson(req, 3_000_000);
    } catch {
      return sendJson(res, 413, { error: "That logo is too big. Use one under 2 MB." });
    }
    const r = await setTradeLogo(id, body);
    return r.error ? sendJson(res, r.status, { error: r.error }) : sendJson(res, 200, { logo: r.at });
  }
  return sendJson(res, 405, { error: "Not allowed." });
}
const CLAIM_PHOTO_MAX = 2_000_000;

const claimBy = (o) => {
  const d = deliveredAt(o);
  return d ? new Date(Date.parse(d) + CLAIM_DAYS() * 864e5).toISOString() : null;
};
// The lines a problem can still be reported for: coffee, tea, accessories and subscription boxes,
// less what's already been reported (and not declined). Delivered, within CLAIM_DAYS.
function claimableLines(o) {
  const by = claimBy(o);
  if (!by || Date.now() > Date.parse(by) || o.status !== "completed") return [];
  const told = new Map();
  for (const c of o.claims || []) if (c.status !== "declined") for (const i of c.items) told.set(i.index, (told.get(i.index) || 0) + i.qty);
  return o.lines.map((l, index) => ({ index, l, left: l.qty - (told.get(index) || 0) })).filter(({ l, left }) => ["coffee", "accessory", "sub"].includes(l.kind) && left > 0);
}
// Can it be refunded? Only a card payment the order took itself (a subscription box is billed by
// Square's invoices, so it's replaced instead).
const claimRefundable = (o) => Boolean(o.square?.paymentId) && o.source !== "wholesale" && chargeNow(o) - (o.refunded || 0) > 0.004;

function savePhoto(dataUrl) {
  const m = /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/.exec(String(dataUrl || ""));
  if (!m) throw new OrderError("Photos need to be JPEG, PNG or WebP.");
  if (m[2].length * 0.75 > CLAIM_PHOTO_MAX) throw new OrderError("One of the photos is too large.");
  const id = randomBytes(9).toString("base64url");
  claimPhotos.data.photos.push({ id, type: m[1], data: m[2], createdAt: new Date().toISOString() });
  return id;
}

async function startClaim(order, { items = [], problem = "", note = "", photos = [], want = "replace" }: any = {}, by = "customer") {
  const open = new Map<any, any>(claimableLines(order).map((x) => [x.index, x]));
  const picked = [];
  for (const it of [].concat(items)) {
    const x = open.get(Number(it.index));
    const qty = Math.round(Number(it.qty) || 0);
    if (!x || qty < 1 || qty > x.left) throw new OrderError("Choose what the problem is with.");
    picked.push({ index: x.index, qty, title: x.l.title, variant: x.l.variant, price: x.l.price });
  }
  if (!picked.length) throw new OrderError("Choose what the problem is with.");
  const kind = CLAIM_PROBLEMS[problem] ? problem : null;
  if (!kind) throw new OrderError("Tell us what happened.");
  const text = String(note || "").trim().slice(0, 1000);
  if (kind === "other" && !text) throw new OrderError("Tell us what happened.");
  const shots = [].concat(photos).slice(0, 4);
  if ((kind === "damaged" || kind === "wrong") && !shots.length) throw new OrderError("Add a photo, so we can see what happened.");
  const wholesale = order.source === "wholesale";
  const choice = wholesale ? "credit" : want === "refund" && claimRefundable(order) ? "refund" : "replace";
  const ids = shots.map(savePhoto);
  await claimPhotos.save();
  // What it's worth: for a refund, as a return would be (its share of a code, plus tax); for a
  // wholesale credit, what the account paid for it.
  const amount = wholesale ? round2(picked.reduce((n, i) => n + i.price * i.qty, 0)) : choice === "refund" ? returnValue(order, picked) : 0;
  const c = { id: `P${(order.claims || []).length + 1}`, code: randomBytes(12).toString("base64url"), items: picked, problem: kind, note: text, photos: ids, want: choice, amount, status: "open", createdAt: new Date().toISOString() };
  await orders.update(order.number, { claims: [...(order.claims || []), c] }, { by, note: `Problem reported (${CLAIM_PROBLEMS[kind].toLowerCase()}): ${picked.map((i) => `${i.qty} × ${i.title}`).join(", ")}. Wants ${choice === "credit" ? "a credit" : choice === "refund" ? "a refund" : "a replacement"}` });
  notifyShop(DATA.SITE.ordersEmail, `Problem reported on ${order.number}: ${CLAIM_PROBLEMS[kind]}`, `${order.contact.name} (${order.contact.email})\n${picked.map((i) => `${i.qty} × ${i.title} ${i.variant || ""}`).join("\n")}\n${text ? `\n“${text}”\n` : ""}\nThey'd like ${choice === "credit" ? `a credit of ${money(amount)}` : choice === "refund" ? `a refund of ${money(amount)}` : "a replacement"}.${ids.length ? ` ${ids.length} photo${ids.length === 1 ? "" : "s"}.` : ""}\n\n${SITE_URL}/admin/returns/${c.code}`).catch(() => {});
  if (emailConfigured()) {
    const first = firstName(order.contact.name);
    const msg = `Hi ${first},\n\nSorry about that. We've got your note about order ${order.number} (${picked.map((i) => `${i.qty} × ${i.title}`).join(", ")}) and we'll look at it today. We'll email you once ${choice === "credit" ? "the credit is on your account" : choice === "refund" ? "it's refunded" : "your replacement is on its way"}.`;
    sendOrderEmail({ to: order.contact.email, subject: `We're on it: order ${order.number}`, text: `${msg}\n\nMimi Food`, html: emailHtml(msg, "") }).catch((e) => console.error("[claims] email:", e.message));
  }
  return { order: orders.get(order.number), claim: c };
}

// The shop's answer: approve (as they asked, or another way: `want`) or decline with a note.
const resolving = new Set();
async function resolveClaim(code, { action, want = null, amount = null, note = "" }: any, by = "shop") {
  const order = orders.list({}).find((o) => (o.claims || []).some((c) => c.code === code));
  const c = order?.claims.find((x) => x.code === code);
  if (!c) throw new OrderError("Problem not found.");
  if (c.status !== "open") return { order, claim: c };
  if (resolving.has(code)) throw new OrderError("This one is being answered already.");
  resolving.add(code);
  try {
    const first = firstName(order.contact.name);
    const what = c.items.map((i) => `${i.qty} × ${i.title}`).join(", ");
    const said = String(note || "").trim().slice(0, 500);
    const done: any = { resolvedAt: new Date().toISOString(), answer: said };
    let msg = "";
    if (action === "decline") {
      if (!said) throw new OrderError("Add a note for the customer saying why.");
      done.status = "declined";
      msg = `Hi ${first},\n\nWe've looked at your note about order ${order.number} (${what}). ${said}\n\nQuestions? Just reply to this email.`;
    } else {
      const how = order.source === "wholesale" ? "credit" : want === "refund" && claimRefundable(order) ? "refund" : want === "replace" ? "replace" : c.want;
      const value = round2(Math.max(0, amount == null || amount === "" ? (how === "refund" && c.want !== "refund" ? returnValue(order, c.items) : c.amount) : Number(amount) || 0));
      if (how === "replace") {
        const lines = c.items.map((i) => ({ ...order.lines[i.index], qty: i.qty, price: 0 }));
        const sent = await sendReplacement(order, lines, { source: "replacement", note: `Replacement for ${order.number} (${CLAIM_PROBLEMS[c.problem].toLowerCase()})` });
        Object.assign(done, { status: "replaced", replacement: sent.number });
        msg = `Hi ${first},\n\nWe're sending you a replacement for ${what}, at no charge. It's order ${sent.number}; we'll email you when it ships.${said ? `\n\n${said}` : ""}`;
      } else if (how === "refund") {
        if (!(value > 0)) throw new OrderError("Enter the amount to refund.");
        const pay = round2(Math.min(value, chargeNow(order) - (order.refunded || 0)));
        const refund = await refundCard(order, pay, `Problem ${c.id}: ${what}`, { by, notify: false });
        Object.assign(done, { status: "refunded", refunded: pay, refundId: refund?.id || null });
        msg = `Hi ${first},\n\nWe've refunded ${money(pay)} for ${what} on order ${order.number}. It should appear on your statement within 5–10 business days.${said ? `\n\n${said}` : ""}`;
      } else {
        if (!(value > 0)) throw new OrderError("Enter the credit amount.");
        await trade.addCredit(order.wholesale.accountId, { amount: value, reason: `${CLAIM_PROBLEMS[c.problem]}: ${what}`, order: order.number });
        Object.assign(done, { status: "credited", credited: value });
        msg = `Hi ${first},\n\nWe've put ${money(value)} of credit on your account for ${what} on order ${order.number}. It comes off your next order.${said ? `\n\n${said}` : ""}`;
      }
    }
    const fresh = orders.get(order.number);
    // (A refund already wrote its own timeline line.)
    await orders.update(order.number, { claims: fresh.claims.map((x) => (x.code === code ? { ...x, ...done } : x)) }, { by, note: done.status === "refunded" ? undefined : `Problem ${c.id}: ${{ declined: "declined", replaced: `replacement ${done.replacement}`, refunded: `refunded ${money(done.refunded || 0)}`, credited: `${money(done.credited || 0)} account credit` }[done.status]}${said ? `. ${said}` : ""}` });
    if (emailConfigured()) await sendOrderEmail({ to: order.contact.email, subject: `About your order ${order.number}`, text: `${msg}\n\nMimi Food`, html: emailHtml(msg, "") }).catch((e) => console.error("[claims] email:", e.message));
    return { order: orders.get(order.number), claim: orders.get(order.number).claims.find((x) => x.code === code) };
  } finally {
    resolving.delete(code);
  }
}

const claimView = (c) => ({ id: c.id, items: c.items.map((i) => ({ title: i.title, variant: i.variant, qty: i.qty })), problem: CLAIM_PROBLEMS[c.problem], want: c.want, amount: c.amount, status: c.status, createdAt: c.createdAt, replacement: c.replacement || null, refunded: c.refunded ?? null, credited: c.credited ?? null, answer: c.status === "declined" ? c.answer : null });

// A delivery that came back (the carrier returned the parcel, or the courier brought it back):
// flagged once; the shop hears, the customer is asked to confirm their address or take a refund.
async function flagDeliveryIssue(order, kind, text, by = "system") {
  if (order.deliveryIssue || order.status === "cancelled") return order;
  const issue = { kind, text: String(text || "").slice(0, 200), at: new Date().toISOString(), status: "open" };
  const updated = await orders.update(order.number, { deliveryIssue: issue }, { by, note: kind === "courier" ? "The courier couldn't deliver it and is bringing it back" : `The carrier is sending it back to us${text ? `: ${text}` : ""}` });
  await notifyShop(DATA.SITE.ordersEmail, `Delivery failed: ${order.number}`, `${kind === "courier" ? "The courier couldn't deliver this order and is bringing it back." : `The carrier is sending this parcel back to us${text ? ` (${text})` : ""}.`}\n\nWe've asked ${order.contact.name} to confirm their address for a free reship, or take a refund. When it's back, put the stock back on the Stock page.\n\n${SITE_URL}/admin/orders/${order.number}`).catch(() => {});
  if (emailConfigured()) {
    const first = firstName(order.contact.name);
    const link = await trackUrl(updated);
    const msg = `Hi ${first},\n\n${kind === "courier" ? "Our courier couldn't deliver your order" : "The carrier couldn't deliver your order and is sending it back to us"}. Sorry about that.\n\nCheck your address and we'll send it again for free, or choose a refund. It takes a minute on your order page.`;
    await sendOrderEmail({ to: order.contact.email, subject: `We couldn't deliver order ${order.number}`, text: `${msg}\n\n${link}\n\nMimi Food`, html: emailHtml(msg, "", { href: link, label: "Choose What Happens" }) }).catch((e) => console.error("[delivery] email:", e.message));
  }
  return updated;
}

// What came back in this parcel: its own coffee and gear, their tax and share of a discount, and
// its shipping. Not gifts sent elsewhere, gift cards or class seats.
function parcelValue(order) {
  const sum = (lines) => lines.reduce((n, l) => n + l.price * l.qty, 0);
  const parcel = order.lines.filter((l) => ["coffee", "accessory"].includes(l.kind));
  const goods = sum(parcel);
  const all = sum(allLines(order).filter((l) => l.kind !== "sub"));
  const tax = parcel.reduce((n, l) => n + l.price * l.qty * (order.taxRates?.[DATA.taxClass(l)] || 0), 0);
  const ship = (order.shipping || 0) - (order.giftDeliveries || []).reduce((n, g) => n + (g.shipping || 0), 0);
  const off = all > 0 ? ((order.discount?.amount || 0) * goods) / all : 0;
  return round2(Math.max(0, goods + tax + ship - off));
}

// Reship (to the address on the order, or a corrected one) or refund what's left of it. One
// choice at a time per order, so a double tap can't reship twice.
const resolvingIssue = new Set();
async function resolveDeliveryIssue(order, input: any, by = "customer") {
  if (resolvingIssue.has(order.number)) throw new OrderError("That's already going through.");
  resolvingIssue.add(order.number);
  try {
    return await resolveDeliveryIssueNow(orders.get(order.number) || order, input, by);
  } finally {
    resolvingIssue.delete(order.number);
  }
}
async function resolveDeliveryIssueNow(order, { choice, address = null }: any, by = "customer") {
  const issue = order.deliveryIssue;
  if (!issue || issue.status !== "open") throw new OrderError("There's nothing to sort out on this order.");
  if (choice === "refund") {
    const left = round2(Math.min(parcelValue(order), chargeNow(order) - (order.refunded || 0)));
    if (!(left > 0) || !order.square?.paymentId) throw new OrderError("This order can't be refunded here. Reply to our email and we'll sort it out.");
    await refundCard(order, left, "Delivery failed", { by, notify: true, shown: "Your order couldn't be delivered." });
    await orders.update(order.number, { deliveryIssue: { ...issue, status: "refunded", resolvedAt: new Date().toISOString() } }, { by, note: `Refunded ${money(left)}: delivery failed` });
    return orders.get(order.number);
  }
  if (choice !== "reship") throw new OrderError("Choose reship or refund.");
  let shipTo = order.shipTo;
  if (address) {
    const to = { address: String(address.address || "").trim().slice(0, 160), city: String(address.city || "").trim().slice(0, 80), state: String(address.state || "").trim().toUpperCase().slice(0, 2), postcode: String(address.postcode || "").trim().slice(0, 10) };
    if (!to.address || !to.city || !to.state || !to.postcode) throw new OrderError("Enter the full address.");
    const found: any = await checkAddress(to);
    if (found.status === "invalid") throw new OrderError(found.message || "We couldn't find that address. Check it and try again.");
    shipTo = { ...order.shipTo, ...to, ...(found.status === "corrected" ? found.address : {}) };
  }
  const lines = order.lines.filter((l) => ["coffee", "accessory", "sub"].includes(l.kind)).map((l) => ({ ...l, price: 0 }));
  if (!lines.length) throw new OrderError("Reply to our email and we'll sort it out.");
  const again = await sendReplacement({ ...order, shipTo }, lines, { source: "reship", note: `Reship of ${order.number} (couldn't be delivered)` });
  await orders.update(order.number, { deliveryIssue: { ...issue, status: "reshipped", reship: again.number, resolvedAt: new Date().toISOString() } }, { by, note: `Reshipped as ${again.number}${address ? " to a corrected address" : ""}` });
  return orders.get(order.number);
}

// A mail return's progress, from Shippo (its webhook, or the 15-minute check when that's quiet):
// the customer hears at its first scan and when it arrives; the shop hears when it arrives.
async function applyReturnTracking(o, r, state) {
  state = String(state || "").toUpperCase();
  if (r.arrivedAt) return;
  if (state === "TRANSIT" && !r.label.scannedAt) {
    await orders.update(o.number, { returns: o.returns.map((x) => (x.id === r.id ? { ...x, label: { ...x.label, scannedAt: new Date().toISOString() } } : x)) }, { by: "shippo", note: `Return ${r.id} on its way back` });
    await emailReturnStep(orders.get(o.number), r, "transit").catch((e) => console.error("[returns] transit email:", e.message));
    return;
  }
  if (state !== "DELIVERED") return;
  await orders.update(o.number, { returns: o.returns.map((x) => (x.id === r.id ? { ...x, arrivedAt: new Date().toISOString(), label: { ...x.label, scannedAt: x.label.scannedAt || new Date().toISOString() } } : x)) }, { by: "shippo", note: `Return ${r.id} delivered to the shop` });
  await emailReturnStep(orders.get(o.number), r, "arrived").catch((e) => console.error("[returns] arrived email:", e.message));
  await notifyShop(DATA.SITE.ordersEmail, `Return arrived for ${o.number}`, `${r.items.map((i) => `${i.qty} × ${i.title}`).join("\n")}\n\nCheck it, then scan the QR code in the box or check it in: ${SITE_URL}/admin/returns/${r.code}`);
}
// Shippo's webhook can be missed: every 15 minutes, open mail returns not looked at for 6 hours
// are looked up, and so are shipped parcels (so one the carrier sends back is caught too).
async function trackingSweep() {
  if (!shippo.shippoConfigured()) return;
  const stale = (iso, hours) => !iso || Date.now() - Date.parse(iso) > hours * 3600e3;
  for (const o of orders.list({})) {
    for (const r of o.returns || []) {
      if (r.status !== "open" || r.method !== "mail" || !r.label?.trackingNumber || r.label.voided || r.arrivedAt || !stale(r.label.checkedAt, 6)) continue;
      try {
        const t = await shippo.track(r.label.carrier, r.label.trackingNumber);
        const fresh = orders.get(o.number);
        await orders.update(o.number, { returns: fresh.returns.map((x) => (x.id === r.id ? { ...x, label: { ...x.label, checkedAt: new Date().toISOString() } } : x)) }, { by: "system" });
        if (t.status === "transit" || t.status === "out_for_delivery") await applyReturnTracking(orders.get(o.number), orders.get(o.number).returns.find((x) => x.id === r.id), "TRANSIT");
        if (t.status === "delivered") await applyReturnTracking(orders.get(o.number), orders.get(o.number).returns.find((x) => x.id === r.id), "DELIVERED");
      } catch (error) {
        console.error(`[returns] track ${o.number} ${r.id}:`, error.message);
      }
    }
    // Labeled but not marked shipped yet counts too: the first scan moves it along.
    if (["new", "packed", "shipped"].includes(o.status) && o.tracking?.number && !o.deliveryIssue && stale(o.tracking.checkedAt, 6)) await refreshParcel(o, "system").catch((e) => console.error(`[tracking] ${o.number}:`, e.message));
  }
}

// The tracking page: the order's link from its emails (?t=), or the signed-in customer's own.
// A courier on the move, or a parcel not looked at for half an hour, is looked up first.
// The order's own link (its token), or the account it belongs to.
function trackAllowed(req, order, token = "") {
  if (!order || order.status === "pending_payment") return false;
  const user = accounts.userFromToken(cookie(req, SESSION_COOKIE));
  token = String(token || "");
  return Boolean((order.trackToken && token.length > 10 && token === order.trackToken) || (user && (order.userId === user.id || (user.verified && order.contact?.email === user.email))));
}

// An order number as a customer might type it ("50D118", "as50d118", "#MF-50D118"): MF-50D118.
const orderNumberOf = (input) => {
  const raw = String(input || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const code = raw.startsWith("AS") && raw.length > 2 && orders.get(`MF-${raw.slice(2)}`) ? raw.slice(2) : raw;
  return /^[A-Z0-9]{1,12}$/.test(code) ? `MF-${code}` : "";
};

// The tracking page without its link: the order number and the email it was placed with.
async function handleTrackLookup(req, res) {
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "track-lookup", 10)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  const body = await readJson(req).catch(() => ({}));
  const number = orderNumberOf(body?.number);
  const email = String(body?.email || "").trim().toLowerCase();
  const order = number ? orders.get(number) : null;
  if (!order || order.status === "pending_payment" || String(order.contact?.email || "").toLowerCase() !== email) {
    return sendJson(res, 404, { error: "No order with that number and email." });
  }
  return sendJson(res, 200, { url: (await trackUrl(order)).replace(SITE_URL, "") });
}

async function handleTrack(req, res, url, number) {
  if (rateLimited(clientIp(req), "track", 120)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let order = orders.get(number);
  if (!trackAllowed(req, order, url.searchParams.get("t"))) return sendJson(res, 404, { error: "Order not found. Check your email link." });
  const age = (iso) => (iso ? Date.now() - Date.parse(iso) : Infinity);
  try {
    const c = order.courier;
    if (c?.id && couriers.PROVIDERS[c.provider]?.configured() && !["delivered", "cancelled", "returned", "failed"].includes(c.status) && age(c.updatedAt) > 60e3) {
      order = await applyCourier(order, await couriers.PROVIDERS[c.provider].get(c.id), "system");
    }
    if (order.tracking?.number && order.status !== "completed" && order.status !== "cancelled" && age(order.tracking.checkedAt) > 30 * 60e3) order = await refreshParcel(order, "system");
  } catch (error) {
    console.warn(`[tracking] ${number}: ${error.message}`);
  }
  sendJson(res, 200, { order: trackView(order) }, { "Cache-Control": "no-store" });
}

// The QR code staff scan: it opens the return in the back office.
async function sendReturnQr(res, code) {
  if (!orders.list({}).some((o) => (o.returns || []).some((r) => r.code === code))) return notFound(res);
  const png = await QRCode.toBuffer(`${SITE_URL}/admin/returns/${code}`, { margin: 1, width: 360 });
  send(res, 200, png, { "Content-Type": "image/png", "Cache-Control": "private, max-age=86400" });
}

// The days USPS can collect a return: the next six it delivers on (not Sundays), from tomorrow,
// in Los Angeles time ("YYYY-MM-DD").
function pickupDays() {
  const days = [];
  for (let i = 1; days.length < 6 && i < 10; i++) {
    const d = new Date(Date.now() + i * 864e5);
    const ymd = d.toLocaleDateString("en-CA", { timeZone: "America/Los_Angeles" });
    if (new Date(`${ymd}T12:00:00Z`).getUTCDay() !== 0) days.push(ymd);
  }
  return days;
}
// Where on the property USPS picks it up (Shippo's names).
const PICKUP_SPOTS = ["Front Door", "Back Door", "Side Door", "Knock on Door", "In/At Mailbox", "Mail Room", "Office", "Reception", "Other"];

// POST /api/track/<order>/return/<id>/pickup { t, day, spot, note }: USPS collects the return from
// the address on the order, on that day. Booked once; the customer gets an email with it.
async function handleReturnPickup(req, res, number, rid) {
  if (req.method !== "POST") return sendJson(res, 405, { error: "Method not allowed." });
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "return-pickup", 6)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  const body = await readJson(req).catch(() => ({}));
  const order = orders.get(number);
  if (!trackAllowed(req, order, body.t)) return sendJson(res, 404, { error: "Order not found. Check your email link." });
  const r = (order.returns || []).find((x) => x.id === rid && x.status === "open");
  if (!r?.label?.doorPickup || r.label.voided) return sendJson(res, 400, { error: "This return can't be picked up. Drop it off instead." });
  if (r.pickup) return sendJson(res, 200, { order: trackView(order) });
  const day = String(body.day || "");
  if (!pickupDays().includes(day)) return sendJson(res, 400, { error: "Choose a day." });
  const spot = PICKUP_SPOTS.includes(body.spot) ? body.spot : "Front Door";
  const note = String(body.note || "").trim().slice(0, 200);
  if (spot === "Other" && !note) return sendJson(res, 400, { error: "Tell the carrier where to find it." });
  const at = { ...labelShipTo(order), email: order.contact.email, phone: labelShipTo(order).phone || order.contact.phone || DATA.SITE.shipFrom?.phone || "" };
  try {
    const p = await shippo.schedulePickup({ transactionId: r.label.shipmentId, carrierAccount: r.label.carrierAccount, at, day, spot, instructions: note });
    const pickup = { ...p, day, spot, note, bookedAt: new Date().toISOString() };
    await orders.update(order.number, { returns: order.returns.map((x) => (x.id === r.id ? { ...x, pickup } : x)) }, { by: "customer", note: `Return ${r.id}: USPS pickup booked for ${day}${p.confirmation ? ` (${p.confirmation})` : ""}` });
    const updated = orders.get(order.number);
    emailReturnStep(updated, { ...r, pickup }, "pickup").catch((e) => console.error("[returns] pickup email:", e.message));
    return sendJson(res, 200, { order: trackView(updated) });
  } catch (error) {
    console.error(`[returns] ${order.number} pickup:`, error.message);
    return sendJson(res, 502, { error: "USPS couldn't book that pickup. Try another day, or drop it off at a Post Office." });
  }
}

// POST /api/track/<order>/problem { t, items, problem, note, photos, want }: Report a Problem.
// POST /api/track/<order>/delivery { t, choice: reship|refund, address? }: a delivery that failed.
async function handleTrackProblem(req, res, number, kind) {
  if (req.method !== "POST") return sendJson(res, 405, { error: "Method not allowed." });
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), `track-${kind}`, 8)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body;
  try {
    body = await readJson(req, kind === "problem" ? 4 * CLAIM_PHOTO_MAX * 1.4 + 20_000 : LIMITS.bodyBytes);
  } catch {
    return sendJson(res, 400, { error: kind === "problem" ? "Those photos are too large. Try fewer, or smaller ones." : "Couldn't read that request." });
  }
  const order = orders.get(number);
  if (!trackAllowed(req, order, body.t)) return sendJson(res, 404, { error: "Order not found. Check your email link." });
  try {
    if (kind === "problem") await startClaim(order, body);
    else await resolveDeliveryIssue(order, body);
    return sendJson(res, 200, { order: trackView(orders.get(number)) });
  } catch (error) {
    if (error instanceof OrderError) return sendJson(res, 400, { error: error.message });
    console.error(`[${kind}] ${number}:`, error.message);
    return sendJson(res, 502, { error: "That didn't go through. Try again, or reply to your order email." });
  }
}

async function handleReturnStart(req, res, number) {
  if (req.method !== "POST") return sendJson(res, 405, { error: "Method not allowed." });
  if (!isJsonRequest(req)) return sendJson(res, 415, { error: "Something went wrong. Try again." });
  if (rateLimited(clientIp(req), "return", 10)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body;
  try {
    body = await readJson(req);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that request." });
  }
  const order = orders.get(number);
  if (!trackAllowed(req, order, body.t)) return sendJson(res, 404, { error: "Order not found. Check your email link." });
  try {
    const { order: updated } = await startReturn(order, body);
    return sendJson(res, 200, { order: trackView(updated) });
  } catch (error) {
    if (error instanceof OrderError) return sendJson(res, 400, { error: error.message });
    throw error;
  }
}

// Shippo's track_updated webhook: look the parcel up again (the body is only a hint).
// With SHIPPO_WEBHOOK_SECRET set, the webhook URL needs ?token=<it>.
async function handleShippoWebhook(req, res, url) {
  const secret = process.env.SHIPPO_WEBHOOK_SECRET;
  if (secret && url.searchParams.get("token") !== secret) return send(res, 401, "Unauthorized");
  if (rateLimited(clientIp(req), "shippo-hook", 300)) return sendJson(res, 429, { error: "Slow down." });
  let event: any = {};
  try {
    event = JSON.parse(await readRaw(req));
  } catch {
    return send(res, 400, "Bad request");
  }
  const number = String(event.data?.tracking_number || "").trim();
  const matches = number ? orders.list().filter((o) => o.tracking?.number === number) : [];
  for (const o of matches) await refreshParcel(o).catch((e) => console.error(`[tracking] ${o.number}:`, e.message));
  // A return on its way back.
  for (const o of number ? orders.list({}) : []) {
    const r = (o.returns || []).find((x) => x.status === "open" && x.label?.trackingNumber === number);
    if (r) await applyReturnTracking(o, r, event.data?.tracking_status?.status);
  }
  sendJson(res, 200, { received: true });
}

async function handleUberWebhook(req, res) {
  const raw = await readRaw(req);
  if (!uber.verifyWebhook(raw, req.headers["x-uber-signature"] || req.headers["x-postmates-signature"])) return send(res, 401, "Unauthorized");
  let event;
  try {
    event = JSON.parse(raw);
  } catch {
    return send(res, 400, "Bad request");
  }
  const d = event.data || {};
  const id = String(event.delivery_id || d.id || "");
  const order = orders.find((o) => o.courier?.provider === "uber" && o.courier?.id === id);
  if (!order) return sendJson(res, 200, { received: true });
  await applyCourier(order, { status: uber.STATUS[event.status || d.status], trackingUrl: d.tracking_url, dasher: d.courier?.name, dasherPhone: d.courier?.phone_number, courierAt: uber.courierAt(d.courier), dropoffEta: d.dropoff_eta, pickupEta: d.pickup_eta }, "uber");
  sendJson(res, 200, { received: true });
}

async function handlePromoPreview(req, res) {
  // Few tries per visitor, so codes can't be guessed by brute force.
  if (rateLimited(clientIp(req), "promo", 15)) return sendJson(res, 429, { error: "Too many tries. Try again soon." });
  let body: any = {};
  try {
    body = await readJson(req);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that code." });
  }
  try {
    const d = promos.apply(String(body.code || "").slice(0, 40), { eligible: Math.max(0, Number(body.eligible) || 0), shipping: Math.max(0, Number(body.shipping) || 0), today: shopToday() });
    return sendJson(res, 200, d);
  } catch (error) {
    if (error instanceof PromoError) return sendJson(res, 400, { error: error.message });
    throw error;
  }
}

async function handleDeliveryZone(req, res) {
  if (rateLimited(clientIp(req), "geo", 20)) return sendJson(res, 429, { error: "Too many address checks." });
  let body: any = {};
  try {
    body = await readJson(req);
  } catch {
    return sendJson(res, 400, { error: "Couldn't read that address." });
  }
  const shipTo = Object.fromEntries(["address", "city", "state", "postcode"].map((k) => [k, String(body?.[k] ?? "").trim().slice(0, 120)]));
  if (!shipTo.address || !shipTo.city) return sendJson(res, 400, { error: "Add the street and city." });
  const miles = await localMiles(shipTo);
  const local = miles != null && miles <= LOCAL.radiusMiles;
  const pick = local ? await courierChoice(shipTo) : null;
  // The courier's fee is the customer's delivery fee (see courierFee).
  // The courier's drive time, from its quote's drop-off estimate (for "Arrives about …").
  const eta = pick?.dropoffEta ? Math.round((Date.parse(pick.dropoffEta) - Date.now()) / 60e3) : NaN;
  sendJson(res, 200, { found: miles != null, miles, local: local && Boolean(pick), radiusMiles: LOCAL.radiusMiles, courier: pick ? couriers.providerName(pick.provider) : null, provider: pick?.provider || null, fee: pick ? courierFee(pick) : null, minutes: eta > 0 && eta < 240 ? eta : null });
}

/* ── Square webhooks ───────────────────────────────────────── */

async function readRaw(req, limit = 512_000) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new Error("too large");
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString("utf8");
}

// A subscription invoice was paid: after the first one, each is a delivery to pack.
async function subscriptionBilled(inv) {
  const found = await accounts.billed(inv.subscription_id, inv.id);
  if (!found || !found.user) return;
  const { sub, user } = found;
  const line = { kind: "sub", title: sub.gift ? `${sub.coffeeLabel} Subscription, gift for ${sub.recipient}` : `${sub.coffeeLabel} Subscription`, variant: [sub.sizeLabel, sub.grind, sub.freqLabel].filter(Boolean).join(" · "), note: sub.note || "", gift: sub.gift, qty: 1, price: sub.price, sub: { coffee: sub.coffee, size: sub.size, freq: sub.freq, grind: sub.grind || "" } };
  const total = sq.fromMoney(inv.payment_requests?.[0]?.total_completed_amount_money) || sub.price;
  const routed = await routeDelivery({ contact: { name: user.name, email: user.email, phone: sub.phone || "" }, lines: [line], fulfilment: "Delivery", shipTo: sub.shipTo, cafe: null, notes: "", subtotal: total, shipping: 0, cafeFee: 0, total, userId: null, source: "renewal", square: { invoiceId: inv.id, subscriptionId: inv.subscription_id, orderId: inv.order_id || null } });
  const order = await orders.add(routed, { status: "new", payment: "paid", by: "square" });
  console.log(`[orders] ${order.number} subscription renewal`);
  autoLabel(order.number).catch((e) => console.error("[labels]", e.message));
  await notifyShop(DATA.SITE.ordersEmail, `Subscription delivery ${order.number}: ${sub.coffeeLabel}, ${sub.sizeLabel}`, orderText(order));
}

// A wholesale payment that was processing (a bank payment) settled or failed. True if it was one.
async function wholesalePaymentChanged(p) {
  const order = orders.find((o) => o.source === "wholesale" && o.square?.paymentId === p.id);
  if (!order) return false;
  if (p.status === "COMPLETED" && order.payment !== "paid") {
    await orders.update(order.number, { payment: "paid", wholesale: { ...order.wholesale, processing: null, declined: null } }, { by: "square", note: "Bank payment cleared" });
  } else if ((p.status === "FAILED" || p.status === "CANCELED") && order.payment !== "paid") {
    await orders.update(order.number, { wholesale: { ...order.wholesale, processing: null, declined: { at: new Date().toISOString(), message: "Bank payment failed" } } }, { by: "square", note: "Bank payment failed" });
  }
  return true;
}

// A wholesale invoice changed in Square (its invoice number is our order number): Square is the
// record, so the order follows it. Paid, cancelled, refunded, or a scheduled charge declined.
async function wholesaleInvoiceChanged(inv, type) {
  if (await editInvoiceChanged(inv, type)) return;
  const order = orders.find((o) => o.source === "wholesale" && (o.wholesale?.invoice?.id === inv.id || o.number === inv.invoice_number));
  // An invoice cancelled before the order was reopened is history: it changes nothing now.
  if (!order || (order.wholesale.voided || []).some((v) => v.id === inv.id)) return;
  const name = `Invoice ${inv.invoice_number || inv.id}`;
  const balance = inv.payment_requests?.[0];
  const fullyPaid = inv.status === "PAID" || (type === "invoice.payment_made" && (!balance || sq.fromMoney(balance.total_completed_amount_money) + 0.005 >= sq.fromMoney(balance.computed_amount_money)));
  if (fullyPaid && order.payment !== "paid") {
    await orders.update(order.number, { payment: "paid", wholesale: { ...order.wholesale, declined: null } }, { by: "square", note: `${name} paid` });
  } else if (inv.status === "CANCELED" && order.status !== "cancelled" && order.payment !== "paid") {
    await orders.update(order.number, { status: "cancelled" }, { by: "square", note: `${name} cancelled in Square` });
    await cancelUnderway(order.number);
  } else if (inv.status === "REFUNDED" && order.payment !== "refunded") {
    await orders.update(order.number, { payment: "refunded" }, { by: "square", note: `${name} refunded` });
  } else if (inv.status === "PARTIALLY_REFUNDED" && order.payment !== "partially_refunded") {
    await orders.update(order.number, { payment: "partially_refunded" }, { by: "square", note: `${name} partly refunded` });
  } else if ((type === "invoice.scheduled_charge_failed" || inv.status === "FAILED") && order.payment !== "paid") {
    await orders.update(order.number, { wholesale: { ...order.wholesale, declined: { at: new Date().toISOString(), message: "Payment declined" } } }, { by: "square", note: `${name}: payment declined` });
  }
}

// Refunds made in the Square dashboard show up on the order too.
async function refundUpdated(r) {
  if (r.status !== "COMPLETED") return;
  const order = orders.find((o) => o.square?.paymentId === r.payment_id);
  if (!order) return;
  const refunds: Record<string, any> = { ...(order.square.refunds || {}), [r.id]: sq.fromMoney(r.amount_money) };
  const refunded = round2(Object.values(refunds).reduce((n, x) => n + x, 0));
  if (Math.abs((order.refunded || 0) - refunded) < 0.005 && order.square.refunds?.[r.id] !== undefined) return;
  await orders.update(order.number, { refunded, payment: refunded >= chargeNow(order) - 0.005 ? "refunded" : "partially_refunded", square: { ...order.square, refunds } }, { by: "square", note: `Refunded ${money(refunded)} in total` });
}

async function handleSquareWebhook(req, res) {
  if (!squareConfigured()) return send(res, 404, "Not found");
  let raw;
  try {
    raw = await readRaw(req);
  } catch {
    return send(res, 413, "Too large");
  }
  const event = sq.verifyWebhook(raw, req.headers["x-square-hmacsha256-signature"], process.env.SQUARE_WEBHOOK_URL || `${SITE_URL}/api/square/webhook`);
  if (!event) return send(res, 403, "Bad signature");
  try {
    const obj = event.data?.object || {};
    if (event.type === "invoice.payment_made" && obj.invoice?.subscription_id) await subscriptionBilled(obj.invoice);
    else if (event.type === "invoice.scheduled_charge_failed" && obj.invoice?.subscription_id) await subscriptionPaymentFailed(obj.invoice.id, obj.invoice.subscription_id);
    else if (/^invoice\.(payment_made|canceled|refunded|updated|scheduled_charge_failed)$/.test(event.type) && obj.invoice && !obj.invoice.subscription_id) await wholesaleInvoiceChanged(obj.invoice, event.type); else if ((event.type === "refund.created" || event.type === "refund.updated") && obj.refund) await refundUpdated(obj.refund);
    else if ((event.type === "subscription.updated" || event.type === "subscription.created") && obj.subscription?.status === "CANCELED") {
      const sub = await accounts.endedInSquare(obj.subscription.id);
      if (sub) await notifyShop(DATA.SITE.ordersEmail, `Subscription ended in Square: ${sub.coffeeLabel}`, "Square ended this subscription. It's now cancelled in the customer's account.");
    } else if (event.type === "payment.updated" && obj.payment && (await wholesalePaymentChanged(obj.payment))) {
      // A wholesale bank payment settled or failed (handled above).
    } else if (event.type === "payment.updated" && obj.payment?.status === "FAILED" && obj.payment.invoice_id) {
      await notifyShop(DATA.SITE.ordersEmail, "A subscription payment failed", `Square couldn't charge the card for invoice ${obj.payment.invoice_id}. Square will retry and email the customer; check the Square dashboard.`);
      await subscriptionPaymentFailed(obj.payment.invoice_id);
    }
  } catch (error) {
    console.error(`[square] ${event.type} failed:`, error);
    return send(res, 500, "Failed"); // Square retries
  }
  sendJson(res, 200, { received: true });
}

// A coffee's or tea's price changed (in the back office, or a sale starting or ending): its
// Square-billed subscriptions move to the new price from their next billing, and each subscriber
// is told. A subscription billed before this was kept is read from Square once.
var repricing = null; // var: syncCatalog may call repriceSoon before this line runs
var repriceAgain = false;
function repriceSoon() {
  if (!squareConfigured()) return;
  if (repricing) return void (repriceAgain = true);
  repricing = setTimeout(async () => {
    try {
      await repriceSubscriptions();
    } catch (error) {
      console.error("[subscriptions] reprice:", error.message);
    } finally {
      repricing = null;
      if (repriceAgain) {
        repriceAgain = false;
        repriceSoon();
      }
    }
  }, 5000);
}
async function repriceSubscriptions() {
  for (const sub of accounts.squareBilled()) {
    const now = accounts.priceNow(sub);
    if (now == null) continue; // no longer sold: left as it is
    try {
      const was = sub.billedPrice ?? (await sq.subscriptionBilled(sub.squareSubscriptionId));
      if (was == null) continue;
      if (Math.round(was * 100) === Math.round(now * 100)) {
        if (sub.billedPrice == null) await accounts.setBilledPrice(sub.id, was);
        continue;
      }
      const coffee = DATA.subscriptionCoffee(sub.coffee);
      const size = DATA.SUBSCRIPTION.sizes.find((x) => x.id === sub.size);
      const planVariationId = await sq.planVariation({ coffee, size, freq: sub.freq, price: now, currency: CURRENCY(), cache: planCache });
      await square("POST", `subscriptions/${encodeURIComponent(sub.squareSubscriptionId)}/swap-plan`, { new_plan_variation_id: planVariationId });
      await accounts.setBilledPrice(sub.id, now);
      console.log(`[subscriptions] ${sub.id} ${coffee.label}: ${money(was)} → ${money(now)}`);
      const who = accounts.customer(sub.userId);
      if (who?.email && emailConfigured()) {
        const first = firstName(String(who.name || ""));
        const text = `${first ? `Hi ${first},\n\n` : ""}The price of ${coffee.label} has changed, so your subscription is now ${money(now)} a delivery (it was ${money(was)}), from your next billing. Nothing else changes.\n\nYou can change, skip or cancel it any time from your account.`;
        await sendOrderEmail({ to: who.email, subject: `Your ${DATA.SITE.name} subscription price`, text: `${text}\n${SITE_URL}/account\n\n${DATA.SITE.name}`, html: emailHtml(text, "", { href: `${SITE_URL}/account`, label: "Your Account" }) }).catch((e) => console.error("[subscriptions] price email:", e.message));
      }
    } catch (error) {
      console.error(`[subscriptions] couldn't reprice ${sub.id}:`, error.message);
    }
  }
}

// Keeps a Square-billed subscription in step when the customer (or the shop) changes it.
async function syncSubscription(sub, action, details, { price }) {
  if (!sub.squareSubscriptionId || !squareConfigured()) return;
  const id = encodeURIComponent(sub.squareSubscriptionId);
  try {
    if (action === "pause") await square("POST", `subscriptions/${id}/pause`, { pause_reason: "Paused from the account page" });
    else if (action === "resume") await square("POST", `subscriptions/${id}/resume`, { resume_change_timing: "IMMEDIATE" });
    else if (action === "cancel") await square("POST", `subscriptions/${id}/cancel`, {});
    else if (action === "skip") await square("POST", `subscriptions/${id}/pause`, { pause_cycle_duration: 1, pause_reason: "Skipped the next delivery" });
    else if (action === "change") {
      const S = DATA.SUBSCRIPTION;
      const coffee = DATA.subscriptionCoffee(details.coffee);
      const size = S.sizes.find((x) => x.id === details.size);
      const planVariationId = await sq.planVariation({ coffee, size, freq: details.freq, price, currency: CURRENCY(), cache: planCache });
      await square("POST", `subscriptions/${id}/swap-plan`, { new_plan_variation_id: planVariationId });
    }
  } catch (error) {
    console.error("[square] subscription update failed:", error.message);
    throw new AccountError("We couldn't update your billing just now. Please try again in a moment.", 502);
  }
}

// A tea's lid label to print (Products → Tea → Lid Label): a true-size page, or ?format=svg.
function handleLidLabel(req, res, url, id) {
  if (rateLimited(clientIp(req), "admin", 10)) return send(res, 429, "Too many attempts.");
  if (!adminCan(req, url, "products")) return send(res, 404, "Not found");
  const tea = catalog.adminView().teas.find((t) => t.id === id);
  if (!tea) return send(res, 404, "Not found");
  const opts = { brew: DATA.BREW_GUIDES?.Tea, brand: DATA.SITE.name, guides: url.searchParams.get("guides") === "1" };
  const headers = { "Cache-Control": "no-store", "X-Robots-Tag": "noindex" };
  if (url.searchParams.get("format") === "svg") {
    const file = `${String(tea.short || tea.id).toLowerCase().replace(/[^a-z0-9]+/g, "-")}-lid-label${opts.guides ? "-proof" : ""}.svg`;
    return send(res, 200, lidLabelSvg(tea, opts), { ...headers, "Content-Type": "image/svg+xml; charset=utf-8", "Content-Disposition": `attachment; filename="${file}"` });
  }
  return send(res, 200, lidLabelPage(tea, opts), { ...headers, "Content-Type": "text/html; charset=utf-8" });
}

